from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return [[0]]
    w = len(grid[0])
    if w == 0:
        return [[0]]

    start = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                start = (r, c)
                break
        if start is not None:
            break

    if start is None:
        return [[0]]

    sr, sc = start
    target = int(grid[sr][sc])

    q = deque([(sr, sc)])
    seen = {(sr, sc)}
    min_r = max_r = sr
    min_c = max_c = sc

    while q:
        r, c = q.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                if int(grid[nr][nc]) == target:
                    seen.add((nr, nc))
                    q.append((nr, nc))
                    if nr < min_r:
                        min_r = nr
                    if nr > max_r:
                        max_r = nr
                    if nc < min_c:
                        min_c = nc
                    if nc > max_c:
                        max_c = nc

    out_h = max_r - min_r + 1
    out_w = max_c - min_c + 1
    result = [[0] * out_w for _ in range(out_h)]

    for r, c in seen:
        result[r - min_r][c - min_c] = target

    return result

