import itertools

def transform(grid: list[list[int]]) -> list[list[int]]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    twos = []
    fours = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                twos.append((r, c))
            elif grid[r][c] == 4:
                fours.append((r, c))

    if not twos or not fours:
        return [list(row) for row in grid]

    def on_segment(p, a, b):
        pr, pc = p
        ar, ac = a
        br, bc = b

        # Check collinearity using a 2D cross product.
        if (pr - ar) * (bc - ac) - (pc - ac) * (br - ar) != 0:
            return False

        # Check that p is inside the bounding box of the segment.
        return (min(ar, br) <= pr <= max(ar, br) and
                min(ac, bc) <= pc <= max(ac, bc))

    keep_fours = False

    for a, b in itertools.combinations(twos, 2):
        for p in fours:
            if on_segment(p, a, b):
                keep_fours = True
                break
        if keep_fours:
            break

    result = [[0] * cols for _ in range(rows)]

    if keep_fours:
        for r, c in fours:
            result[r][c] = 4
    else:
        for r, c in twos:
            result[r][c] = 2

    return result

