def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]

    cells = {}
    for r in range(h):
        for c in range(w):
            v = int(grid[r][c])
            if v != 0:
                cells.setdefault(v, []).append((r, c))

    if not cells:
        return out

    counts = {color: len(points) for color, points in cells.items()}

    # The intended rule:
    # There is a singleton object and a set of anchor objects.
    # Keep the singleton iff it lies inside the inclusive axis-aligned
    # bounding box of the anchors; otherwise keep the anchors.
    singleton_color = None
    for color in sorted(counts):
        if counts[color] == 1:
            singleton_color = color
            break

    if singleton_color is None:
        singleton_color = min(counts, key=lambda color: (counts[color], color))

    other_colors = [color for color in counts if color != singleton_color]

    if not other_colors:
        keep_colors = {singleton_color}
    else:
        # Prefer the color that appears exactly twice as the anchor color.
        anchor_color = None
        for color in sorted(other_colors):
            if counts[color] == 2:
                anchor_color = color
                break

        if anchor_color is None:
            anchor_color = max(other_colors, key=lambda color: (counts[color], -color))

        anchor_pts = cells[anchor_color]
        min_r = min(r for r, _ in anchor_pts)
        max_r = max(r for r, _ in anchor_pts)
        min_c = min(c for _, c in anchor_pts)
        max_c = max(c for _, c in anchor_pts)

        singleton_pts = cells[singleton_color]
        inside = all(
            min_r <= r <= max_r and min_c <= c <= max_c
            for r, c in singleton_pts
        )

        keep_colors = {singleton_color} if inside else {anchor_color}

    for r in range(h):
        for c in range(w):
            v = int(grid[r][c])
            if v in keep_colors:
                out[r][c] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [[int(x) for x in row] for row in grid]
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return grid

    result = [row[:] for row in grid]

    ones = []
    twos = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                ones.append((r, c))
            elif grid[r][c] == 2:
                twos.append((r, c))

    if not ones or not twos:
        return result

    # Identify the straight 2-wall.
    full_rows = [r for r in range(H) if all(grid[r][c] == 2 for c in range(W))]
    full_cols = [c for c in range(W) if all(grid[r][c] == 2 for r in range(H))]

    if len(full_rows) == 1:
        axis = "h"
        coord = full_rows[0]
    elif len(full_cols) == 1:
        axis = "v"
        coord = full_cols[0]
    else:
        # Fallback: all 2s in one row or one column.
        two_rows = {r for r, c in twos}
        two_cols = {c for r, c in twos}
        if len(two_rows) == 1:
            axis = "h"
            coord = next(iter(two_rows))
        elif len(two_cols) == 1:
            axis = "v"
            coord = next(iter(two_cols))
        else:
            return result

    moves = []

    if axis == "h":
        above = [(r, c) for r, c in ones if r < coord]
        below = [(r, c) for r, c in ones if r > coord]

        if above:
            shift = coord - max(r for r, c in above) - 1
            if shift > 0:
                moves.extend((r, c, shift, 0) for r, c in above)

        if below:
            shift = min(r for r, c in below) - coord - 1
            if shift > 0:
                moves.extend((r, c, -shift, 0) for r, c in below)

    else:
        left = [(r, c) for r, c in ones if c < coord]
        right = [(r, c) for r, c in ones if c > coord]

        if left:
            shift = coord - max(c for r, c in left) - 1
            if shift > 0:
                moves.extend((r, c, 0, shift) for r, c in left)

        if right:
            shift = min(c for r, c in right) - coord - 1
            if shift > 0:
                moves.extend((r, c, 0, -shift) for r, c in right)

    if moves:
        # Clear old 1 positions.
        for r, c, _, _ in moves:
            if result[r][c] == 1:
                result[r][c] = 0

        # Place moved 1s.
        for r, c, dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and result[nr][nc] != 2:
                result[nr][nc] = 1

    return result

