                    is_edge = True
                    break

            if is_edge:
                out[r][c] = color

    return out

from __future__ import annotations

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [list(row) for row in grid]

    g = [[int(v) for v in row] for row in grid]
    h, w = len(g), len(g[0])

    ones = []
    twos = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 1:
                ones.append((r, c))
            elif g[r][c] == 2:
                twos.append((r, c))

    if not ones or not twos:
        return g

    dx = dy = 0
    one_rows = [r for r, _ in ones]
    one_cols = [c for _, c in ones]
    two_rows = [r for r, _ in twos]
    two_cols = [c for _, c in twos]

    # The 2s form a straight line. Move all 1s perpendicular to that line
    # until their bounding box is adjacent to the line.
    if len(set(two_cols)) == 1 and len(set(two_rows)) > 1:
        line_c = two_cols[0]
        if max(one_cols) < line_c:
            dx = line_c - max(one_cols) - 1
        elif min(one_cols) > line_c:
            dx = line_c - min(one_cols) + 1
    elif len(set(two_rows)) == 1 and len(set(two_cols)) > 1:
        line_r = two_rows[0]
        if max(one_rows) < line_r:
            dy = line_r - max(one_rows) - 1
        elif min(one_rows) > line_r:
            dy = line_r - min(one_rows) + 1
    else:
        # Fallback for unusual cases: move toward the 2 bounding box
        # in any separated axis.
        min_r1, max_r1 = min(one_rows), max(one_rows)
        min_c1, max_c1 = min(one_cols), max(one_cols)
        min_r2, max_r2 = min(two_rows), max(two_rows)
        min_c2, max_c2 = min(two_cols), max(two_cols)

        if max_r1 < min_r2:
            dy = min_r2 - max_r1 - 1
        elif min_r1 > max_r2:
            dy = max_r2 - min_r1 + 1

        if max_c1 < min_c2:
            dx = min_c2 - max_c1 - 1
        elif min_c1 > max_c2:
            dx = max_c2 - min_c1 + 1

    if dx == 0 and dy == 0:
        return g

    for r, c in ones:
        g[r][c] = 0

    for r, c in ones:
        nr, nc = r + dy, c + dx
        if 0 <= nr < h and 0 <= nc < w and g[nr][nc] in (0, 1):
            g[nr][nc] = 1

    return g

