    # Make a mutable copy and normalize entries to Python ints.
    # This also safely handles inputs given as lists of digit strings.
    out = []
    for row in grid:
        if isinstance(row, str):
            out.append([int(ch) for ch in row])
        else:
            out.append([int(v) for v in row])

    for row in out:
        first_one = -1
        last_one = -1

        for col, value in enumerate(row):
            if value == 1:
                if first_one == -1:
                    first_one = col
                last_one = col

        if first_one != -1 and last_one > first_one:
            for col in range(first_one + 1, last_one):
                if row[col] == 0:
                    row[col] = 2

    return out

