    cells2 = []
    cells4 = []

    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 2:
                cells2.append((r, c))
            elif v == 4:
                cells4.append((r, c))

    # If one of the expected colors is missing, return the grid unchanged.
    if not cells2 or not cells4:
        return [row[:] for row in grid]

    # The two 2s define a bounding box.
    rmin = min(r for r, _ in cells2)
    rmax = max(r for r, _ in cells2)
    cmin = min(c for _, c in cells2)
    cmax = max(c for _, c in cells2)

    # If the 4 lies inside that bounding box, keep the 4 and erase all 2s.
    # Otherwise, keep the 2s and erase all 4s.
    four_inside = all(
        rmin <= r <= rmax and cmin <= c <= cmax
        for r, c in cells4
    )

    if four_inside:
        return [[0 if v == 2 else v for v in row] for row in grid]
    else:
        return [[0 if v == 4 else v for v in row] for row in grid]

