                if grid[i][j] == 8:
                    if not (r0 <= i <= r1 and c0 <= j <= c1):
                        out[i][j] = 8
    else:
        for i in range(h):
            for j in range(w):
                if grid[i][j] == 8:
                    out[i][j] = 8

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def full_row(i: int):
        v = grid[i][0]
        if v == 0:
            return None
        if all(x == v for x in grid[i]):
            return v
        return None

    def full_col(j: int):
        v = grid[0][j]
        if v == 0:
            return None
        if all(grid[i][j] == v for i in range(H)):
            return v
        return None

    candidates = []

    for i in range(H):
        v = full_row(i)
        if v is None:
            continue
        above = sum(
            1 for r in range(i) for c in range(W)
            if grid[r][c] != 0 and grid[r][c] != v
        )
        below = sum(
            1 for r in range(i + 1, H) for c in range(W)
            if grid[r][c] != 0 and grid[r][c] != v
        )
        score = (
            1 if above and below else 0,
            above + below,
            -abs(i - (H - 1) / 2),
            1,  # prefer horizontal if tied
        )
        candidates.append(("H", i, v, score))

    for j in range(W):
        v = full_col(j)
        if v is None:
            continue
        left = sum(
            1 for r in range(H) for c in range(j)
            if grid[r][c] != 0 and grid[r][c] != v
        )
        right = sum(
            1 for r in range(H) for c in range(j + 1, W)
            if grid[r][c] != 0 and grid[r][c] != v
        )
        score = (
            1 if left and right else 0,
            left + right,
            -abs(j - (W - 1) / 2),
            0,
        )
        candidates.append(("V", j, v, score))

    if not candidates:
        return out

    orient, pos, line_color, _ = max(candidates, key=lambda x: x[3])

    visited = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v == 0 or v == line_color or visited[r][c]:
                continue

            q = deque([(r, c)])
            visited[r][c] = True
            cells = []

            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W:
                        if not visited[nx][ny] and grid[nx][ny] == v:
                            visited[nx][ny] = True
                            q.append((nx, ny))

            components.append(cells)

    for cells in components:
        if orient == "H":
            line_r = pos
            avg_r = sum(r for r, _ in cells) / len(cells)

            if avg_r < line_r:
                endpoint = (line_r, 0)
            elif avg_r > line_r:
                endpoint = (line_r, W - 1)
            else:
                endpoint = (line_r, 0) if any(r < line_r for r, _ in cells) else (line_r, W - 1)

        else:
            line_c = pos
            avg_c = sum(c for _, c in cells) / len(cells)

            if avg_c < line_c:
                endpoint = (H - 1, line_c)
            elif avg_c > line_c:
                endpoint = (0, line_c)
            else:
                endpoint = (H - 1, line_c) if any(c < line_c for _, c in cells) else (0, line_c)

        er, ec = endpoint
        best = min(
            cells,
            key=lambda rc: (abs(rc[0] - er) + abs(rc[1] - ec), rc[0], rc[1])
        )
        out[best[0]][best[1]] = line_color

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])
    a = np.array(grid, dtype=int)

    # Find connected components of the same non-zero colour (4-connectivity).
    visited = np.zeros((H, W), dtype=bool)
    comps = []

    for r in range(H):
        for c in range(W):
            val = a[r, c]
            if val == 0 or visited[r, c]:
                continue

            color = int(val)
            stack = [(r, c)]
            visited[r, c] = True
            cells = []

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not visited[nr, nc] and a[nr, nc] == color:
                            visited[nr, nc] = True
                            stack.append((nr, nc))

            rs = [x[0] for x in cells]
            cs = [x[1] for x in cells]
            comps.append({
                "cells": cells,
                "color": color,
                "rmin": min(rs),
                "rmax": max(rs),
                "cmin": min(cs),
                "cmax": max(cs),
                "area": len(cells),
            })

    if not comps:
        return [[0] * W for _ in range(H)]

    def vertical_line() -> bool:
        order = sorted(comps, key=lambda x: (x["rmin"], x["cmin"]))
        return all(
            order[i]["rmax"] < order[i + 1]["rmin"]
            for i in range(len(order) - 1)
        )

    def horizontal_line() -> bool:
        order = sorted(comps, key=lambda x: (x["cmin"], x["rmin"]))
        return all(
            order[i]["cmax"] < order[i + 1]["cmin"]
            for i in range(len(order) - 1)
        )

    vline = vertical_line()
    hline = horizontal_line()

    def row_block_count() -> int:
        nonempty = (a != 0).any(axis=1)
        cnt = 0
        prev = False
        for x in nonempty:
            if x and not prev:
                cnt += 1
            prev = bool(x)
        return cnt

    def col_block_count() -> int:
        nonempty = (a != 0).any(axis=0)
        cnt = 0
        prev = False
        for x in nonempty:
            if x and not prev:
                cnt += 1
            prev = bool(x)
        return cnt

    # Choose the direction in which the objects are laid out.
    if vline and not hline:
        axis = "V"
    elif hline and not vline:
        axis = "H"
    elif vline and hline:
        rb = row_block_count()
        cb = col_block_count()
        if rb > cb:
            axis = "V"
        elif cb > rb:
            axis = "H"
        else:
            axis = "V"
    else:
        # Fallback: use full empty rows/columns as the separators.
        rb = row_block_count()
        cb = col_block_count()
        if rb >= 2 and rb >= cb:
            axis = "V"
        elif cb >= 2:
            axis = "H"
        else:
            return [[int(x) for x in row] for row in a]

    out = np.zeros((H, W), dtype=int)

    if axis == "V":
        original = sorted(comps, key=lambda x: (x["rmin"], x["cmin"]))
        gaps = [
            original[i + 1]["rmin"] - original[i]["rmax"] - 1
            for i in range(len(original) - 1)
        ]
        top_gap = original[0]["rmin"]

        # Sort by pixel count, smallest first. Stable for ties.
        ordered = sorted(original, key=lambda x: x["area"])

        y = top_gap
        for i, comp in enumerate(ordered):
            dy = y - comp["rmin"]
            for r, c in comp["cells"]:
                out[r + dy, c] = comp["color"]
            y += comp["rmax"] - comp["rmin"] + 1
            if i < len(ordered) - 1:
                y += gaps[i]

    else:
        original = sorted(comps, key=lambda x: (x["cmin"], x["rmin"]))
        gaps = [
            original[i + 1]["cmin"] - original[i]["cmax"] - 1
            for i in range(len(original) - 1)
        ]
        left_gap = original[0]["cmin"]

        # Sort by pixel count, smallest first. Stable for ties.
        ordered = sorted(original, key=lambda x: x["area"])

        x = left_gap
        for i, comp in enumerate(ordered):
            dx = x - comp["cmin"]
            for r, c in comp["cells"]:
                out[r, c + dx] = comp["color"]
            x += comp["cmax"] - comp["cmin"] + 1
            if i < len(ordered) - 1:
                x += gaps[i]

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Count non-background colors.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    # The marker color is the least frequent non-background color.
    marker_color = min(counts, key=lambda x: (counts[x], x))

    # Positions of the marker color.
    marker_positions = [
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] == marker_color
    ]

    # Determine orientation from the two marker cells.
    # If they share a row, paint a horizontal border.
    # If they share a column, paint a vertical border.
    if len(marker_positions) >= 2:
        r0, c0 = marker_positions[0]
        r1, c1 = marker_positions[1]
        if r0 == r1:
            orientation = "horizontal"
        elif c0 == c1:
            orientation = "vertical"
        else:
            # Fallback for unexpected diagonal inputs.
            orientation = "horizontal" if abs(r1 - r0) < abs(c1 - c0) else "vertical"
    else:
        orientation = "horizontal"

    # Bounding box of all non-background cells except the marker color.
    min_r = min_c = 10**9
    max_r = max_c = -10**9
    found = False

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != marker_color:
                found = True
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if not found:
        # No other non-background cells; default to top/left.
        if orientation == "horizontal":
            out = [row[:] for row in grid]
            for c in range(w):
                out[0][c] = marker_color
            return out
        else:
            out = [row[:] for row in grid]
            for r in range(h):
                out[r][0] = marker_color
            return out

    # Distances from the main object to each border.
    dist_top = min_r
    dist_bottom = h - 1 - max_r
    dist_left = min_c
    dist_right = w - 1 - max_c

    if orientation == "horizontal":
        candidates = [("top", dist_top, 0), ("bottom", dist_bottom, 1)]
    else:
        candidates = [("left", dist_left, 0), ("right", dist_right, 1)]

    # Prefer a non-touching (positive distance) border, then the closest one,
    # then top/left on ties.
    best = min(
        candidates,
        key=lambda item: (0 if item[1] > 0 else 1, item[1], item[2])
    )
    side = best[0]

    out = [row[:] for row in grid]

    if side == "top":
        for c in range(w):
            out[0][c] = marker_color
    elif side == "bottom":
        for c in range(w):
            out[h - 1][c] = marker_color
    elif side == "left":
        for r in range(h):
            out[r][0] = marker_color
    elif side == "right":
        for r in range(h):
            out[r][w - 1] = marker_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
