def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    grid = [list(row) for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Find the main non-background color.
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if not counts:
        return grid

    color = max(counts, key=lambda x: counts[x])

    # Flood-fill exterior background from the border using 4-connectivity.
    exterior = [[False] * w for _ in range(h)]
    stack = []

    def add_exterior(r, c):
        if 0 <= r < h and 0 <= c < w:
            if not exterior[r][c] and grid[r][c] == 0:
                exterior[r][c] = True
                stack.append((r, c))

    for r in range(h):
        add_exterior(r, 0)
        add_exterior(r, w - 1)

    for c in range(w):
        add_exterior(0, c)
        add_exterior(h - 1, c)

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            add_exterior(r + dr, c + dc)

    out = [row[:] for row in grid]

    # If there are enclosed background cells, fill them.
    has_hole = False
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not exterior[r][c]:
                has_hole = True
                out[r][c] = color

    if has_hole:
        return out

    # Otherwise, hollow out the shape by removing internal colored cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == color:
                if 0 < r < h - 1 and 0 < c < w - 1:
                    if (
                        grid[r - 1][c] == color
                        and grid[r + 1][c] == color
                        and grid[r][c - 1] == color
                        and grid[r][c + 1] == color
                    ):
                        out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque

