from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    g = [list(map(int, row)) for row in grid]
    h, w = len(g), len(g[0])

    # Detect the background color.  In the examples it is 0, but if the
    # grid uses another background color we should repaint with that color.
    total = Counter(g[r][c] for r in range(h) for c in range(w))

    border = Counter()
    for r in range(h):
        border[g[r][0]] += 1
        border[g[r][w - 1]] += 1
    for c in range(1, w - 1):
        border[g[0][c]] += 1
        border[g[h - 1][c]] += 1

    bg = max(
        total,
        key=lambda col: (
            total[col],
            border.get(col, 0),
            col == 0,
            -col,
        ),
    )

    # Central cells: one for odd lengths, a 2x2 block for even lengths.
    def center_indices(n: int):
        m = n // 2
        if n % 2 == 1:
            return [m]
        return [m - 1, m]

    crs = center_indices(h)
    ccs = center_indices(w)

    marked = [[False] * w for _ in range(h)]
    directions = ((-1, 0), (1, 0), (0, -1), (0, 1))

    def flood(r: int, c: int):
        color = g[r][c]
        q = deque([(r, c)])
        marked[r][c] = True
        while q:
            r, c = q.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not marked[nr][nc] and g[nr][nc] == color:
                        marked[nr][nc] = True
                        q.append((nr, nc))

    # Remove every non-background component that occupies the center.
    for r in crs:
        for c in ccs:
            if g[r][c] != bg and not marked[r][c]:
                flood(r, c)

    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = bg

    return out

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    grid = [list(map(int, row)) for row in grid]
    h, w = len(grid), len(grid[0])

    out = [row[:] for row in grid]
    changes = {}

    # Global colour counts used only for deterministic tie-breaking.
    total_counts = Counter(v for row in grid for v in row if v != 0)

    def add_change(r, c, color):
        changes.setdefault((r, c), set()).add(color)

    # Check rows.
    if w >= 3:
        for r in range(h):
            counts = Counter(grid[r])
            for color, cnt in counts.items():
                if color != 0 and cnt == w - 1:
                    for c, val in enumerate(grid[r]):
                        if val != color:
                            add_change(r, c, color)

    # Check columns.
    if h >= 3:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            counts = Counter(col)
            for color, cnt in counts.items():
                if color != 0 and cnt == h - 1:
                    for r, val in enumerate(col):
                        if val != color:
                            add_change(r, c, color)

    # Apply all detected fixes.
    for (r, c), colors in changes.items():
        if len(colors) == 1:
            out[r][c] = next(iter(colors))
        else:
            best = max(colors, key=lambda x: (total_counts.get(x, 0), -x))
            out[r][c] = best

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return [list(row) for row in grid]

    out = [list(row) for row in grid]

    # Collect cells by color and pick the main object color.
    cells_by_color = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                cells_by_color.setdefault(v, []).append((r, c))

    if not cells_by_color:
        return out

    best_color = None
    best_score = (-1, -1)

    for color, cells in cells_by_color.items():
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)
        bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
        score = (len(cells), bbox_area)
        if score > best_score:
            best_score = score
            best_color = color

    cells = cells_by_color[best_color]
    color = int(best_color)

    min_r = min(r for r, _ in cells)
    max_r = max(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    max_c = max(c for _, c in cells)

    # Empty distances from the bounding box to each grid edge.
    gaps = [
        ("right", W - 1 - max_c),
        ("down", H - 1 - max_r),
        ("left", min_c),
        ("up", min_r),
    ]

    chosen = None
    best_gap = -1
    for name, gap in gaps:
        if gap > best_gap:
            best_gap = gap
            chosen = name

    if best_gap <= 0:
        return out

    if chosen in ("right", "left"):
        r = (min_r + max_r) // 2
        if chosen == "right":
            for c in range(max_c + 1, W):
                out[r][c] = color
        else:
            for c in range(0, min_c):
                out[r][c] = color
    else:
        c = (min_c + max_c) // 2
        if chosen == "down":
            for r in range(max_r + 1, H):
                out[r][c] = color
        else:
            for r in range(0, min_r):
                out[r][c] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    new_grid = [row[:] for row in grid]

    # Find the main non-zero connected component.
    visited = [[False] * W for _ in range(H)]
    best_cells = []
    best_color = 0

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                stack = [(r, c)]
                visited[r][c] = True
                cells = []

                while stack:
                    rr, cc = stack.pop()
                    cells.append((rr, cc))

                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = rr + dr, cc + dc
                        if (
                            0 <= nr < H
                            and 0 <= nc < W
                            and not visited[nr][nc]
                            and grid[nr][nc] == color
                        ):
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                if len(cells) > len(best_cells):
                    best_cells = cells
                    best_color = color

    if not best_cells:
        return new_grid

    min_r = min(r for r, c in best_cells)
    max_r = max(r for r, c in best_cells)
    min_c = min(c for r, c in best_cells)
    max_c = max(c for r, c in best_cells)

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    # Middle rows/columns.  For even sizes, use both central lines.
    if height % 2 == 1:
        center_rows = [min_r + height // 2]
    else:
        center_rows = [min_r + height // 2 - 1, min_r + height // 2]

    if width % 2 == 1:
        center_cols = [min_c + width // 2]
    else:
        center_cols = [min_c + width // 2 - 1, min_c + width // 2]

    # Extend toward the farthest empty edge of the bounding box.
    margins = {
        "up": min_r,
        "down": H - 1 - max_r,
        "left": min_c,
        "right": W - 1 - max_c,
    }

    max_margin = max(margins.values())
    if max_margin == 0:
        return new_grid

    candidates = [d for d in ("right", "down", "left", "up") if margins[d] == max_margin]

    # Deterministic tie-breaking: prefer the longer grid axis if available.
    if H > W:
        vertical = [d for d in candidates if d in ("up", "down")]
        if vertical:
            candidates = vertical
    elif W > H:
        horizontal = [d for d in candidates if d in ("left", "right")]
        if horizontal:
            candidates = horizontal

    direction = None
    for d in ("right", "down", "left", "up"):
        if d in candidates:
            direction = d
            break

    if direction is None:
        return new_grid

    if direction == "right":
        for r in center_rows:
            for c in range(max_c + 1, W):
                new_grid[r][c] = best_color
    elif direction == "left":
        for r in center_rows:
            for c in range(min_c - 1, -1, -1):
                new_grid[r][c] = best_color
    elif direction == "down":
        for c in center_cols:
            for r in range(max_r + 1, H):
                new_grid[r][c] = best_color
    else:  # "up"
        for c in center_cols:
            for r in range(min_r - 1, -1, -1):
                new_grid[r][c] = best_color

    return new_grid

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Normalize input to a list of lists of ints
    g = [list(map(int, row)) for row in grid]

    if not g or not g[0]:
        return [[0]]

    # Find bounding box of all non-zero cells
    non_zero = []
    for r in range(len(g)):
        for c in range(len(g[r])):
            if g[r][c] != 0:
                non_zero.append((r, c))

    if not non_zero:
        return [[0]]

    min_r = min(r for r, c in non_zero)
    max_r = max(r for r, c in non_zero)
    min_c = min(c for r, c in non_zero)
    max_c = max(c for r, c in non_zero)

    # Interior width: strictly inside the bounding box
    out_height = max_c - min_c - 1

    if out_height <= 0:
        return [[0]]

    # Count non-zero cells strictly inside the frame
    count = 0
    for r in range(min_r + 1, max_r):
        for c in range(min_c + 1, max_c):
            if g[r][c] != 0:
                count += 1

    # Clip in case count exceeds the interior width
    filled = min(count, out_height)

    return [[4 if i < filled else 0] for i in range(out_height)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Global color counts.
    total = {}
    for row in grid:
        for v in row:
            total[v] = total.get(v, 0) + 1
    colors = sorted(total.keys())

    # Candidate simple pattern models.
    # Each model partitions the cells into groups; every group will be filled
    # with one of the two chosen colors.
    model_pref = {
        "const": 0,
        "row_parity": 1,
        "col_parity": 2,
        "checker": 3,
        "row": 4,
        "col": 5,
    }

    def build_groups(name: str):
        if name == "const":
            return [[0] * W for _ in range(H)], 1
        if name == "row_parity":
            return [[(r % 2) for _ in range(W)] for r in range(H)], 2
        if name == "col_parity":
            return [[(c % 2) for c in range(W)] for _ in range(H)], 2
        if name == "checker":
            return [[((r + c) % 2) for c in range(W)] for r in range(H)], 2
        if name == "row":
            return [[r] * W for r in range(H)], H
        if name == "col":
            return [[c for c in range(W)] for _ in range(H)], W
        raise ValueError(name)

    model_names = ["const", "row_parity", "col_parity", "checker", "row", "col"]
    model_groups = {}
    model_group_count = {}
    for name in model_names:
        model_groups[name], model_group_count[name] = build_groups(name)

    best_key = None
    best_pair = None
    best_model = None

    # Single-color constant models.
    for c in colors:
        score = total[c]
        key = (score, total[c], -model_pref["const"], -1, -c, -c)
        if best_key is None or key > best_key:
            best_key = key
            best_pair = (c, c)
            best_model = "const"

    # Two-color pattern models over every pair of present colors.
    for i, a in enumerate(colors):
        for b in colors[i + 1:]:
            coverage = total[a] + total[b]
            for name in model_names:
                gids = model_groups[name]
                gcount = model_group_count[name]
                counts = [[0, 0] for _ in range(gcount)]

                for r in range(H):
                    row = grid[r]
                    gid_row = gids[r]
                    for c in range(W):
                        v = row[c]
                        if v == a:
                            counts[gid_row[c]][0] += 1
                        elif v == b:
                            counts[gid_row[c]][1] += 1

                score = 0
                for x, y in counts:
                    score += x if x > y else y

                key = (
                    score,
                    coverage,
                    -model_pref[name],
                    -gcount,
                    -a,
                    -b,
                )
                if best_key is None or key > best_key:
                    best_key = key
                    best_pair = (a, b)
                    best_model = name

    a, b = best_pair

    # Constant single-color case.
    if a == b:
        return [[a] * W for _ in range(H)]

    # Recompute group counts for the winning model and fill the grid.
    gids = model_groups[best_model]
    gcount = model_group_count[best_model]
    counts = [[0, 0] for _ in range(gcount)]

    for r in range(H):
        row = grid[r]
        gid_row = gids[r]
        for c in range(W):
            v = row[c]
            if v == a:
                counts[gid_row[c]][0] += 1
            elif v == b:
                counts[gid_row[c]][1] += 1

    group_color = [0] * gcount
    for gid in range(gcount):
        ca, cb = counts[gid]
        if ca > cb:
            group_color[gid] = a
        elif cb > ca:
            group_color[gid] = b
        else:
            # Tie-break: more frequent globally; if still tied, alternate by group.
            if total[a] > total[b]:
                group_color[gid] = a
            elif total[b] > total[a]:
                group_color[gid] = b
            else:
                group_color[gid] = a if gid % 2 == 0 else b

    out = [[0] * W for _ in range(H)]
    for r in range(H):
        gid_row = gids[r]
        out_row = out[r]
        for c in range(W):
            out_row[c] = group_color[gid_row[c]]

    return out

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    R = len(grid)
    C = len(grid[0])
    if R == 0 or C == 0:
        return [row[:] for row in grid]

    # Identify background. Prefer 0 only as a final tie-breaker;
    # otherwise choose the most widespread most-common color.
    color_counts = Counter(val for row in grid for val in row)
    max_count = max(color_counts.values())
    candidates = [c for c, n in color_counts.items() if n == max_count]

    if len(candidates) == 1:
        bg = candidates[0]
    else:
        def spread(c):
            row_spread = sum(1 for row in grid if any(v == c for v in row))
            col_spread = sum(
                1 for j in range(C) if any(grid[i][j] == c for i in range(R))
            )
            return (row_spread, col_spread, c == 0)
        bg = max(candidates, key=spread)

    # Count non-background pixels per row and per column.
    row_counts = [sum(1 for val in row if val != bg) for row in grid]
    col_counts = [
        sum(1 for i in range(R) if grid[i][j] != bg) for j in range(C)
    ]

    if max(row_counts) == 0:
        return [row[:] for row in grid]

    # The true horizontal row and vertical column should have at least
    # two visible marks in these puzzles; fall back to maximum otherwise.
    row_candidates = [i for i in range(R) if row_counts[i] >= 2]
    col_candidates = [j for j in range(C) if col_counts[j] >= 2]

    r = max(row_candidates or range(R), key=lambda i: row_counts[i])
    c = max(col_candidates or range(C), key=lambda j: col_counts[j])

    # Determine line colors, ignoring the intersection cell if possible.
    row_without_cross = Counter(
        grid[r][j] for j in range(C) if j != c and grid[r][j] != bg
    )
    col_without_cross = Counter(
        grid[i][c] for i in range(R) if i != r and grid[i][c] != bg
    )

    if row_without_cross:
        row_color = row_without_cross.most_common(1)[0][0]
    else:
        row_color = next((val for val in grid[r] if val != bg), bg)

    if col_without_cross:
        col_color = col_without_cross.most_common(1)[0][0]
    else:
        col_color = next(
            (val for val in (grid[i][c] for i in range(R)) if val != bg),
            bg
        )

    # Draw the completed cross. Column first so row wins at intersection.
    out = [row[:] for row in grid]
    for i in range(R):
        out[i][c] = col_color
    for j in range(C):
        out[r][j] = row_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])

    # Work on a copy with plain Python ints.
    out = [[int(grid[r][c]) for c in range(w)] for r in range(h)]

    # Find the bounding box for every non-zero colour.
    boxes = {}
    for r in range(h):
        for c in range(w):
            v = out[r][c]
            if v == 0:
                continue

            if v not in boxes:
                boxes[v] = [r, r, c, c]
            else:
                min_r, max_r, min_c, max_c = boxes[v]
                boxes[v] = [
                    min(min_r, r),
                    max(max_r, r),
                    min(min_c, c),
                    max(max_c, c),
                ]

    # Fill the bounding boxes.  Smaller boxes first avoids accidental
    # overwrites if two boxes overlap on empty cells.
    for colour in sorted(
        boxes,
        key=lambda v: (
            (boxes[v][1] - boxes[v][0] + 1) * (boxes[v][3] - boxes[v][2] + 1),
            v,
        ),
    ):
        min_r, max_r, min_c, max_c = boxes[colour]
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if out[r][c] == 0:
                    out[r][c] = colour

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []

    # Normalise to a rectangular Python list of lists of ints.
    grid = [[int(v) for v in row] for row in grid]
    w = max(len(row) for row in grid)
    if w == 0:
        return [[0]]
    grid = [row + [0] * (w - len(row)) for row in grid]

    colors = set()
    for row in grid:
        for v in row:
            if v != 0:
                colors.add(v)

    if not colors:
        return [[0]]

    best_side = 0
    best_color = 0

    # Largest solid square of any non-background colour.
    for c in sorted(colors):
        dp = [0] * (w + 1)
        max_side = 0

        for i in range(h):
            curr = [0] * (w + 1)
            row = grid[i]

            for j in range(w):
                if row[j] == c:
                    val = 1 + min(dp[j + 1], curr[j], dp[j])
                    curr[j + 1] = val
                    if val > max_side:
                        max_side = val

            dp = curr

        if max_side > best_side:
            best_side = max_side
            best_color = c

    return [[best_color] * best_side for _ in range(best_side)]

