def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [[0]]

    g = [[int(x) for x in row] for row in grid]
    h, w = len(g), len(g[0])

    # Count total occurrences of each colour.
    total = {}
    for row in g:
        for v in row:
            total[v] = total.get(v, 0) + 1

    # Find connected components (4-neighbour) and sum the area of all
    # components of each colour that touch the border.  The background is
    # the colour most strongly associated with the exterior of the grid.
    visited = [[False] * w for _ in range(h)]
    border_area = {}

    for r in range(h):
        for c in range(w):
            if visited[r][c]:
                continue

            colour = g[r][c]
            stack = [(r, c)]
            visited[r][c] = True
            size = 0
            touches_border = False

            while stack:
                i, j = stack.pop()
                size += 1

                if i == 0 or i == h - 1 or j == 0 or j == w - 1:
                    touches_border = True

                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w:
                        if not visited[ni][nj] and g[ni][nj] == colour:
                            visited[ni][nj] = True
                            stack.append((ni, nj))

            if touches_border:
                border_area[colour] = border_area.get(colour, 0) + size

    # Choose the background colour.  Prefer 0 when it is on the border,
    # since 0 is usually the background; otherwise use border presence,
    # then total frequency, then smaller colour as tie-breakers.
    border_colors = [c for c in total if border_area.get(c, 0) > 0]
    if not border_colors:
        border_colors = list(total.keys())

    if 0 in border_colors:
        bg = 0
    else:
        bg = max(border_colors, key=lambda c: (border_area[c], total[c], -c))

    # Number of colours other than the background.
    other_count = len([c for c in total if c != bg])
    if other_count == 0:
        other_count = 1

    return [[bg] * other_count]

