    out = [row[:] for row in grid]
    visited = [[False] * w for _ in range(h)]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or visited[r][c]:
                continue

            cells = []
            stack = [(r, c)]
            visited[r][c] = True

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny][nx] and grid[ny][nx] == color:
                            visited[ny][nx] = True
                            stack.append((ny, nx))

            if len(cells) % color not in (0, 1):
                for y, x in cells:
                    out[y][x] = 0

    return out

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return []

    grid = [list(row) for row in grid]

    # Separator lines are full rows/cols of colour 4.
    sep_rows = [r for r in range(H) if all(grid[r][c] == 4 for c in range(W))]
    sep_cols = [c for c in range(W) if all(grid[r][c] == 4 for r in range(H))]
    sep_row_set = set(sep_rows)
    sep_col_set = set(sep_cols)

    def make_intervals(seps, n):
        """Non-separator intervals in [0, n)."""
        res = []
        start = 0
        for s in sorted(set(seps)):
            if s < start:
                continue
            if s > start:
                res.append((start, s))
            start = s + 1
        if start < n:
            res.append((start, n))
        return res

    row_intervals = make_intervals(sep_rows, H)
    col_intervals = make_intervals(sep_cols, W)

    def get_background(r1, r2, c1, c2):
        """
        Determine the background colour of one rectangular panel.
        The background is normally the colour on the panel border next to
        the separator.  Corner/uniform-panel checks make this robust.
        """
        h = r2 - r1
        w = c2 - c1
        if h <= 0 or w <= 0:
            return 0

        # If all four corners are the same colour, that is almost certainly
        # the panel background.
        corners = [
            grid[r1][c1],
            grid[r1][c2 - 1],
            grid[r2 - 1][c1],
            grid[r2 - 1][c2 - 1],
        ]
        if all(x == corners[0] for x in corners):
            return corners[0]

        # Cells immediately adjacent to separator lines.
        adjacent = []
        if r1 > 0 and (r1 - 1) in sep_row_set:
            adjacent.extend(grid[r1][c1:c2])
        if r2 < H and r2 in sep_row_set:
            adjacent.extend(grid[r2 - 1][c1:c2])
        if c1 > 0 and (c1 - 1) in sep_col_set:
            adjacent.extend([grid[r][c1] for r in range(r1, r2)])
        if c2 < W and c2 in sep_col_set:
            adjacent.extend([grid[r][c2 - 1] for r in range(r1, r2)])

        overall = Counter()
        for r in range(r1, r2):
            for c in range(c1, c2):
                overall[grid[r][c]] += 1

        if h == 1:
            border = grid[r1][c1:c2]
        elif w == 1:
            border = [grid[r][c1] for r in range(r1, r2)]
        else:
            border = grid[r1][c1:c2] + grid[r2 - 1][c1:c2]
            for r in range(r1 + 1, r2 - 1):
                border.append(grid[r][c1])
                border.append(grid[r][c2 - 1])

        adj_count = Counter(adjacent)
        border_count = Counter(border)

        # Prefer the colour on separator-adjacent border, then overall/border.
        return max(
            overall.keys(),
            key=lambda x: (
                adj_count.get(x, 0),
                overall[x],
                border_count.get(x, 0),
                -x,
            ),
        )

    out = [[0] * W for _ in range(H)]

    # Replace each panel's background with 0; separator lines remain 0.
    for r1, r2 in row_intervals:
        for c1, c2 in col_intervals:
            if r2 <= r1 or c2 <= c1:
                continue

            bg = get_background(r1, r2, c1, c2)
            for r in range(r1, r2):
                for c in range(c1, c2):
                    v = grid[r][c]
                    out[r][c] = 0 if v == bg else v

    # Remove all completely empty rows and columns.
    keep_rows = [r for r in range(H) if any(out[r][c] != 0 for c in range(W))]
    keep_cols = [c for c in range(W) if any(out[r][c] != 0 for r in range(H))]

    if not keep_rows or not keep_cols:
        return [[0]]

    return [[out[r][c] for c in keep_cols] for r in keep_rows]

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    counts = Counter()

    for row in grid:
        for cell in row:
            v = int(cell)
            if v != 0:
                counts[v] += 1

    if not counts:
        return []

    main_color = max(counts.items(), key=lambda kv: kv[1])[0]

    total_anomalies = sum(counts.values()) - counts[main_color]
    distinct_anomalies = len(counts) - 1

    return [[distinct_anomalies] for _ in range(total_anomalies)]

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return [[0]]
    W = len(grid[0])
    if W == 0:
        return [[0]]

    a = [[int(v) for v in row] for row in grid]

    eight = [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1) if (dx, dy) != (0, 0)]
    four = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    visited = [[False] * W for _ in range(H)]
    inner_colors = []

    # Find 8-connected components of each non-zero colour.
    # A closed border component can enclose an interior region.
    for color in range(1, 10):
        for r in range(H):
            for c in range(W):
                if a[r][c] != color or visited[r][c]:
                    continue

                comp = []
                q = deque([(r, c)])
                visited[r][c] = True

                while q:
                    x, y = q.popleft()
                    comp.append((x, y))
                    for dx, dy in eight:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if not visited[nx][ny] and a[nx][ny] == color:
                                visited[nx][ny] = True
                                q.append((nx, ny))

                # Quick reject: cannot enclose a hole if too small / too solid.
                if len(comp) < 4:
                    continue

                min_r = min(x for x, _ in comp)
                max_r = max(x for x, _ in comp)
                min_c = min(y for _, y in comp)
                max_c = max(y for _, y in comp)

                if max_r - min_r + 1 < 3 or max_c - min_c + 1 < 3:
                    continue
                if (max_r - min_r + 1) * (max_c - min_c + 1) <= len(comp):
                    continue

                # Use this component as walls.
                wall = [[False] * W for _ in range(H)]
                for x, y in comp:
                    wall[x][y] = True

                # Flood-fill reachable outside using 4-neighbour movement.
                reach = [[False] * W for _ in range(H)]
                q = deque()

                for x in range(H):
                    for y in (0, W - 1):
                        if not wall[x][y] and not reach[x][y]:
                            reach[x][y] = True
                            q.append((x, y))
                for y in range(W):
                    for x in (0, H - 1):
                        if not wall[x][y] and not reach[x][y]:
                            reach[x][y] = True
                            q.append((x, y))

                while q:
                    x, y = q.popleft()
                    for dx, dy in four:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if not wall[nx][ny] and not reach[nx][ny]:
                                reach[nx][ny] = True
                                q.append((nx, ny))

                # Interior is any non-wall cell not reachable from the border.
                counts = {}
                has_interior = False
                for x in range(H):
                    for y in range(W):
                        if not wall[x][y] and not reach[x][y]:
                            has_interior = True
                            v = a[x][y]
                            if v != 0:
                                counts[v] = counts.get(v, 0) + 1

                if not has_interior or not counts:
                    continue

                # The box's contained digit is the dominant non-zero colour inside.
                digit = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
                inner_colors.append(digit)

    if not inner_colors:
        return [[0]]

    freq = {}
    for d in inner_colors:
        freq[d] = freq.get(d, 0) + 1

    # Most common contained digit; deterministic tie-break by smaller digit.
    ans = max(freq.keys(), key=lambda k: (freq[k], -k))
    return [[ans]]

