        for c in range(w):
            v = grid[r][c]
            if v != 0:
                by_color.setdefault(int(v), []).append((r, c))

    if not by_color:
        return out

    def vertical_params(cells):
        cols = sorted({c for _, c in cells})
        if len(cols) != 2:
            return None
        rows = sorted({r for r, _ in cells})
        top, bottom = rows[0], rows[-1]
        left, right = cols

        expected = set()
        for r in range(top, bottom + 1):
            expected.add((r, left))
            expected.add((r, right))

        if set(cells) != expected:
            return None
        return (top, bottom, left, right)

    def horizontal_params(cells):
        rows = sorted({r for r, _ in cells})
        if len(rows) != 2:
            return None
        cols = sorted({c for _, c in cells})
        top, bottom = rows
        left, right = cols[0], cols[-1]

        expected = set()
        for c in range(left, right + 1):
            expected.add((top, c))
            expected.add((bottom, c))

        if set(cells) != expected:
            return None
        return (top, bottom, left, right)

    best = None
    for color, cells in by_color.items():
        v = vertical_params(cells)
        hp = horizontal_params(cells)
        if v is None and hp is None:
            continue
        if best is None or len(cells) > best[0]:
            best = (len(cells), color, v, hp)

    if best is None:
        color = max(by_color, key=lambda k: len(by_color[k]))
        cells = by_color[color]
        rows = sorted({r for r, _ in cells})
        cols = sorted({c for _, c in cells})

        if len(cols) == 2 and len(rows) >= 2:
            top, bottom = rows[0], rows[-1]
            left, right = cols
            for r in (top, bottom):
                for c in range(left + 1, right + 1):
                    out[r][c] = color
        elif len(rows) == 2 and len(cols) >= 2:
            top, bottom = rows
            left, right = cols[0], cols[-1]
            for r in range(top + 1, bottom + 1):
                out[r][left] = color
                out[r][right] = color
        return out

    _, color, v, hp = best

    if v is not None:
        top, bottom, left, right = v
        for r in (top, bottom):
            for c in range(left + 1, right + 1):
                out[r][c] = color
    else:
        top, bottom, left, right = hp
        for r in range(top + 1, bottom + 1):
            out[r][left] = color
            out[r][right] = color

    return out

