def transform(grid: list[list[int]]) -> list[list[int]]:
    # Normalise input to a list of lists of ints
    grid = [list(map(int, row)) for row in grid]
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the vertical separator made of 5s.
    counts5 = [sum(1 for r in range(H) if grid[r][c] == 5) for c in range(W)]
    full_cols = [c for c in range(W) if counts5[c] == H]

    if full_cols:
        # If there are several full 5-columns (thick line), take the contiguous
        # run closest to the centre.
        runs = []
        start = prev = full_cols[0]
        for c in full_cols[1:]:
            if c == prev + 1:
                prev = c
            else:
                runs.append((start, prev))
                start = prev = c
        runs.append((start, prev))
        center = (W - 1) / 2.0
        left_sep, right_sep = min(runs, key=lambda p: abs((p[0] + p[1]) / 2.0 - center))
    else:
        maxc = max(counts5)
        if maxc == 0:
            return out
        cands = [c for c in range(W) if counts5[c] == maxc]
        center = (W - 1) / 2.0
        left_sep = right_sep = min(cands, key=lambda c: abs(c - center))

    def components(side: int):
        """Collect 4-connected components of non-zero, non-5 cells on one side."""
        seen = [[False] * W for _ in range(H)]
        comps = []

        for r in range(H):
            for c in range(W):
                if side == 0 and not (c < left_sep):
                    continue
                if side == 1 and not (c > right_sep):
                    continue

                v = grid[r][c]
                if v == 0 or v == 5 or seen[r][c]:
                    continue

                stack = [(r, c)]
                seen[r][c] = True
                cells = []

                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))

                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if not (0 <= nr < H and 0 <= nc < W):
                            continue
                        if side == 0 and not (nc < left_sep):
                            continue
                        if side == 1 and not (nc > right_sep):
                            continue
                        if not seen[nr][nc] and grid[nr][nc] == v:
                            seen[nr][nc] = True
                            stack.append((nr, nc))

                rmin = min(r for r, _ in cells)
                rmax = max(r for r, _ in cells)
                cmin = min(c for _, c in cells)
                cmax = max(c for _, c in cells)

                mask = tuple(
                    tuple(1 if grid[r2][c2] == v else 0 for c2 in range(cmin, cmax + 1))
                    for r2 in range(rmin, rmax + 1)
                )

                comps.append({
                    "color": v,
                    "rmin": rmin,
                    "rmax": rmax,
                    "mask": mask,
                    "cells": cells,
                })

        return comps

    left_comps = components(0)
    right_comps = components(1)

    # A right component is kept only if it has an identical left counterpart:
    # same colour, same vertical span, and same shape mask.
    left_keys = {
        (c["color"], c["rmin"], c["rmax"], c["mask"])
        for c in left_comps
    }

    for comp in right_comps:
        key = (comp["color"], comp["rmin"], comp["rmax"], comp["mask"])
        if key not in left_keys:
            for r, c in comp["cells"]:
                out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    visited = [[False] * W for _ in range(H)]
    exact_candidates = []
    loose_candidates = []
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def extract(r1, r2, c1, c2):
        return [[grid[r][c] for c in range(c1, c2 + 1)]
                for r in range(r1, r2 + 1)]

    def add_candidate(cands, r, c, interior):
        if not interior or not interior[0]:
            return
        first = interior[0][0]
        uniform = all(x == first for row in interior for x in row)
        area = len(interior) * len(interior[0])
        cands.append({
            "area": area,
            "r": r,
            "c": c,
            "uniform": uniform,
            "interior": interior,
        })

    def choose(cands):
        if not cands:
            return None
        # Prefer larger enclosed area; tie-break by top-left position.
        best = max(cands, key=lambda x: (x["area"], -x["r"], -x["c"]))
        return best["interior"]

    for r0 in range(H):
        for c0 in range(W):
            if grid[r0][c0] == 0 or visited[r0][c0]:
                continue

            color = grid[r0][c0]
            stack = [(r0, c0)]
            visited[r0][c0] = True
            coords = []

            while stack:
                r, c = stack.pop()
                coords.append((r, c))
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < H and 0 <= nc < W
                            and not visited[nr][nc]
                            and grid[nr][nc] == color):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            min_r = min(r for r, _ in coords)
            max_r = max(r for r, _ in coords)
            min_c = min(c for _, c in coords)
            max_c = max(c for _, c in coords)
            h = max_r - min_r + 1
            w = max_c - min_c + 1

            if h <= 2 or w <= 2:
                continue

            # Check whether the bounding-box perimeter is exactly this color.
            perimeter_ok = True
            for c in range(min_c, max_c + 1):
                if grid[min_r][c] != color or grid[max_r][c] != color:
                    perimeter_ok = False
                    break
            if perimeter_ok:
                for r in range(min_r, max_r + 1):
                    if grid[r][min_c] != color or grid[r][max_c] != color:
                        perimeter_ok = False
                        break

            if not perimeter_ok:
                continue

            # Primary rule: a one-cell-thick rectangular frame.
            perimeter_cells = h * w - (h - 2) * (w - 2)
            if len(coords) == perimeter_cells:
                interior = extract(min_r + 1, max_r, min_c + 1, max_c)
                add_candidate(exact_candidates, min_r, min_c, interior)
                continue

            # Fallback: a thick rectangular border, i.e. the component is a
            # solid rectangular ring around a rectangular hole.
            hole_r1 = hole_c1 = H
            hole_r2 = hole_c2 = -1
            total_color_cells = 0

            for r in range(min_r, max_r + 1):
                for c in range(min_c, max_c + 1):
                    if grid[r][c] == color:
                        total_color_cells += 1
                    else:
                        hole_r1 = min(hole_r1, r)
                        hole_r2 = max(hole_r2, r)
                        hole_c1 = min(hole_c1, c)
                        hole_c2 = max(hole_c2, c)

            if hole_r2 < 0:
                continue

            if not (min_r < hole_r1 and hole_r2 < max_r
                    and min_c < hole_c1 and hole_c2 < max_c):
                continue

            # All cells in the hole must be non-border-color.
            ok = True
            for r in range(hole_r1, hole_r2 + 1):
                for c in range(hole_c1, hole_c2 + 1):
                    if grid[r][c] == color:
                        ok = False
                        break
                if not ok:
                    break

            if ok:
                # Everything in the outer bbox outside the hole must be border-color.
                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
                        in_hole = (hole_r1 <= r <= hole_r2 and
                                   hole_c1 <= c <= hole_c2)
                        if not in_hole and grid[r][c] != color:
                            ok = False
                            break
                    if not ok:
                        break

            if ok and total_color_cells == len(coords):
                interior = extract(hole_r1, hole_r2, hole_c1, hole_c2)
                add_candidate(loose_candidates, min_r, min_c, interior)

    result = choose(exact_candidates)
    if result is None:
        result = choose(loose_candidates)
    if result is None:
        result = [[0]]

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Allow string rows, though the stated input is lists of ints.
    if isinstance(grid[0], str):
        grid = [[int(ch) for ch in row] for row in grid]

    H = len(grid)
    W = len(grid[0])

