                count += 1

                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < H
                        and 0 <= nc < W
                        and not visited[nr][nc]
                        and grid[nr][nc] == color
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            h = max_r - min_r + 1
            w = max_c - min_c + 1

            if h < 3 or w < 3:
                continue

            # A one-cell-thick rectangular outline has exactly these cells.
            perimeter_count = h * w - (h - 2) * (w - 2)
            if count != perimeter_count:
                continue

            # Verify that the whole bounding-box perimeter is this color.
            ok = True
            for c in range(min_c, max_c + 1):
                if grid[min_r][c] != color or grid[max_r][c] != color:
                    ok = False
                    break

            if ok:
                for r in range(min_r, max_r + 1):
                    if grid[r][min_c] != color or grid[r][max_c] != color:
                        ok = False
                        break

            if not ok:
                continue

            interior = [
                [int(grid[r][c]) for c in range(min_c + 1, max_c)]
                for r in range(min_r + 1, max_r)
            ]
            area = (h - 2) * (w - 2)
            candidates.append((area, min_r, min_c, interior))

    if not candidates:
        return [[0]]

    # If more than one outline is present, use the largest interior.
    best = max(candidates, key=lambda x: (x[0], -x[1], -x[2]))
    return best[3]

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return [row[:] for row in grid]

    # Find the vertical separator.  In the examples it is a full column of 5s.
    sep = None
    for c in range(W):
        if all(grid[r][c] == 5 for r in range(H)):
            sep = c
            break

    # Fallback: any full-height non-background column.
    if sep is None:
        candidates = []
        for c in range(W):
            first = grid[0][c]
            if first != 0 and all(grid[r][c] == first for r in range(H)):
                candidates.append(c)

        if candidates:
            def score(c):
                left_has = any(grid[r][cc] != 0 for r in range(H) for cc in range(c))
                right_has = any(grid[r][cc] != 0 for r in range(H) for cc in range(c + 1, W))
                return (
                    0 if (left_has and right_has) else 1,
                    abs(c - (W - 1) / 2)
                )
            candidates.sort(key=score)
            sep = candidates[0]

    # If no separator can be identified, leave the grid unchanged.
    if sep is None:
        return [row[:] for row in grid]

    visited = [[False] * W for _ in range(H)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    left_shapes = set()
    right_components = []

    for r in range(H):
        for c in range(W):
            if c == sep or grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True

            cells = []
            min_r = max_r = r
            min_c = max_c = c

            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))

                if rr < min_r:
                    min_r = rr
                if rr > max_r:
                    max_r = rr
                if cc < min_c:
                    min_c = cc
                if cc > max_c:
                    max_c = cc

                for dr, dc in dirs:
                    nr, nc = rr + dr, cc + dc
                    if (
                        0 <= nr < H
                        and 0 <= nc < W
                        and nc != sep
                        and not visited[nr][nc]
                        and grid[nr][nc] == color
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            cell_set = set(cells)
            pattern = tuple(
                tuple(1 if (rr, cc) in cell_set else 0 for cc in range(min_c, max_c + 1))
                for rr in range(min_r, max_r + 1)
            )

            key = (color, pattern)

            if c < sep:
                left_shapes.add(key)
            else:
                right_components.append((key, cells))

    result = [row[:] for row in grid]
    to_erase = set()

    # Keep a right-side object only if the same color/shape appears on the left.
    for key, cells in right_components:
        if key not in left_shapes:
            to_erase.update(cells)

    for r, c in to_erase:
        if c > sep:
            result[r][c] = 0

    return result

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Convert to plain Python ints/list rows (also handles strings or numpy rows).
    rows = [[int(cell) for cell in row] for row in grid]
    if not rows:
        return []

    width = len(rows[0])

    # Count how often each exact row occurs.
    counts = Counter(tuple(row) for row in rows)

    # Remember the first occurrence of each row for stable tie-breaking.
    first_index = {}
    for i, row in enumerate(rows):
        t = tuple(row)
        if t not in first_index:
            first_index[t] = i

    # The template row is a row containing background 0 and at least one marker.
    candidates = [
        row for row in counts
        if any(v == 0 for v in row) and any(v != 0 for v in row)
    ]

    # Fallback if no mixed 0/non-zero row exists.
    if not candidates:
        candidates = list(counts.keys())

    # Choose the most frequent candidate; if tied, choose the earliest one.
    template = max(candidates, key=lambda row: (counts[row], -first_index[row]))

    # Copy non-zero template cells to every row.
    out = [row[:] for row in rows]
    for r in range(len(rows)):
        for c in range(width):
            if template[c] != 0:
                out[r][c] = template[c]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    # Work with plain ints/lists even if a numpy array or strings are given.
    orig = [[int(grid[r][c]) for c in range(w)] for r in range(h)]
    out = [row[:] for row in orig]

    # Locations of the 5-line(s), grouped by row and column.
    row_fives = {}
    col_fives = {}
    for r in range(h):
        for c in range(w):
            if orig[r][c] == 5:
                row_fives.setdefault(r, []).append(c)
                col_fives.setdefault(c, []).append(r)

    # For each non-background, non-5 pixel, connect it by a straight
    # horizontal/vertical line to the nearest 5 in the same row or column.
    for r in range(h):
        for c in range(w):
            color = orig[r][c]
            if color == 0 or color == 5:
                continue

            candidates = []

            if r in row_fives:
                c5 = min(row_fives[r], key=lambda x: (abs(x - c), x))
                candidates.append((r, c5))

            if c in col_fives:
                r5 = min(col_fives[c], key=lambda x: (abs(x - r), x))
                candidates.append((r5, c))

            if not candidates:
                continue

            # Nearest aligned 5; break ties by preferring a row match.
            tr, tc = min(
                candidates,
                key=lambda t: (abs(t[0] - r) + abs(t[1] - c), 0 if t[0] == r else 1)
            )

            dr = 0 if tr == r else (1 if tr > r else -1)
            dc = 0 if tc == c else (1 if tc > c else -1)

            rr, cc = r, c
            while (rr, cc) != (tr, tc):
                rr += dr
                cc += dc

                if not (0 <= rr < h and 0 <= cc < w):
                    break
                if orig[rr][cc] == 5:
                    break
                if orig[rr][cc] != 0:
                    break

                if out[rr][cc] == 0:
                    out[rr][cc] = color

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not sixes:
        return out

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def passable(r, c):
        return grid[r][c] in (0, 6)

    # Label connected components of empty cells, treating 6 as empty.
    comp_id = [[-1] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if passable(r, c) and comp_id[r][c] == -1:
                cid = len(components)
                q = deque([(r, c)])
                comp_id[r][c] = cid
                touches_boundary = False
                cells = []

                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                        touches_boundary = True

                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w:
                            if comp_id[nx][ny] == -1 and passable(nx, ny):
                                comp_id[nx][ny] = cid
                                q.append((nx, ny))

                components.append({
                    "touches_boundary": touches_boundary,
                    "cells": cells,
                })

    def has_enclosed_empty_hole(cid):
        """
        Return True if this empty component surrounds another empty component.
        In the examples, that means the 6 is in a larger ring/annulus rather
        than in the innermost empty region.
        """
        visited = [[False] * w for _ in range(h)]
        q = deque()

        # Flood the complement of this component starting from the grid border.
        for r in range(h):
            for c in (0, w - 1):
                if comp_id[r][c] != cid and not visited[r][c]:
                    visited[r][c] = True
                    q.append((r, c))

        for c in range(w):
            for r in (0, h - 1):
                if comp_id[r][c] != cid and not visited[r][c]:
                    visited[r][c] = True
                    q.append((r, c))

        while q:
            x, y = q.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < h and 0 <= ny < w:
                    if comp_id[nx][ny] != cid and not visited[nx][ny]:
                        visited[nx][ny] = True
                        q.append((nx, ny))

        # Any unvisited empty cell means there is an enclosed inner empty region.
        for r in range(h):
            for c in range(w):
                if comp_id[r][c] != cid and not visited[r][c] and passable(r, c):
                    return True

        return False

    keep_component = {}

    for cid, info in enumerate(components):
        contains_six = any(grid[r][c] == 6 for r, c in info["cells"])
        if not contains_six:
            continue

        if info["touches_boundary"]:
            keep_component[cid] = False
        else:
            keep_component[cid] = not has_enclosed_empty_hole(cid)

    for r, c in sixes:
        cid = comp_id[r][c]
        if not keep_component.get(cid, False):
            out[r][c] = 0

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not sixes:
        return out

    # Collect non-background, non-6 colors.
    info = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != 6:
                if v not in info:
                    info[v] = {
                        "min_r": r, "max_r": r,
                        "min_c": c, "max_c": c,
                        "count": 0,
                    }
                d = info[v]
                d["min_r"] = min(d["min_r"], r)
                d["max_r"] = max(d["max_r"], r)
                d["min_c"] = min(d["min_c"], c)
                d["max_c"] = max(d["max_c"], c)
                d["count"] += 1

    if not info:
        return out

    def bbox_area(v):
        d = info[v]
        return (d["max_r"] - d["min_r"] + 1) * (d["max_c"] - d["min_c"] + 1)

    # Flood-fill from the border through every cell except the given wall color.
    # Using 4-neighbour moves makes diagonally-touching wall pixels form a
    # proper barrier, which is required for the diagonal frames.
    def outside_reached(wall):
        visited = [[False] * w for _ in range(h)]
        q = deque()

        def try_start(r, c):
            if 0 <= r < h and 0 <= c < w:
                if not visited[r][c] and grid[r][c] != wall:
                    visited[r][c] = True
                    q.append((r, c))

        for r in range(h):
            try_start(r, 0)
            try_start(r, w - 1)
        for c in range(w):
            try_start(0, c)
            try_start(h - 1, c)

        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not visited[nr][nc] and grid[nr][nc] != wall:
                        visited[nr][nc] = True
                        q.append((nr, nc))

        return visited

    # Choose the inner frame:
    # among colors that actually enclose at least one non-wall cell, pick the
    # one with the smallest bounding box.  If no such color exists, fall back
    # to the smallest bounding-box color.
    hole_colors = []
    for v in info:
        visited = outside_reached(v)
        has_hole = False
        for r in range(h):
            for c in range(w):
                if grid[r][c] != v and not visited[r][c]:
                    has_hole = True
                    break
            if has_hole:
                break
        if has_hole:
            hole_colors.append(v)

    if hole_colors:
        barrier = min(hole_colors, key=lambda v: (bbox_area(v), info[v]["count"]))
    else:
        barrier = min(info, key=lambda v: (bbox_area(v), info[v]["count"]))

    # The 6 is kept iff it is not reachable from the border without crossing
    # the inner frame color.
    visited = outside_reached(barrier)

    for r, c in sixes:
        if visited[r][c]:
            out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Rows that are completely non-background are the horizontal beams.
    horiz = [all(cell != 0 for cell in row) for row in grid]

    for c in range(w):
        non_zero_rows = [r for r in range(h) if grid[r][c] != 0]
        if not non_zero_rows:
            continue

        # The vertical beam colour is normally the colour at the ends of the
        # non-zero span.  If the ends disagree, fall back to the most common
        # colour outside horizontal rows.
        top_col = grid[non_zero_rows[0]][c]
        bot_col = grid[non_zero_rows[-1]][c]

        if top_col == bot_col:
            vertical_col = top_col
        else:
            counts = {}
            for r in non_zero_rows:
                if not horiz[r]:
                    counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
            if not counts:
                continue
            vertical_col = max(counts.items(), key=lambda x: x[1])[0]

        # Remove this vertical beam only if it is broken by another colour in
        # a horizontal row.
        broken = any(
            horiz[r] and grid[r][c] != 0 and grid[r][c] != vertical_col
            for r in range(h)
        )

        if broken:
            for r in range(h):
                if out[r][c] == vertical_col:
                    out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])

    # Find the vertical divider made of 5s.
    five_counts = [0] * w
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                five_counts[c] += 1

    max_fives = max(five_counts)
    if max_fives == 0:
        return [row[:] for row in grid]

    # Use the column with the most 5s as the dividing column.
    divider_col = five_counts.index(max_fives)

    # Compare the total "weight" on each side.
    # Weight is the sum of the cell values (color numbers), excluding the 5 divider.
    left_sum = 0
    right_sum = 0

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 5:
                continue
            if c < divider_col:
                left_sum += v
            elif c > divider_col:
                right_sum += v

    # If equal, keep both sides.
    if left_sum == right_sum:
        return [row[:] for row in grid]

    remove_left = left_sum > right_sum

    # Remove all non-divider colored cells from the heavier side.
    result = []
    for r in range(h):
        new_row = []
        for c in range(w):
            v = grid[r][c]
            if v != 5:
                if remove_left and c < divider_col:
                    v = 0
                elif (not remove_left) and c > divider_col:
                    v = 0
            new_row.append(int(v))
        result.append(new_row)

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    out = [[int(grid[r][c]) for c in range(w)] for r in range(h)]

    points_by_color = {}
    all_points = []
    for r in range(h):
        for c in range(w):
            v = int(grid[r][c])
            if v != 0:
                points_by_color.setdefault(v, []).append((r, c))
                all_points.append((r, c, v))

    if not all_points:
        return out

    def key_value(orient, r, c):
        if orient == "H":
            return r
        if orient == "V":
            return c
        if orient == "D1":  # r - c constant, slope +1
            return r - c
        return r + c         # D2, slope -1

    def find_line(min_count):
        best = None
        for color, pts in points_by_color.items():
            groups = {}
            for orient in ("H", "V", "D1", "D2"):
                for r, c in pts:
                    k = key_value(orient, r, c)
                    groups.setdefault((orient, k), []).append((r, c))

            for (orient, k), group in groups.items():
                if len(group) >= min_count:
                    rs = [p[0] for p in group]
                    cs = [p[1] for p in group]
                    span = max(max(rs) - min(rs), max(cs) - min(cs))
                    score = (len(group), span, len(pts))
                    if best is None or score > best[0]:
                        best = (score, color, orient, k, group)

        if best is None:
            return None
        return best[1], best[2], best[3], best[4]

    line_info = find_line(3)
    if line_info is None:
        line_info = find_line(2)
    if line_info is None:
        return out

    line_color, orient, line_key, _ = line_info

    dots = []
    for r, c, v in all_points:
        if v == line_color and key_value(orient, r, c) == line_key:
            continue
        dots.append((r, c, v))

    for dr, dc, dv in dots:
        if orient == "H":
            delta = line_key - dr
            if delta == 0:
                continue
            sign = 1 if delta > 0 else -1
            steps = abs(delta) - 1
        elif orient == "V":
            delta = line_key - dc
            if delta == 0:
                continue
            sign = 1 if delta > 0 else -1
            steps = abs(delta) - 1
        elif orient == "D1":
            delta = line_key - (dr - dc)
            if delta == 0:
                continue
            sign = 1 if delta > 0 else -1
            steps = (abs(delta) - 1) // 2
        else:  # D2
            delta = line_key - (dr + dc)
            if delta == 0:
                continue
            sign = 1 if delta > 0 else -1
            steps = (abs(delta) - 1) // 2

        for i in range(1, steps + 1):
            if orient == "H":
                r, c = dr + i * sign, dc
            elif orient == "V":
                r, c = dr, dc + i * sign
            elif orient == "D1":
                r, c = dr + i * sign, dc - i * sign
            else:
                r, c = dr + i * sign, dc + i * sign

            if not (0 <= r < h and 0 <= c < w):
                break

            if out[r][c] == 0:
                out[r][c] = dv
            elif out[r][c] != dv:
                break

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Copy the grid and convert to plain Python ints.
    out = [[int(v) for v in row] for row in grid]
    if not out:
        return out

    # Find the dominant non-zero colour (5 in the given examples).
    counts = {}
    for row in out:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if not counts:
        return out

    target = max(counts, key=lambda color: (counts[color], color))

    # Bounding box of the target colour.
    min_r = min_c = 10**9
    max_r = max_c = -10**9

    for r, row in enumerate(out):
        for c, v in enumerate(row):
            if v == target:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    # Integer center of the bounding box.
    center_r = (min_r + max_r) // 2
    center_c = (min_c + max_c) // 2

    out[center_r][center_c] = 1
    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if grid is None:
        return []

    h = len(grid)
    if h == 0:
        return []

    grid = [[int(v) for v in row] for row in grid]
    h = len(grid)
    w = max((len(row) for row in grid), default=0)
    if h == 0 or w == 0:
        return []

    # Normalize just in case rows are ragged.
    grid = [row + [0] * (w - len(row)) for row in grid]

    def component_direction():
        """
        Detect whether the non-zero objects are arranged in a horizontal line
        or a vertical line.

        Returns:
            "vertical"   -> objects are side-by-side, so duplicate vertically
            "horizontal" -> objects are stacked, so duplicate horizontally
            None         -> not enough information
        """
        visited = [[False] * w for _ in range(h)]
        boxes = []

        for y in range(h):
            for x in range(w):
                if grid[y][x] != 0 and not visited[y][x]:
                    stack = [(y, x)]
                    visited[y][x] = True
                    minx = maxx = x
                    miny = maxy = y

                    while stack:
                        cy, cx = stack.pop()

                        if cy < miny:
                            miny = cy
                        if cy > maxy:
                            maxy = cy
                        if cx < minx:
                            minx = cx
                        if cx > maxx:
                            maxx = cx

                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = cy + dy, cx + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not visited[ny][nx] and grid[ny][nx] != 0:
                                    visited[ny][nx] = True
                                    stack.append((ny, nx))

                    boxes.append((minx, maxx, miny, maxy))

        n = len(boxes)
        if n < 2:
            return None

        x_overlap = 0
        y_overlap = 0

        for i in range(n):
            for j in range(i + 1, n):
                x1a, x2a, y1a, y2a = boxes[i]
                x1b, x2b, y1b, y2b = boxes[j]

                # Horizontal intervals overlap -> objects stacked vertically.
                if x2a >= x1b and x2b >= x1a:
                    x_overlap += 1

                # Vertical intervals overlap -> objects side-by-side horizontally.
                if y2a >= y1b and y2b >= y1a:
                    y_overlap += 1

        if y_overlap > x_overlap:
            return "vertical"
        if x_overlap > y_overlap:
            return "horizontal"

        return None

    direction = component_direction()

    if direction is None:
        empty_rows = [y for y in range(h) if all(grid[y][x] == 0 for x in range(w))]
        empty_cols = [x for x in range(w) if all(grid[y][x] == 0 for y in range(h))]

        if empty_cols and not empty_rows:
            direction = "vertical"
        elif empty_rows and not empty_cols:
            direction = "horizontal"
        else:
            # Fallback: duplicate in the shorter dimension.
            if h < w:
                direction = "vertical"
            elif h > w:
                direction = "horizontal"
            else:
                direction = "vertical"

    if direction == "vertical":
        zero_row = [0] * w
        return [row[:] for row in grid] + [zero_row] + [row[:] for row in grid]

    return [row + [0] + row[:] for row in grid]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows = len(grid)
    cols = max(len(row) for row in grid)

    # Make a padded copy so every row has the same length.
    out = [list(row) + [0] * (cols - len(row)) for row in grid]

    boxes = {}
    counts = {}

    for r in range(rows):
        for c in range(cols):
            v = grid[r][c] if c < len(grid[r]) else 0
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
                if v in boxes:
                    r1, r2, c1, c2 = boxes[v]
                    boxes[v] = (min(r1, r), max(r2, r), min(c1, c), max(c2, c))
                else:
                    boxes[v] = (r, r, c, c)

    if not boxes:
        return out

    # Fill the bounding box of each colour.  For the given examples/tests there
    # is only one colour, so this simply fills the bounding rectangle.
    for color in sorted(boxes, key=lambda x: (counts[x], x)):
        r1, r2, c1, c2 = boxes[color]
        fill = int(color)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                out[r][c] = fill

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    colors = set()
    for row in grid:
        for v in row:
            if v != 0:
                colors.add(v)

    candidates = []

    for c in colors:
        min_r, max_r = h, -1
        min_c, max_c = w, -1
        count = 0

        for r in range(h):
            for cc in range(w):
                if grid[r][cc] == c:
                    count += 1
                    if r < min_r:
                        min_r = r
                    if r > max_r:
                        max_r = r
                    if cc < min_c:
                        min_c = cc
                    if cc > max_c:
                        max_c = cc

        if count == 0:
            continue

        area = (max_r - min_r + 1) * (max_c - min_c + 1)

        # The moved object is the colour that forms one solid rectangle.
        if count == area:
            # Prefer a rectangle that can actually move left.
            edge_blocked = 1 if min_c == 0 else 0
            candidates.append((edge_blocked, area, c, min_r, max_r, min_c, max_c))

    if not candidates:
        return out

    # If there is more than one rectangular colour, move the smallest one.
    candidates.sort(key=lambda x: (x[0], x[1], x[2], x[3], x[4]))
    _, _, c, min_r, max_r, min_c, max_c = candidates[0]

    for r in range(min_r, max_r + 1):
        # Shift the rectangle one cell left.
        if min_c - 1 >= 0:
            out[r][min_c - 1] = c

        # The rightmost old column is vacated; fill it from the original
        # pixel immediately to its right (or background if none exists).
        fill = grid[r][max_c + 1] if max_c + 1 < w else 0
        out[r][max_c] = fill

    return out

