def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    # Most frequent non-background color
    freq = {}
    for row in grid:
        for v in row:
            if v != 0:
                freq[v] = freq.get(v, 0) + 1

    if not freq:
        return [row[:] for row in grid]

    target = max(freq, key=lambda c: (freq[c], -c))

    # Mask of target cells
    mask = [[grid[r][c] == target for c in range(W)] for r in range(H)]

    # Prefix sum for fast 2D sum queries
    ps = [[0] * (W + 1) for _ in range(H + 1)]
    for r in range(H):
        row_sum = 0
        for c in range(W):
            row_sum += mask[r][c]
            ps[r + 1][c + 1] = ps[r][c + 1] + row_sum

    def rect_sum(r1, c1, r2, c2):
        # inclusive bounds
        return (ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1]
                - ps[r2 + 1][c1] + ps[r1][c1])

    def is_valid_square(r1, c1, r2, c2):
        # square side >= 2
        if r2 <= r1 or c2 <= c1:
            return False
        h = r2 - r1 + 1
        w = c2 - c1 + 1
        if h != w or h < 2:
            return False

        # Each side must contain at least one target pixel
        if rect_sum(r1, c1, r1, c2) == 0:
            return False
        if rect_sum(r2, c1, r2, c2) == 0:
            return False
        if rect_sum(r1, c1, r2, c1) == 0:
            return False
        if rect_sum(r1, c2, r2, c2) == 0:
            return False

        # Interior must contain no target pixel
        if r2 > r1 + 1 and c2 > c1 + 1:
            if rect_sum(r1 + 1, c1 + 1, r2 - 1, c2 - 1) > 0:
                return False

        return True

    # Collect all valid squares
    valid = []
    max_side = min(H, W)
    for side in range(2, max_side + 1):
        for r1 in range(0, H - side + 1):
            r2 = r1 + side - 1
            for c1 in range(0, W - side + 1):
                c2 = c1 + side - 1
                if is_valid_square(r1, c1, r2, c2):
                    valid.append((r1, c1, r2, c2))

    if not valid:
        return [[0] * W for _ in range(H)]

    # Keep inclusion-maximal squares: discard any square contained in another valid square.
    # Process larger squares first.
    valid.sort(key=lambda x: (-(x[2] - x[0] + 1), x[0], x[1]))

    maximal = []
    for sq in valid:
        r1, c1, r2, c2 = sq
        contained = False
        for or1, oc1, or2, oc2 in maximal:
            if or1 <= r1 and oc1 <= c1 and or2 >= r2 and oc2 >= c2:
                contained = True
                break
        if not contained:
            maximal.append(sq)

    out = [[0] * W for _ in range(H)]
    for r1, c1, r2, c2 in maximal:
        for c in range(c1, c2 + 1):
            out[r1][c] = target
            out[r2][c] = target
        for r in range(r1, r2 + 1):
            out[r][c1] = target
            out[r][c2] = target

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return []

    result = [[0] * W for _ in range(H)]

    # Count non-background colors.
    freq = {}
    for row in grid:
        for v in row:
            if v != 0:
                freq[v] = freq.get(v, 0) + 1

    if not freq:
        return result

    def find_largest_squares(color: int):
        """
        Return (max_side, list_of_squares_with_that_side) for this color.
        A square is valid if:
          - side length >= 2
          - each of its four sides contains at least two pixels of this color
          - its interior contains no pixel of this color
        """
        mask = [[1 if grid[r][c] == color else 0 for c in range(W)] for r in range(H)]

        # Prefix sums for fast rectangle queries.
        ps = [[0] * (W + 1) for _ in range(H + 1)]
        for r in range(H):
            row_sum = 0
            for c in range(W):
                row_sum += mask[r][c]
                ps[r + 1][c + 1] = ps[r][c + 1] + row_sum

        def rect_sum(r1, c1, r2, c2):
            if r1 > r2 or c1 > c2:
                return 0
            return (ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1]
                    - ps[r2 + 1][c1] + ps[r1][c1])

        def valid(r1, c1, r2, c2):
            side = r2 - r1 + 1
            if side < 2:
                return False

            # At least two pixels of this color on each side.
            if rect_sum(r1, c1, r1, c2) < 2:
                return False
            if rect_sum(r2, c1, r2, c2) < 2:
                return False
            if rect_sum(r1, c1, r2, c1) < 2:
                return False
            if rect_sum(r1, c2, r2, c2) < 2:
                return False

            # Interior must be free of this color.
            if side > 2 and rect_sum(r1 + 1, c1 + 1, r2 - 1, c2 - 1) > 0:
                return False

            return True

        max_side = 0
        best_squares = []

        # Search from largest to smallest; stop at the first size with a valid square.
        for side in range(min(H, W), 1, -1):
            found = []
            for r1 in range(0, H - side + 1):
                r2 = r1 + side - 1
                for c1 in range(0, W - side + 1):
                    c2 = c1 + side - 1
                    if valid(r1, c1, r2, c2):
                        found.append((r1, c1, r2, c2))

            if found:
                max_side = side
                best_squares = found
                break

        return max_side, best_squares

    candidates = []
    for color, count in freq.items():
        max_side, squares = find_largest_squares(color)
        if max_side > 0:
            # Prefer larger square, then more frequent color, then smaller color id.
            candidates.append((max_side, count, -color, color, squares))

    if not candidates:
        return result

    candidates.sort(reverse=True)
    _, _, _, color, squares = candidates[0]

    # Draw all largest valid square borders.
    for r1, c1, r2, c2 in squares:
        for c in range(c1, c2 + 1):
            result[r1][c] = color
            result[r2][c] = color
        for r in range(r1, r2 + 1):
            result[r][c1] = color
            result[r][c2] = color

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    h, w = len(grid), len(grid[0])
    orig = [list(row) for row in grid]
    out = [row[:] for row in orig]

    def get_cells(direction, offset):
        cells = []
        if direction == 0:
            for c in range(w):
                cells.append((offset, c))
        elif direction == 1:
            for r in range(h):
                cells.append((r, offset))
        elif direction == 2:
            for r in range(h):
                c = r - offset
                if 0 <= c < w:
                    cells.append((r, c))
        else:
            for r in range(h):
                c = offset - r
                if 0 <= c < w:
                    cells.append((r, c))
        return cells

    def has_enough_contiguous(cell_values, color, min_count=4):
        positions = [i for i, v in enumerate(cell_values) if v == color]
        if len(positions) < min_count:
            return False
        gaps = sum(1 for i in range(1, len(positions)) if positions[i] - positions[i-1] > 1)
        return gaps <= 1

    lines = {}

    for direction in range(4):
        if direction == 0:
            offsets = range(h)
        elif direction == 1:
            offsets = range(w)
        elif direction == 2:
            offsets = range(-(w - 1), h)
        else:
            offsets = range(h + w - 1)

        for offset in offsets:
            cells = get_cells(direction, offset)
            if len(cells) < 4:
                continue
            vals = [orig[r][c] for r, c in cells]
            counts = {}
            for v in vals:
                if v != 0:
                    counts[v] = counts.get(v, 0) + 1
            if not counts:
                continue
            color = max(counts, key=counts.get)
            if counts[color] >= 4 and has_enough_contiguous(vals, color):
                lines[(direction, offset)] = color

    for r in range(h):
        for c in range(w):
            v = orig[r][c]
            if v == 0:
                continue
            gap_colors = []
            for d, off in [(0, r), (1, c), (2, r - c), (3, r + c)]:
                if (d, off) in lines and lines[(d, off)] != v:
                    gap_colors.append(lines[(d, off)])
            if gap_colors:
                out[r][c] = gap_colors[0]

    return out

