    return [[2] for _ in range(marked_count)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if grid is None:
        return []

    # Normalize to plain Python lists of ints.
    grid = [[int(v) for v in row] for row in grid]

    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return grid

    row_nonzero = [any(cell != 0 for cell in row) for row in grid]
    col_nonzero = [any(grid[r][c] != 0 for r in range(H)) for c in range(W)]

    def separator_count(flags: list[bool]) -> int:
        """Count contiguous all-zero lines that have nonzero content on both sides."""
        count = 0
        i = 0
        n = len(flags)
        while i < n:
            if not flags[i]:
                j = i
                while j < n and not flags[j]:
                    j += 1
                if i > 0 and j < n:
                    count += 1
                i = j
            else:
                i += 1
        return count

    row_seps = separator_count(row_nonzero)
    col_seps = separator_count(col_nonzero)

    if row_seps > col_seps:
        mirror_horizontally = True
    elif col_seps > row_seps:
        mirror_horizontally = False
    else:
        # Fallback: reflect along the shorter dimension.
        if H > W:
            mirror_horizontally = True
        elif W > H:
            mirror_horizontally = False
        else:
            mirror_horizontally = True

    if mirror_horizontally:
        return [row + [0] + row[::-1] for row in grid]
    else:
        zero_row = [0] * W
        return [row[:] for row in grid] + [zero_row] + [row[:] for row in grid[::-1]]

