    components = []
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True
            cells = []

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))

                for dr, dc in directions:
                    nr, nc = cr + dr, cc + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and not visited[nr][nc]
                        and grid[nr][nc] == color
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            min_r = min(row for row, _ in cells)
            max_r = max(row for row, _ in cells)
            min_c = min(col for _, col in cells)
            max_c = max(col for _, col in cells)

            cell_set = set(cells)
            shape = tuple(
                tuple(
                    1 if (row, col) in cell_set else 0
                    for col in range(min_c, max_c + 1)
                )
                for row in range(min_r, max_r + 1)
            )

            components.append((color, cells, shape))

    shape_counts = Counter(shape for _, _, shape in components)

    result = [[0] * w for _ in range(h)]
    for color, cells, shape in components:
        if shape_counts[shape] > 1:
