def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    out = [[int(v) for v in row] for row in grid]

    fives = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 5:
                fives.append((r, c))

    if not fives:
        return out

    five_set = set(fives)
    target = None

    # The 5s are arranged in 180-degree rotational symmetry about one empty cell.
    # Find that center explicitly.
    candidates = []
    for r in range(H):
        for c in range(W):
            if (r, c) in five_set:
                continue
            ok = True
            for r0, c0 in fives:
                if (2 * r - r0, 2 * c - c0) not in five_set:
                    ok = False
                    break
            if ok:
                candidates.append((r, c))

    if candidates:
        if len(candidates) > 1:
            sr = sum(p[0] for p in fives)
            sc = sum(p[1] for p in fives)
            n = len(fives)
            candidates.sort(
                key=lambda p: (p[0] * n - sr) ** 2 + (p[1] * n - sc) ** 2
            )
        target = candidates[0]

    # Fallback 1: midpoint of the two missing cells of the 2x2 L-shaped groups.
    if target is None:
        missing = []
        for r in range(H - 1):
            for c in range(W - 1):
                cnt = 0
                miss = None
                for rr in (r, r + 1):
                    for cc in (c, c + 1):
                        if grid[rr][cc] == 5:
                            cnt += 1
                        else:
                            miss = (rr, cc)
                if cnt == 3:
                    missing.append(miss)

        if len(missing) == 2:
            r = (missing[0][0] + missing[1][0]) // 2
            c = (missing[0][1] + missing[1][1]) // 2
            if 0 <= r < H and 0 <= c < W and out[r][c] == 0:
                target = (r, c)

    # Fallback 2: centroid of all 5s, which is the symmetry center for valid inputs.
    if target is None:
        n = len(fives)
        sr = sum(p[0] for p in fives)
        sc = sum(p[1] for p in fives)
        r = (sr + n // 2) // n
        c = (sc + n // 2) // n
        r = max(0, min(H - 1, r))
        c = max(0, min(W - 1, c))
        target = (r, c)

    out[target[0]][target[1]] = 1
    return out

