                        max_c = c

        area = (max_r - min_r + 1) * (max_c - min_c + 1)

        # Count non-background cells of other colors inside this color's bbox.
        other_nonzero = 0
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                v = g[r][c]
                if v != 0 and v != color:
                    other_nonzero += 1

        info[color] = (min_r, max_r, min_c, max_c, area, count, other_nonzero)

    # Prefer colors that are not perfectly solid rectangles.
    candidates = [c for c in info if info[c][5] < info[c][4]]
    if not candidates:
        candidates = list(info.keys())

    # If there are several candidates, choose the one whose bbox contains
    # the most other colored pixels, then the one with the largest hole/area gap.
    target = max(
        candidates,
        key=lambda c: (
            info[c][6],               # other non-zero pixels inside bbox
            info[c][4] - info[c][5],  # missing cells inside bbox
            info[c][5],               # total pixels of this color
            c,
        ),
    )

    min_r, max_r, min_c, max_c = info[target][:4]

    out = [[0] * W for _ in range(H)]
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            out[r][c] = target

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Normalize to a list of lists of Python ints.
    grid = [list(map(int, row)) for row in grid]

    H = len(grid)
    W = len(grid[0])
    if W == 0:
        return [list(row) for row in grid]

    # Horizontal marker:
    # a suffix of the top row consisting of 1s, with zeros below those columns.
    marker_h = 0
    for c in range(W - 1, -1, -1):
        if grid[0][c] != 1:
            break
        ok = True
        for r in range(1, H):
            if grid[r][c] != 0:
                ok = False
                break
        if ok:
            marker_h += 1
        else:
            break

    # If the whole grid were counted as marker, there is no stamp.
    if marker_h == W:
        marker_h = 0

    # Vertical marker:
    # a suffix of the left column consisting of 1s, with zeros to the right in those rows.
    marker_v = 0
    for r in range(H - 1, -1, -1):
        if grid[r][0] != 1:
            break
        ok = True
        for c in range(1, W):
            if grid[r][c] != 0:
                ok = False
                break
        if ok:
            marker_v += 1
        else:
            break

    # If the whole grid were counted as marker, there is no stamp.
    if marker_v == H:
        marker_v = 0

    # Repeat horizontally.
    if marker_h > 0:
        stamp_w = W - marker_h
        copies = marker_h + 1
        stamp = [row[:stamp_w] for row in grid]
        zero_sep = [0] * stamp_w

        out = []
        for row in stamp:
            new_row = []
            for i in range(copies):
                new_row.extend(row)
                if i != copies - 1:
                    new_row.extend(zero_sep)
            out.append(new_row)
        return out

    # Repeat vertically.
    if marker_v > 0:
        stamp_h = H - marker_v
        copies = marker_v + 1
        stamp = [row[:] for row in grid[:stamp_h]]
        zero_sep_row = [0] * W

        out = []
        for i in range(copies):
            for row in stamp:
                out.append(row[:])
            if i != copies - 1:
                out.append(zero_sep_row[:])
        return out

    # No marker found: leave the grid unchanged.
    return [row[:] for row in grid]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Normalize to a list of lists of Python ints.
    grid = [list(map(int, row)) for row in grid]
    H = len(grid)
    W = len(grid[0])
    if W == 0:
        return [list(row) for row in grid]

    # Crop outer all-zero rows/columns, if any.
    row_has = [any(x != 0 for x in row) for row in grid]
    col_has = [any(grid[r][c] != 0 for r in range(H)) for c in range(W)]
    if not any(row_has) or not any(col_has):
        return [row[:] for row in grid]

    r0 = row_has.index(True)
    r1 = H - 1 - row_has[::-1].index(True)
    c0 = col_has.index(True)
    c1 = W - 1 - col_has[::-1].index(True)
    if r0 > 0 or r1 < H - 1 or c0 > 0 or c1 < W - 1:
        grid = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]
        H, W = r1 - r0 + 1, c1 - c0 + 1

    candidates = []

    # Horizontal repetition:
    # stamp is a top-left all-nonzero rectangle.
    # To its right, along the top row, is a line of 1s; below those 1s are zeros.
    for sw in range(1, W):
        marker_ok = True
        for c in range(sw, W):
            if grid[0][c] != 1:
                marker_ok = False
                break
            for r in range(1, H):
                if grid[r][c] != 0:
                    marker_ok = False
                    break
            if not marker_ok:
                break
        if not marker_ok:
            continue

        sh = 0
        while sh < H:
            if all(grid[sh][c] != 0 for c in range(sw)):
                sh += 1
            else:
                break

        if sh == 0:
            continue

        # Everything below the detected stamp in the stamp columns must be zero.
        valid = True
        for r in range(sh, H):
            for c in range(sw):
                if grid[r][c] != 0:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            # copies = marker_length + 1, separator count = marker_length.
            candidates.append((sh * sw, W - sw, 0, sh, sw))

    # Vertical repetition:
    # stamp is a top-left all-nonzero rectangle.
    # Below it, along the left column, is a line of 1s; to the right of those 1s are zeros.
    for sh in range(1, H):
        marker_ok = True
        for r in range(sh, H):
            if grid[r][0] != 1:
                marker_ok = False
                break
            for c in range(1, W):
                if grid[r][c] != 0:
                    marker_ok = False
                    break
            if not marker_ok:
                break
        if not marker_ok:
            continue

        sw = 0
        while sw < W:
            if all(grid[r][sw] != 0 for r in range(sh)):
                sw += 1
            else:
                break

        if sw == 0:
            continue

        # Everything to the right of the detected stamp in the stamp rows must be zero.
        valid = True
        for r in range(sh):
            for c in range(sw, W):
                if grid[r][c] != 0:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            candidates.append((sh * sw, H - sh, 1, sh, sw))

    if candidates:
        # Prefer the largest plausible stamp; on ties, prefer a longer marker, then horizontal.
        candidates.sort(key=lambda x: (x[0], x[1], 1 - x[2]), reverse=True)
        _, marker_len, orient, sh, sw = candidates[0]

        stamp = [list(grid[r][:sw]) for r in range(sh)]
        copies = marker_len + 1

        if orient == 0:  # horizontal
            out = []
            for row in stamp:
                new_row = []
                for i in range(copies):
                    new_row.extend(row)
                    if i != copies - 1:
                        new_row.append(0)
                out.append(new_row)
            return out
        else:  # vertical
            out = []
            zero_row = [0] * sw
            for i in range(copies):
                for row in stamp:
                    out.append(row[:])
                if i != copies - 1:
                    out.append(zero_row[:])
            return out

    # Fallback for unusual cases where the strict all-nonzero stamp check is too strong.
    # Use the first detectable marker line and repeat accordingly.
    Lh = 0
    for c in range(W - 1, -1, -1):
        if grid[0][c] == 1 and all(grid[r][c] == 0 for r in range(1, H)):
            Lh += 1
        else:
            break

    if Lh > 0 and W - Lh > 0:
        sw = W - Lh
        stamp = [list(grid[r][:sw]) for r in range(H)]
        copies = Lh + 1
        out = []
        for row in stamp:
            new_row = []
            for i in range(copies):
                new_row.extend(row)
                if i != copies - 1:
                    new_row.append(0)
            out.append(new_row)
        return out

    Lv = 0
    for r in range(H - 1, -1, -1):
        if grid[r][0] == 1 and all(grid[r][c] == 0 for c in range(1, W)):
            Lv += 1
        else:
            break

    if Lv > 0 and H - Lv > 0:
        sh = H - Lv
        sw = W
        stamp = [list(grid[r][:sw]) for r in range(sh)]
        copies = Lv + 1
        out = []
        zero_row = [0] * sw
        for i in range(copies):
            for row in stamp:
                out.append(row[:])
            if i != copies - 1:
                out.append(zero_row[:])
        return out

    return [row[:] for row in grid]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    orig = [[int(v) for v in row] for row in grid]
    h = len(orig)
    w = len(orig[0]) if orig[0] else 0
    if w == 0:
        return [row[:] for row in orig]

    out = [row[:] for row in orig]

    # Collect non-background colours.
    colours = {}
    for r in range(h):
        for c in range(w):
            v = orig[r][c]
            if v != 0:
                colours.setdefault(v, []).append((r, c))

    if not colours:
        return out

    # Identify the "line" colour.  In the given puzzles it is colour 5.
    # If 5 is a straight line, use it; otherwise fall back to the most
    # prominent straight-line colour, or simply colour 5 / most common colour.
    def is_straight_line(pts):
        if len(pts) < 2:
            return False
        rows = {r for r, _ in pts}
        cols = {c for _, c in pts}
        dm = {r - c for r, c in pts}
        ds = {r + c for r, c in pts}
        return len(rows) == 1 or len(cols) == 1 or len(dm) == 1 or len(ds) == 1

    line_colours = [c for c, pts in colours.items() if is_straight_line(pts)]

    if 5 in line_colours:
        target = 5
    elif line_colours:
        target = max(line_colours, key=lambda c: len(colours[c]))
    elif 5 in colours:
        target = 5
    else:
        target = max(colours, key=lambda c: len(colours[c]))

    sources = [
        (r, c, orig[r][c])
        for r in range(h)
        for c in range(w)
        if orig[r][c] != 0 and orig[r][c] != target
    ]

    # Try left, right, up, down.  Horizontal directions are preferred on ties.
    dirs = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    for r, c, col in sources:
        best_dist = None
        best_idx = None

        for idx, (dr, dc) in enumerate(dirs):
            rr, cc = r + dr, c + dc
            dist = 1
            while 0 <= rr < h and 0 <= cc < w:
                v = orig[rr][cc]

                if v == target:
                    if (
                        best_dist is None
                        or dist < best_dist
                        or (dist == best_dist and idx < best_idx)
                    ):
                        best_dist = dist
                        best_idx = idx
                    break

                # Stop at a different non-background object; same-colour pixels
                # are allowed as pass-throughs for the same colour's extension.
                if v != 0 and v != col:
                    break

                rr += dr
                cc += dc
                dist += 1

        if best_idx is None:
            continue

        dr, dc = dirs[best_idx]
        for step in range(1, best_dist):
            rr = r + dr * step
            cc = c + dc * step
            if orig[rr][cc] == 0 or orig[rr][cc] == col:
                out[rr][cc] = col

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    """
    Rule:
    1. Consider all non-zero colours that appear on the outer border of the grid.
    2. Choose the one with the smallest total number of cells in the whole grid.
       (Ties are broken by lower colour value.)
    3. Output the axis-aligned bounding box of all cells of that colour,
       filled completely with that colour.
    """
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    # Count all non-zero colours.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = int(grid[r][c])
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    # If there are no non-zero cells, return a copy of the input.
    if not counts:
        return [list(row) for row in grid]

    # Colours touching the outer border.
    border_colors = set()

    # Top and bottom rows.
    for c in range(w):
        v = int(grid[0][c])
        if v != 0:
            border_colors.add(v)
        v = int(grid[h - 1][c])
        if v != 0:
            border_colors.add(v)

    # Left and right columns, excluding corners already processed.
    for r in range(1, h - 1):
        v = int(grid[r][0])
        if v != 0:
            border_colors.add(v)
        v = int(grid[r][w - 1])
        if v != 0:
            border_colors.add(v)

    # Choose the least frequent border colour.
    if border_colors:
        target = min(border_colors, key=lambda x: (counts[x], x))
    else:
        # Fallback for degenerate cases: least frequent non-zero colour.
        target = min(counts, key=lambda x: (counts[x], x))

    # Find the bounding box of the target colour.
    min_r, max_r = h, -1
    min_c, max_c = w, -1

    for r in range(h):
        for c in range(w):
            if int(grid[r][c]) == target:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if max_r == -1:
        return []

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    return [[target] * width for _ in range(height)]

from __future__ import annotations

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Normalise input to a list of lists of Python ints.
    grid = [list(map(int, row)) for row in grid]

    if not grid:
        return []

    h = len(grid)
    w = len(grid[0]) if h else 0

    if w == 0:
        return [row[:] for row in grid]

    # Collect all non-background colours.
    colors = sorted({v for row in grid for v in row if v != 0})

    if not colors:
        return [row[:] for row in grid]

    info = {}

    # For each colour, compute bounding box, count, and how many other
    # non-background cells lie inside its bounding box.
    for c in colors:
        min_r, min_c = h, w
        max_r, max_c = -1, -1
        count = 0

        for i in range(h):
            row = grid[i]
            for j in range(w):
                if row[j] == c:
                    count += 1
                    if i < min_r:
                        min_r = i
                    if i > max_r:
                        max_r = i
                    if j < min_c:
                        min_c = j
                    if j > max_c:
                        max_c = j

        area = (max_r - min_r + 1) * (max_c - min_c + 1)

        other_inside = 0
        for i in range(min_r, max_r + 1):
            row = grid[i]
            for j in range(min_c, max_c + 1):
                v = row[j]
                if v != 0 and v != c:
                    other_inside += 1

        info[c] = {
            "area": area,
            "count": count,
            "other_inside": other_inside,
            "min_r": min_r,
            "max_r": max_r,
            "min_c": min_c,
            "max_c": max_c,
        }

    # Colours whose bounding box is not completely filled by that colour.
    non_full = [c for c in colors if info[c]["area"] != info[c]["count"]]

    # If every colour already forms a solid rectangle, leave the grid unchanged.
    if not non_full:
        return [row[:] for row in grid]

    # In the intended puzzles there is exactly one such colour.
    if len(non_full) == 1:
        target = non_full[0]
    else:
        # Deterministic fallback: prefer a non-full colour that contains other
        # colours inside its bounding box, then larger missing area/count.
        with_other = [c for c in non_full if info[c]["other_inside"] > 0]

        if with_other:
            target = max(
                with_other,
                key=lambda c: (
                    info[c]["other_inside"],
                    info[c]["area"] - info[c]["count"],
                    info[c]["count"],
                    info[c]["area"],
                    c,
                ),
            )
        else:
            target = max(
                non_full,
                key=lambda c: (
                    info[c]["area"] - info[c]["count"],
                    info[c]["count"],
                    info[c]["area"],
                    c,
                ),
            )

    t = info[target]

    out = [[0] * w for _ in range(h)]

    for i in range(t["min_r"], t["max_r"] + 1):
        for j in range(t["min_c"], t["max_c"] + 1):
            out[i][j] = target

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque

    sys.setrecursionlimit(1000000)
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h, w = len(grid), len(grid[0])

    def neighbors4(x, y):
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < h and 0 <= ny < w:
                yield nx, ny

    def neighbors8(x, y):
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 0 <= nx < h and 0 <= ny < w:
                    yield nx, ny

    out = [row[:] for row in grid]

    # Free cells are zeros and the marker 6. Use 4-connectivity for free space
    # so that diagonally touching colored boundary pixels still act as barriers.
    free = [[grid[i][j] == 0 or grid[i][j] == 6 for j in range(w)] for i in range(h)]

    free_id = [[-1] * w for _ in range(h)]
    free_cells = []

    for i in range(h):
        for j in range(w):
            if free[i][j] and free_id[i][j] == -1:
                cid = len(free_cells)
                q = deque([(i, j)])
                free_id[i][j] = cid
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for nx, ny in neighbors4(x, y):
                        if free[nx][ny] and free_id[nx][ny] == -1:
                            free_id[nx][ny] = cid
                            q.append((nx, ny))
                free_cells.append(cells)

    # Components touching the border are outside all closed shapes.
    exterior_free_ids = set()
    for cid, cells in enumerate(free_cells):
        for x, y in cells:
            if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                exterior_free_ids.add(cid)
                break

    # Label connected components of colored boundary pixels.
    # Use 8-connectivity because shapes may be drawn with diagonal steps.
    colored = [[grid[i][j] != 0 and grid[i][j] != 6 for j in range(w)] for i in range(h)]
    col_id = [[-1] * w for _ in range(h)]
    col_cells = []

    for i in range(h):
        for j in range(w):
            if colored[i][j] and col_id[i][j] == -1:
                cid = len(col_cells)
                q = deque([(i, j)])
                col_id[i][j] = cid
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for nx, ny in neighbors8(x, y):
                        if colored[nx][ny] and col_id[nx][ny] == -1:
                            col_id[nx][ny] = cid
                            q.append((nx, ny))
                col_cells.append(cells)

    # If there is no marker, return the grid unchanged.
    sixes = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == 6]
    if not sixes:
        return out

    # For each colored component, mark which free cells are enclosed by it.
    # A component C encloses a cell if that cell is not reachable from the border
    # when only C is treated as blocked. Other colors are treated as passable
    # for this test, so nesting depth can be counted component by component.
    inside_by_cell = [[False] * w for _ in range(h)]

    for cells in col_cells:
        blocked = [[False] * w for _ in range(h)]
        for x, y in cells:
            blocked[x][y] = True

        seen = [[False] * w for _ in range(h)]
        q = deque()

        for i in range(h):
            for j in (0, w - 1):
                if not blocked[i][j] and not seen[i][j]:
                    seen[i][j] = True
                    q.append((i, j))
        for j in range(w):
            for i in (0, h - 1):
                if not blocked[i][j] and not seen[i][j]:
                    seen[i][j] = True
                    q.append((i, j))

        while q:
            x, y = q.popleft()
            for nx, ny in neighbors4(x, y):
                if not blocked[nx][ny] and not seen[nx][ny]:
                    seen[nx][ny] = True
                    q.append((nx, ny))

        for x, y in cells:
            pass  # blocked cells themselves are not relevant

        # Any free cell not seen is inside this colored component.
        for i in range(h):
            row_block = blocked[i]
            row_seen = seen[i]
            row_inside = inside_by_cell[i]
            for j in range(w):
                if free[i][j] and not row_block[j] and not row_seen[j]:
                    row_inside[j] = True

    # Nesting depth of each free component is the maximum number of colored
    # components enclosing any one of its cells.
    comp_depth = []
    for cells in free_cells:
        depth = 0
        for x, y in cells:
            if inside_by_cell[x][y]:
                # Count distinct colored components that enclose this cell.
                # Since inside_by_cell is a boolean OR, recompute distinct count
                # cheaply by checking neighboring colored components? Instead,
                # we store counts directly below.
                pass
        comp_depth.append(0)

    # Recompute depths as exact counts of enclosing colored components.
    # This is done by repeating the enclosure test and incrementing a count.
    enc_count = [[0] * w for _ in range(h)]
    for cells in col_cells:
        blocked = [[False] * w for _ in range(h)]
        for x, y in cells:
            blocked[x][y] = True

        seen = [[False] * w for _ in range(h)]
        q = deque()

        for i in range(h):
            for j in (0, w - 1):
                if not blocked[i][j] and not seen[i][j]:
                    seen[i][j] = True
                    q.append((i, j))
        for j in range(w):
            for i in (0, h - 1):
                if not blocked[i][j] and not seen[i][j]:
                    seen[i][j] = True
                    q.append((i, j))

        while q:
            x, y = q.popleft()
            for nx, ny in neighbors4(x, y):
                if not blocked[nx][ny] and not seen[nx][ny]:
                    seen[nx][ny] = True
                    q.append((nx, ny))

        for i in range(h):
            for j in range(w):
                if free[i][j] and not blocked[i][j] and not seen[i][j]:
                    enc_count[i][j] += 1

    comp_depth = []
    for cells in free_cells:
        depth = max(enc_count[x][y] for x, y in cells)
        comp_depth.append(depth)

    max_depth = max(comp_depth) if comp_depth else -1

    # Keep marker 6 only in free components of maximum nesting depth.
    for x, y in sixes:
        cid = free_id[x][y]
        if cid != -1 and comp_depth[cid] == max_depth:
            out[x][y] = 6
        else:
            out[x][y] = 0

    return out

import sys
from collections import deque

