def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    out = [row[:] for row in grid]

    def is_empty(x: int) -> bool:
        return x == 0 or x == 6

    def is_wall(x: int) -> bool:
        return x != 0 and x != 6

    # 4-connected empty regions (0 and 6)
    empty_id = [[-1] * w for _ in range(h)]
    empty_cells = []

    for i in range(h):
        for j in range(w):
            if is_empty(grid[i][j]) and empty_id[i][j] == -1:
                cid = len(empty_cells)
                q = deque([(i, j)])
                empty_id[i][j] = cid
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if 0 <= nx < h and 0 <= ny < w:
                            if is_empty(grid[nx][ny]) and empty_id[nx][ny] == -1:
                                empty_id[nx][ny] = cid
                                q.append((nx, ny))
                empty_cells.append(cells)

    # 8-connected wall regions of the same colour.
    # 8-connectivity is needed because some outlines are diagonal.
    wall_id = [[-1] * w for _ in range(h)]
    wall_cells = []

    for i in range(h):
        for j in range(w):
            if is_wall(grid[i][j]) and wall_id[i][j] == -1:
                cid = len(wall_cells)
                color = grid[i][j]
                q = deque([(i, j)])
                wall_id[i][j] = cid
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w:
                                if (
                                    is_wall(grid[nx][ny])
                                    and grid[nx][ny] == color
                                    and wall_id[nx][ny] == -1
                                ):
                                    wall_id[nx][ny] = cid
                                    q.append((nx, ny))
                wall_cells.append(cells)

    e_count = len(empty_cells)
    w_count = len(wall_cells)

    # Build graph: empty component <-> wall component.
    adj_e = [set() for _ in range(e_count)]
    adj_w = [set() for _ in range(w_count)]

    for x in range(h):
        for y in range(w):
            if not is_wall(grid[x][y]):
                continue
            wid = wall_id[x][y]
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < h and 0 <= ny < w:
                    eid = empty_id[nx][ny]
                    if eid != -1:
                        adj_e[eid].add(wid)
                        adj_w[wid].add(eid)

    # BFS nesting depth.
    # Virtual outside node has depth 0 and is adjacent to wall components touching border.
    INF = 10**9
    wall_depth = [INF] * w_count

    q = deque()

    # Actual empty regions touching the border are depth 0.
    for eid, cells in enumerate(empty_cells):
        touches_border = False
        for x, y in cells:
            if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                touches_border = True
                break
        if touches_border:
            q.append((eid, 0))

    # If the border is completely wall, connect the virtual outside to border walls.
    for wid, cells in enumerate(wall_cells):
        touches_border = False
        for x, y in cells:
            if x == 0 or y == 0 or x == h - 1 or y == w - 1:
                touches_border = True
                break
        if touches_border:
            wall_depth[wid] = 0

    # Empty-region depths.  Use a small dictionary-like list, -1 means unvisited.
    depth = [-1] * e_count

    # First propagate from border empty regions and border wall regions.
    for wid, d in enumerate(wall_depth):
        if d == 0:
            for eid in adj_w[wid]:
                if depth[eid] == -1:
                    depth[eid] = 1
                    q.append((eid, 1))

    while q:
        eid, d = q.popleft()
        if d != depth[eid]:
            continue

        for wid in adj_e[eid]:
            nd = d + 1
            if nd < wall_depth[wid]:
                wall_depth[wid] = nd
                for eid2 in adj_w[wid]:
                    if depth[eid2] == -1 or depth[eid2] > nd:
                        depth[eid2] = nd
                        q.append((eid2, nd))

    # Any empty region not reached should be treated as outside (depth 0).
    for i in range(e_count):
        if depth[i] == -1:
            depth[i] = 0

    if not depth:
        return out

    max_depth = max(depth)

    # Keep 6 only if it lies in a deepest empty region.
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 6:
                eid = empty_id[i][j]
                if eid == -1 or depth[eid] != max_depth:
                    out[i][j] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Work with plain Python lists of ints
    orig = [list(row) for row in grid]
    h = len(orig)
    if h == 0:
        return []
    w = len(orig[0])

    out = [row[:] for row in orig]

    # Collect all colored dots: any non-zero color that is not 5
    seeds = []
    for r in range(h):
        for c in range(w):
            v = orig[r][c]
            if v != 0 and v != 5:
                seeds.append((r, c, v))

    # Try horizontal directions first, then vertical.
    dirs = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    for r, c, color in seeds:
        best = None  # (distance, dr, dc, target_r, target_c)

        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            dist = 1

            # Scan until hitting a 5, a different obstacle, or the border.
            # Cells of the same color are treated as part of the dot/object.
            while 0 <= rr < h and 0 <= cc < w:
                v = orig[rr][cc]
                if v == 5:
                    break
                if v != 0 and v != color:
                    break
                rr += dr
                cc += dc
                dist += 1

            # If we stopped on a 5, this is a possible target.
            if 0 <= rr < h and 0 <= cc < w and orig[rr][cc] == 5:
                if best is None or dist < best[0]:
                    best = (dist, dr, dc, rr, cc)

        if best is not None:
            _, dr, dc, tr, tc = best
            rr, cc = r + dr, c + dc

            # Fill the cells between the dot and the 5, excluding the 5.
            while (rr, cc) != (tr, tc):
                if out[rr][cc] == 0:
                    out[rr][cc] = color
                rr += dr
                cc += dc

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h, w = len(grid), len(grid[0])

    # Find the topmost row, then the rightmost non-zero cell in that row.
    sr = sc = None
    for r in range(h):
        for c in range(w - 1, -1, -1):
            if grid[r][c] != 0:
                sr, sc = r, c
                break
        if sr is not None:
            break

    out = [row[:] for row in grid]

    if sr is None:
        return out

    target = grid[sr][sc]
    seen = [[False] * w for _ in range(h)]
    stack = [(sr, sc)]
    seen[sr][sc] = True

    # 8-connected component of the same colour.
    while stack:
        r, c = stack.pop()
        out[r][c] = 5

        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < h
                    and 0 <= nc < w
                    and not seen[nr][nc]
                    and grid[nr][nc] == target
                ):
                    seen[nr][nc] = True
                    stack.append((nr, nc))

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])

    # Work from the original grid for collision checking.
    base = [[int(grid[r][c]) for c in range(w)] for r in range(h)]
    out = [row[:] for row in base]

    for r in range(h):
        for c in range(w):
            if base[r][c] == 1:
                nr, nc = r - 1, c + 1
                while 0 <= nr < h and 0 <= nc < w:
                    if base[nr][nc] != 0:
                        break
                    out[nr][nc] = 1
                    nr -= 1
                    nc += 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    if not grid:
        return [[0]]

    # Find the main non-background colour.
    colour_counts = Counter()
    for row in grid:
        for value in row:
            if value != 0:
                colour_counts[value] += 1

    if not colour_counts:
        return [[0]]

    colour = colour_counts.most_common(1)[0][0]

    # For every non-empty horizontal segment of that colour, record its length.
    segment_lengths = []
    for row in grid:
        current = 0
        best = 0
        for value in row:
            if value == colour:
                current += 1
                if current > best:
                    best = current
            else:
                current = 0
        if best > 0:
            segment_lengths.append(best)

    if not segment_lengths:
        return [[0]]

    # Output the middle horizontal segment, as a 1-row grid.
    length = segment_lengths[len(segment_lengths) // 2]
    return [[colour] * length]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if grid is None:
        return []

    h = len(grid)
    if h == 0:
        return []

    # Normalize input in case rows are strings or numpy rows.
    norm = []
    for row in grid:
        if isinstance(row, (str, bytes)):
            norm.append([int(ch) for ch in row])
        else:
            norm.append([int(v) for v in row])

    w = len(norm[0]) if norm else 0
    out = [row[:] for row in norm]

    for r in range(h):
        for c in range(w):
            if norm[r][c] != 1:
                continue

            nr, nc = r - 1, c + 1
            while 0 <= nr < h and 0 <= nc < w:
                v = out[nr][nc]
                if v not in (0, 1):
                    break
                if v == 0:
                    out[nr][nc] = 1
                nr -= 1
                nc += 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return []

    arr = [[int(grid[r][c]) for c in range(W)] for r in range(H)]

    # Background is the most frequent colour (tie broken by smaller value).
    counts = {}
    for r in range(H):
        for c in range(W):
            v = arr[r][c]
            counts[v] = counts.get(v, 0) + 1

    max_count = max(counts.values())
    bg = min(v for v, n in counts.items() if n == max_count)

    out = [[bg] * W for _ in range(H)]
    visited = [[False] * W for _ in range(H)]
    components = []

    # 4-connected components of non-background colours.
    for r0 in range(H):
        for c0 in range(W):
            if visited[r0][c0]:
                continue

            color = arr[r0][c0]
            if color == bg:
                continue

            stack = [(r0, c0)]
            visited[r0][c0] = True
            rmin = rmax = r0
            cmin = cmax = c0

            while stack:
                r, c = stack.pop()

                if r < rmin:
                    rmin = r
                if r > rmax:
                    rmax = r
                if c < cmin:
                    cmin = c
                if c > cmax:
                    cmax = c

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not visited[nr][nc] and arr[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

            # Keep only components that span at least two rows and two columns.
            if rmax > rmin and cmax > cmin:
                area = (rmax - rmin + 1) * (cmax - cmin + 1)
                components.append((area, rmin, rmax, cmin, cmax, color))

    # Fill bounding boxes.  Smaller first, so a larger enclosing component
    # can override overlapping smaller ones if that situation occurs.
    components.sort(key=lambda x: x[0])
    for _, rmin, rmax, cmin, cmax, color in components:
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                out[r][c] = color

    return out

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])

    visited = [[False] * w for _ in range(h)]
    components = []
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                color = int(grid[r][c])
                stack = [(r, c)]
                visited[r][c] = True
                cells = []

                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))

                    for dy, dx in directions:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not visited[ny][nx] and int(grid[ny][nx]) == color:
                                visited[ny][nx] = True
                                stack.append((ny, nx))

                min_r = min(y for y, _ in cells)
                min_c = min(x for _, x in cells)
                shape = tuple(sorted((y - min_r, x - min_c) for y, x in cells))

                components.append((color, cells, shape))

    shape_counts = Counter(shape for _, _, shape in components)

    result = [[0] * w for _ in range(h)]

    for color, cells, shape in components:
        if shape_counts[shape] >= 2:
            for y, x in cells:
                result[y][x] = color

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    g = [list(map(int, row)) for row in grid]
    H = len(g)
    W = len(g[0]) if H else 0
    out = [row[:] for row in g]

    if H == 0 or W == 0:
        return out

    # Choose the object color. The examples use 5; if absent, fall back
    # to the most common non-background color.
    counts = {}
    has_five = False
    for r in range(H):
        for c in range(W):
            v = g[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
                if v == 5:
                    has_five = True

    if has_five:
        target = 5
    elif not counts:
        return out
    else:
        target = max(counts, key=lambda k: counts[k])

    pts = [(r, c) for r in range(H) for c in range(W) if g[r][c] == target]
    if not pts:
        return out

    pts_set = set(pts)

    def place(cr, cc):
        if 0 <= cr < H and 0 <= cc < W:
            out[cr][cc] = 1
        return out

    n = len(pts)
    sr = sum(r for r, c in pts)
    sc = sum(c for r, c in pts)

    # Main rule: the colored pixels are centrally symmetric.
    # Place 1 at the integer center of 180-degree symmetry.
    if sr % n == 0 and sc % n == 0:
        cr, cc = sr // n, sc // n
        ok = True
        for r, c in pts:
            mr, mc = 2 * cr - r, 2 * cc - c
            if not (0 <= mr < H and 0 <= mc < W) or (mr, mc) not in pts_set:
                ok = False
                break
        if ok:
            return place(cr, cc)

    # Fallbacks for safety: midpoint of missing cells of 2x2 corners,
    # then bounding-box center, then rounded centroid.
    holes = []
    for r in range(H - 1):
        for c in range(W - 1):
            cnt = 0
            missing = None
            for rr, cc in ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)):
                if g[rr][cc] == target:
                    cnt += 1
                else:
                    missing = (rr, cc)
            if cnt == 3:
                holes.append(missing)

    if holes:
        uniq = []
        for h in holes:
            if h not in uniq:
                uniq.append(h)

        if len(uniq) == 1:
            return place(*uniq[0])
        if len(uniq) >= 2:
            m = len(uniq)
            hr = sum(h[0] for h in uniq)
            hc = sum(h[1] for h in uniq)
            if hr % m == 0 and hc % m == 0:
                return place(hr // m, hc // m)
            return place((2 * hr + m) // (2 * m), (2 * hc + m) // (2 * m))

    min_r = min(r for r, c in pts)
    max_r = max(r for r, c in pts)
    min_c = min(c for r, c in pts)
    max_c = max(c for r, c in pts)

    if (max_r - min_r) % 2 == 0 and (max_c - min_c) % 2 == 0:
        return place((min_r + max_r) // 2, (min_c + max_c) // 2)

    cr = (2 * sr + n) // (2 * n)
    cc = (2 * sc + n) // (2 * n)
    return place(cr, cc)

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []

    out = [[int(v) for v in row] for row in grid]
    W = len(out[0]) if H else 0
    if W == 0:
        return out

    # The examples use colour 5. If a variant uses another object colour,
    # fall back to all non-background pixels except the marker colour 1.
    cells5 = []
    all_cells = []
    for r in range(H):
        for c in range(W):
            v = out[r][c]
            if v == 5:
                cells5.append((r, c))
            if v not in (0, 1):
                all_cells.append((r, c))

    if not all_cells:
        return out

    def possible_centers(pts):
        min_r = min(r for r, _ in pts)
        max_r = max(r for r, _ in pts)
        min_c = min(c for _, c in pts)
        max_c = max(c for _, c in pts)

        rows = [ (min_r + max_r) // 2 ]
        if (min_r + max_r) % 2 == 1:
            rows.append(rows[0] + 1)

        cols = [ (min_c + max_c) // 2 ]
        if (min_c + max_c) % 2 == 1:
            cols.append(cols[0] + 1)

        candidates = [(r, c) for r in rows for c in cols]

        # Also include centroid-based candidates as a safety net.
        n = len(pts)
        sr = sum(r for r, _ in pts)
        sc = sum(c for _, c in pts)
        for r in (sr // n, (sr + n - 1) // n):
            for c in (sc // n, (sc + n - 1) // n):
                candidates.append((r, c))

        seen = set()
        unique = []
        for p in candidates:
            if p not in seen:
                seen.add(p)
                unique.append(p)
        return unique

    def symmetric_center(pts):
        """Return an integer cell that is the 180-degree symmetry centre."""
        if not pts:
            return None
        pts_set = set(pts)
        for r, c in possible_centers(pts):
            if 0 <= r < H and 0 <= c < W:
                ok = True
                for rr, cc in pts_set:
                    if (2 * r - rr, 2 * c - cc) not in pts_set:
                        ok = False
                        break
                if ok:
                    return r, c
        return None

    def bbox_center(pts):
        min_r = min(r for r, _ in pts)
        max_r = max(r for r, _ in pts)
        min_c = min(c for _, c in pts)
        max_c = max(c for _, c in pts)

        r = (min_r + max_r) // 2
        c = (min_c + max_c) // 2

        # If the bounding box has an even extent, choose between the two
        # central cells by closeness to the centroid.
        n = len(pts)
        sr = sum(r for r, _ in pts)
        sc = sum(c for _, c in pts)

        if (min_r + max_r) % 2 == 1:
            if 2 * sr > n * (2 * r + 1):
                r += 1
        if (min_c + max_c) % 2 == 1:
            if 2 * sc > n * (2 * c + 1):
                c += 1

        return r, c

    # Prefer the centre of the 5 pattern if it is 180-degree symmetric.
    center = symmetric_center(cells5) if cells5 else None

    # Otherwise, try the whole non-background pattern.
    if center is None:
        center = symmetric_center(all_cells)

    # If no exact symmetry is detected, use the bounding-box centre.
    if center is None:
        pts = cells5 if cells5 else all_cells
        center = bbox_center(pts)

    out[center[0]][center[1]] = 1
    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Make a mutable copy and ensure plain ints.
    grid = [list(row) for row in grid]
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    if w == 0:
        return []

    # Collect non-zero cells by colour.
    cells = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                cells.setdefault(v, []).append((r, c))

    if not cells:
        return grid

    # For each colour, compute bounding-box area and how many of its cells
    # touch the 0 background.  The outer frame colour is the one with the
    # largest bounding box (ties broken by background contact / cell count).
    info = {}
    dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))

    for color, pts in cells.items():
        min_r = min(r for r, _ in pts)
        max_r = max(r for r, _ in pts)
        min_c = min(c for _, c in pts)
        max_c = max(c for _, c in pts)
        area = (max_r - min_r + 1) * (max_c - min_c + 1)

        bg_touch = 0
        for r, c in pts:
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                    bg_touch += 1
                    break

        info[color] = (area, bg_touch, len(pts))

    outer_color = max(info, key=lambda col: info[col])

    # Remove every occurrence of the outer colour.
    modified = [
        [0 if grid[r][c] == outer_color else grid[r][c] for c in range(w)]
        for r in range(h)
    ]

    # Crop to the bounding box of the remaining non-zero cells.
    min_r, max_r = h, -1
    min_c, max_c = w, -1
    for r in range(h):
        for c in range(w):
            if modified[r][c] != 0:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    if max_r == -1:
        return [[0]]

    return [
        modified[r][min_c:max_c + 1]
        for r in range(min_r, max_r + 1)
    ]

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return []

    colors = set()
    bboxes = {}
    counts = {}

    for r in range(H):
        for c in range(W):
            v = int(grid[r][c])
            if v == 0:
                continue
            colors.add(v)
            counts[v] = counts.get(v, 0) + 1
            if v not in bboxes:
                bboxes[v] = [r, r, c, c]
            else:
                bb = bboxes[v]
                if r < bb[0]:
                    bb[0] = r
                if r > bb[1]:
                    bb[1] = r
                if c < bb[2]:
                    bb[2] = c
                if c > bb[3]:
                    bb[3] = c

    if not colors:
        return [[int(grid[r][c]) for c in range(W)] for r in range(H)]

    def area(v: int) -> int:
        r0, r1, c0, c1 = bboxes[v]
        return (r1 - r0 + 1) * (c1 - c0 + 1)

    # If there is only one non-background color, just crop to its bounding box.
    if len(colors) == 1:
        v = next(iter(colors))
        r0, r1, c0, c1 = bboxes[v]
        out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if int(grid[r][c]) == v:
                    out[r - r0][c - c0] = v
        return out

    # The frame/background color is usually the one whose bounding box contains
    # all other colors.  If ambiguous, fall back to geometry/count scores.
    def contains(a, b):
        return a[0] <= b[0] and a[1] >= b[1] and a[2] <= b[2] and a[3] >= b[3]

    frame_candidates = []
    for v in sorted(colors):
        if all(contains(bboxes[v], bboxes[u]) for u in colors if u != v):
            frame_candidates.append(v)

    if len(frame_candidates) == 1:
        frame = frame_candidates[0]
    else:
        r0 = min(bboxes[v][0] for v in colors)
        r1 = max(bboxes[v][1] for v in colors)
        c0 = min(bboxes[v][2] for v in colors)
        c1 = max(bboxes[v][3] for v in colors)

        side_counts = {v: 0 for v in colors}

        for v in {int(grid[r0][c]) for c in range(c0, c1 + 1)}:
            if v != 0:
                side_counts[v] += 1
        if r1 != r0:
            for v in {int(grid[r1][c]) for c in range(c0, c1 + 1)}:
                if v != 0:
                    side_counts[v] += 1
        for v in {int(grid[r][c0]) for r in range(r0, r1 + 1)}:
            if v != 0:
                side_counts[v] += 1
        if c1 != c0:
            for v in {int(grid[r][c1]) for r in range(r0, r1 + 1)}:
                if v != 0:
                    side_counts[v] += 1

        boundary = set()
        for c in range(c0, c1 + 1):
            boundary.add((r0, c))
            boundary.add((r1, c))
        for r in range(r0, r1 + 1):
            boundary.add((r, c0))
            boundary.add((r, c1))

        perim_counts = {v: 0 for v in colors}
        for r, c in boundary:
            v = int(grid[r][c])
            if v in perim_counts:
                perim_counts[v] += 1

        frame = max(
            sorted(colors),
            key=lambda v: (area(v), side_counts[v], perim_counts[v], counts[v])
        )

    # Keep everything except the frame color, and crop to their bounding box.
    content = colors - {frame}
    if not content:
        content = {frame}

    r0 = min(bboxes[v][0] for v in content)
    r1 = max(bboxes[v][1] for v in content)
    c0 = min(bboxes[v][2] for v in content)
    c1 = max(bboxes[v][3] for v in content)

    out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            v = int(grid[r][c])
            if v in content:
                out[r - r0][c - c0] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Normalize input to a fresh list of lists of ints.
    g = []
    for row in grid:
        if isinstance(row, str):
            g.append([int(ch) for ch in row])
        else:
            g.append([int(v) for v in row])

    if not g:
        return []

    counts = {}
    boxes = {}

    # Count non-zero colors and compute each color's bounding box.
    for r, row in enumerate(g):
        for c, v in enumerate(row):
            if v == 0:
                continue
            counts[v] = counts.get(v, 0) + 1
            if v not in boxes:
                boxes[v] = [r, r, c, c]
            else:
                b = boxes[v]
                if r < b[0]:
                    b[0] = r
                if r > b[1]:
                    b[1] = r
                if c < b[2]:
                    b[2] = c
                if c > b[3]:
                    b[3] = c

    if not boxes:
        return [row[:] for row in g]

    def bbox_area(b):
        return (b[1] - b[0] + 1) * (b[3] - b[2] + 1)

    # The inner pattern is the non-background color with the smallest
    # bounding box.  Ties are broken by smaller pixel count, then color.
    target = min(boxes, key=lambda color: (bbox_area(boxes[color]), counts[color], color))

    r0, r1, c0, c1 = boxes[target]

    # Crop to the target color's bounding box and blank everything else.
    result = []
    for r in range(r0, r1 + 1):
        result.append(
            [g[r][c] if g[r][c] == target else 0 for c in range(c0, c1 + 1)]
        )

    return result

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    h, w = a.shape
    mask = a > 0
    if not mask.any():
        return [[0] * w for _ in range(h)]

    keep = np.zeros((h, w), dtype=bool)
    counts = {}
    color = {}

    # Diagonal direction: down-right (row+1, col+1), key = col - row
    for d in range(-h + 1, w):
        cells = []
        for r in range(max(0, d), min(h, w - d)):
            c = r + d
            if mask[r, c]:
                cells.append((r, c))
        if not cells:
            continue
        # split into consecutive runs
        start = 0
        for i in range(1, len(cells)):
            if cells[i][0] - cells[i - 1][0] != 1:
                run = cells[start:i]
                if len(run) >= 3:
                    for r, c in run:
                        keep[r, c] = True
                        color[a[r, c]] = color.get(a[r, c], 0) + 1
                    key = ('dr', d)
                    counts[key] = counts.get(key, 0) + len(run)
                start = i
        run = cells[start:]
        if len(run) >= 3:
            for r, c in run:
                keep[r, c] = True
                color[a[r, c]] = color.get(a[r, c], 0) + 1
            key = ('dr', d)
            counts[key] = counts.get(key, 0) + len(run)

    # Diagonal direction: down-left (row+1, col-1), key = row + col
    for s in range(0, h + w - 1):
        cells = []
        for r in range(max(0, s - w + 1), min(h, s + 1)):
            c = s - r
            if 0 <= c < w and mask[r, c]:
                cells.append((r, c))
        if not cells:
            continue
        start = 0
        for i in range(1, len(cells)):
            if cells[i][0] - cells[i - 1][0] != 1:
                run = cells[start:i]
                if len(run) >= 3:
                    for r, c in run:
                        keep[r, c] = True
                        color[a[r, c]] = color.get(a[r, c], 0) + 1
                    key = ('dl', s)
                    counts[key] = counts.get(key, 0) + len(run)
                start = i
        run = cells[start:]
        if len(run) >= 3:
            for r, c in run:
                keep[r, c] = True
                color[a[r, c]] = color.get(a[r, c], 0) + 1
            key = ('dl', s)
            counts[key] = counts.get(key, 0) + len(run)

    if not keep.any():
        return [[0] * w for _ in range(h)]

    out = np.zeros_like(a)

    # Choose the output colour: prefer the most common colour among kept cells.
    # Ties are broken by the larger total line mass for lines containing that colour.
    def score(col):
        line_mass = 0
        for (kind, key), mass in counts.items():
            # Reconstruct line colour mass approximately by checking kept cells.
            if kind == 'dr':
                d = key
                for r in range(max(0, d), min(h, w - d)):
                    c = r + d
                    if keep[r, c] and a[r, c] == col:
                        line_mass += 1
                        break
            else:
                s = key
                for r in range(max(0, s - w + 1), min(h, s + 1)):
                    c = s - r
                    if 0 <= c < w and keep[r, c] and a[r, c] == col:
                        line_mass += 1
                        break
        return (color.get(col, 0), line_mass, -col)

    best = max((col for col in set(a[keep].tolist())), key=score)

    out[keep] = best
    return out.tolist()

import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    h, w = a.shape
    out = np.zeros((h, w), dtype=int)

    # Check both 45-degree diagonal families.
    # A diagonal is "valid" if it contains at least 4 cells of the same color.
    # The whole diagonal is then painted with the most common color on it.
    #
    # 1) constant r + c
    for s in range(h + w - 1):
        color_counter = Counter()
        cells = []
        for r in range(max(0, s - w + 1), min(h, s + 1)):
            c = s - r
            v = a[r, c]
            if v != 0:
                color_counter[v] += 1
            cells.append((r, c))
        if not cells:
            continue
        best_color, best_count = color_counter.most_common(1)[0] if color_counter else (0, 0)
        if best_count >= 4:
            for r, c in cells:
                out[r, c] = best_color

    # 2) constant c - r
    for d in range(-h + 1, w):
        color_counter = Counter()
        cells = []
        for r in range(max(0, d), min(h, w - d)):
            c = r + d
            v = a[r, c]
            if v != 0:
                color_counter[v] += 1
            cells.append((r, c))
        if not cells:
            continue
        best_color, best_count = color_counter.most_common(1)[0] if color_counter else (0, 0)
        if best_count >= 4:
            for r, c in cells:
                out[r, c] = best_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    # For each non-background colour independently:
    # 1) find its bounding box;
    # 2) within that box, fill every cell whose row or column contains
    #    that colour in the original grid.
    for color in range(1, 10):
        rows = set()
        cols = set()
        found = False

        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    rows.add(r)
                    cols.add(c)
                    found = True

        if not found:
            continue

        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        for r in range(min_r, max_r + 1):
            row_has = r in rows
            for c in range(min_c, max_c + 1):
                if row_has or c in cols:
                    out[r][c] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [list(map(int, row)) for row in grid]
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    out = [row[:] for row in grid]

    # Full non-background rows and columns are treated as walls.
    row_color = {}
    for r in range(H):
        row = grid[r]
        if not row:
            continue
        v = row[0]
        if v != 0 and all(x == v for x in row):
            row_color[r] = v

    col_color = {}
    if W > 0:
        for c in range(W):
            v = grid[0][c]
            if v != 0 and all(grid[r][c] == v for r in range(H)):
                col_color[c] = v

    # Cells that are not part of a full wall line are candidates for the moving object.
    candidates = []
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v == 0:
                continue
            if r in row_color and row_color[r] == v:
                continue
            if c in col_color and col_color[c] == v:
                continue
            candidates.append((r, c, v))

    if not candidates:
        return out

    def choose_center(lines: dict[int, int], pos: int, value: int | None = None) -> int | None:
        indices = sorted(lines)
        best = None

        # Prefer a pair of parallel walls with the same colour.
        for i in range(len(indices)):
            for j in range(i + 1, len(indices)):
                a, b = indices[i], indices[j]
                if a < pos < b and lines[a] == lines[b]:
                    pref = 0 if value is not None and lines[a] == value else 1
                    key = (pref, b - a, a, b)
                    if best is None or key < best[0]:
                        best = (key, a, b)

        # Fallback: allow differently coloured walls if necessary.
        if best is None:
            for i in range(len(indices)):
                for j in range(i + 1, len(indices)):
                    a, b = indices[i], indices[j]
                    if a < pos < b:
                        pref = 0 if value is not None and (lines[a] == value or lines[b] == value) else 2
                        key = (pref, b - a, a, b)
                        if best is None or key < best[0]:
                            best = (key, a, b)

        if best is None:
            return None

        a, b = best[1], best[2]
        s = a + b
        if s % 2 == 0:
            return s // 2

        # If there are two middle cells, choose the one closer to the object.
        c1, c2 = s // 2, s // 2 + 1
        return c1 if abs(c1 - pos) <= abs(c2 - pos) else c2

    moves = []
    for r, c, v in candidates:
        nr, nc = r, c

        if row_color:
            center_row = choose_center(row_color, r, v)
            if center_row is not None:
                nr = center_row

        if col_color:
            center_col = choose_center(col_color, c, v)
            if center_col is not None:
                nc = center_col

        moves.append((r, c, nr, nc, v))

    # Remove original candidate cells, then place them at their centered positions.
    for r, c, _ in candidates:
        out[r][c] = 0
    for _, _, nr, nc, v in moves:
        out[nr][nc] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)

    # Count all non-background colours.
    total_counts = {}
    for row in grid:
        for v in row:
            v = int(v)
            if v != 0:
                total_counts[v] = total_counts.get(v, 0) + 1

    # No non-background colour exists.
    if not total_counts:
        return [[0]]

    # Use the middle row of the grid.
    mid_row = grid[h // 2]

    # Prefer the colour that actually appears in the middle row.
    mid_counts = {}
    for v in mid_row:
        v = int(v)
        if v != 0:
            mid_counts[v] = mid_counts.get(v, 0) + 1

    if mid_counts:
        color = max(
            mid_counts.items(),
            key=lambda item: (item[1], total_counts.get(item[0], 0))
        )[0]
    else:
        color = max(
            total_counts.items(),
            key=lambda item: (item[1], item[0])
        )[0]

    def count_in_row(row):
        return sum(1 for v in row if int(v) == color)

    n = count_in_row(mid_row)

    # Fallback: if the exact middle row is empty, use the middle row
    # among the rows that contain the colour.
    if n == 0:
        rows_with = [i for i, row in enumerate(grid) if count_in_row(row) > 0]
        if rows_with:
            n = count_in_row(grid[rows_with[len(rows_with) // 2]])

    if n == 0:
        n = 1

    return [[int(color)] * n]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    H = len(grid)
    W = max((len(row) for row in grid), default=0)
    out = [[0] * W for _ in range(H)]
    cells = []

    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            v = int(v)
            out[r][c] = v
            if v != 0:
                cells.append((r, c, v))

    if not cells:
        return out

    def param(ori, r, c):
        if ori == 0:
            return r
        if ori == 1:
            return c
        if ori == 2:
            return r - c
        return r + c

    by_color = {}
    for r, c, v in cells:
        by_color.setdefault(v, []).append((r, c))

    candidates = []
    for color, pts in by_color.items():
        for ori in range(4):
            groups = {}
            for r, c in pts:
                groups.setdefault(param(ori, r, c), []).append((r, c))
            for const, line_pts in groups.items():
                if len(line_pts) >= 2:
                    candidates.append((color, ori, const, line_pts))

    if not candidates:
        return out

    def regular_spacing(ori, line_pts):
        if len(line_pts) <= 2:
            return 1
        if ori == 0:
            vals = sorted(c for _, c in line_pts)
        else:
            vals = sorted(r for r, _ in line_pts)
        gaps = [vals[i + 1] - vals[i] for i in range(len(vals) - 1)]
        return 1 if all(g == gaps[0] for g in gaps) else 0

    def bounds(line_pts):
        rs = [r for r, _ in line_pts]
        cs = [c for _, c in line_pts]
        return min(rs), max(rs), min(cs), max(cs)

    def intersection_inside(ori, const, line_pts, r, c, tol=1.0):
        rmin, rmax, cmin, cmax = bounds(line_pts)

        if ori == 0:
            col = c
            return cmin - tol <= col <= cmax + tol

        if ori == 1:
            row = r
            return rmin - tol <= row <= rmax + tol

        if ori == 2:
            f = (r - c) - const
            t = abs(f) / 2.0
            s = 1 if f > 0 else -1
            row = r - s * t
            col = c + s * t
        else:
            f = (r + c) - const
            t = abs(f) / 2.0
            s = 1 if f > 0 else -1
            row = r - s * t
            col = c - s * t

        return rmin - tol <= row <= rmax + tol and cmin - tol <= col <= cmax + tol

    def paint_steps(ori, const, r, c):
        if param(ori, r, c) == const:
            return 0
        if ori == 0:
            return max(0, abs(r - const) - 1)
        if ori == 1:
            return max(0, abs(c - const) - 1)
        d = abs(param(ori, r, c) - const)
        return max(0, (d - 1) // 2)

    def score(cand):
        color, ori, const, line_pts = cand
        off = []
        inside = 0
        total_paint = 0

        for r, c, col in cells:
            if param(ori, r, c) == const:
                continue
            off.append((r, c, col))
            total_paint += paint_steps(ori, const, r, c)
            if intersection_inside(ori, const, line_pts, r, c):
                inside += 1

        return (
            1 if off else 0,
            1 if inside else 0,
            len(line_pts),
            regular_spacing(ori, line_pts),
            inside,
            len(by_color[color]),
            -total_paint,
        )

    best = max(candidates, key=score)
    color, ori, const, _ = best

    for r, c, col in cells:
        if param(ori, r, c) == const:
            continue

        f = param(ori, r, c) - const
        if f == 0:
            continue

        if ori == 0:
            dr, dc = (1, 0) if f < 0 else (-1, 0)
            step = 1 if f < 0 else -1
        elif ori == 1:
            dr, dc = (0, 1) if f < 0 else (0, -1)
            step = 1 if f < 0 else -1
        elif ori == 2:
            dr, dc = (1, -1) if f < 0 else (-1, 1)
            step = 2 if f < 0 else -2
        else:
            dr, dc = (1, 1) if f < 0 else (-1, -1)
            step = 2 if f < 0 else -2

        cur = f
        while True:
            nxt = cur + step
            if nxt * f <= 0:
                break
            nr, nc = r + dr, c + dc
            if not (0 <= nr < H and 0 <= nc < W):
                break
            out[nr][nc] = col
            r, c = nr, nc
            cur = nxt

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [[0] * 6]

    h = len(grid)
    w = len(grid[0])
    visited = [[False] * w for _ in range(h)]
    components = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                components += 1
                color = grid[r][c]
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    y, x = stack.pop()
                    for dy in (-1, 0, 1):
                        ny = y + dy
                        if ny < 0 or ny >= h:
                            continue
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            nx = x + dx
                            if nx < 0 or nx >= w:
                                continue
                            if not visited[ny][nx] and grid[ny][nx] == color:
                                visited[ny][nx] = True
                                stack.append((ny, nx))

    return [[4 if i < min(components, 6) else 0 for i in range(6)]]

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if len(grid) == 0:
        return []
    h = len(grid)
    w = len(grid[0])
    if w == 0:
        return []

    seen = [[False] * w for _ in range(h)]
    q = deque()

    def add(r, c):
        if 0 <= r < h and 0 <= c < w and not seen[r][c] and grid[r][c] == 0:
            seen[r][c] = True
            q.append((r, c))

    # Flood fill background connected to the outside border.
    for c in range(w):
        add(0, c)
        add(h - 1, c)
    for r in range(h):
        add(r, 0)
        add(r, w - 1)

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == 0:
                seen[nr][nc] = True
                q.append((nr, nc))

    enclosed = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not seen[r][c]:
                enclosed += 1

    return [[0] * enclosed]

from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    color_pts = defaultdict(list)
    for r in range(H):
        for c in range(W):
            v = int(grid[r][c])
            if v != 0:
                color_pts[v].append((r, c))

    if not color_pts:
        return [[0] * W for _ in range(H)]

    def bbox(pts):
        rmin = min(r for r, _ in pts)
        rmax = max(r for r, _ in pts)
        cmin = min(c for _, c in pts)
        cmax = max(c for _, c in pts)
        return rmin, rmax, cmin, cmax

    def bbox_area(pts):
        rmin, rmax, cmin, cmax = bbox(pts)
        return (rmax - rmin + 1) * (cmax - cmin + 1)

    def fill_8_way(pts, color):
        out = [[0] * W for _ in range(H)]

        rows = defaultdict(list)
        cols = defaultdict(list)
        diags = defaultdict(list)    # r - c
        anti_diags = defaultdict(list)  # r + c

        for r, c in pts:
            if 0 <= r < H and 0 <= c < W:
                out[r][c] = color
                rows[r].append(c)
                cols[c].append(r)
                diags[r - c].append(r)
                anti_diags[r + c].append(r)

        # Fill horizontal gaps
        for r, cs in rows.items():
            for c in range(min(cs), max(cs) + 1):
                out[r][c] = color

        # Fill vertical gaps
        for c, rs in cols.items():
            for r in range(min(rs), max(rs) + 1):
                out[r][c] = color

        # Fill diagonal gaps (top-left to bottom-right)
        for k, rs in diags.items():
            for r in range(min(rs), max(rs) + 1):
                c = r - k
                if 0 <= c < W:
                    out[r][c] = color

        # Fill anti-diagonal gaps (top-right to bottom-left)
        for s, rs in anti_diags.items():
            for r in range(min(rs), max(rs) + 1):
                c = s - r
                if 0 <= c < W:
                    out[r][c] = color

        return out

    colors = list(color_pts.keys())

    # If there is only one non-background color, complete it.
    if len(colors) == 1:
        return fill_8_way(color_pts[colors[0]], colors[0])

    # The occluding shape is the color that forms a solid axis-aligned rectangle.
    solid = [c for c in colors if len(color_pts[c]) == bbox_area(color_pts[c])]

    if solid:
        non_solid = [c for c in colors if c not in solid]
        if non_solid:
            # Keep the non-rectangular / gappier color.
            keep = max(
                non_solid,
                key=lambda c: (bbox_area(color_pts[c]) - len(color_pts[c]),
                               bbox_area(color_pts[c]))
            )
        else:
            # Fallback: if both are rectangles, keep the smaller one.
            keep = min(
                colors,
                key=lambda c: (bbox_area(color_pts[c]), len(color_pts[c]))
            )
    else:
        # Fallback: keep the color that is least like a solid rectangle.
        keep = max(
            colors,
            key=lambda c: (bbox_area(color_pts[c]) - len(color_pts[c]),
                           bbox_area(color_pts[c]))
        )

    return fill_8_way(color_pts[keep], keep)

