    grid = [list(map(int, row)) for row in grid]
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    out = [row[:] for row in grid]

    info = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0:
                continue
            if v not in info:
                info[v] = {
                    "count": 0,
                    "rmin": r,
                    "rmax": r,
                    "cmin": c,
                    "cmax": c,
                }
            d = info[v]
            d["count"] += 1
            d["rmin"] = min(d["rmin"], r)
            d["rmax"] = max(d["rmax"], r)
            d["cmin"] = min(d["cmin"], c)
            d["cmax"] = max(d["cmax"], c)

    if len(info) < 2:
        return out

    def bbox_area(v):
        d = info[v]
        return (d["rmax"] - d["rmin"] + 1) * (d["cmax"] - d["cmin"] + 1)

    # Target: most frequent colour (tie-broken by larger bounding box).
    target = max(info.keys(), key=lambda v: (info[v]["count"], bbox_area(v), v))

    # Payload: least frequent other colour (tie-broken by smaller bounding box).
    payload = min(
        (v for v in info if v != target),
        key=lambda v: (info[v]["count"], bbox_area(v), v),
    )

    t = info[target]
    p = info[payload]

    def center(v):
        d = info[v]
        return (
            (d["rmin"] + d["rmax"] + 1) // 2,
            (d["cmin"] + d["cmax"] + 1) // 2,
        )

    tr, tc = center(target)
    pr, pc = center(payload)
    dr = tr - pr
    dc = tc - pc

    # Remove the payload from its original location.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == payload:
                out[r][c] = 0

    # Move the payload so its bounding-box centre aligns with the target's.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == payload:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = payload

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])

    # Count non-background colours and find the unique "seed" colour.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    # Usually exactly one colour appears once.  Fallbacks keep the function safe.
    seed_color = None
    one_pixels = [(r, c, v) for v, n in counts.items() if n == 1]
    if one_pixels:
        # If there is more than one single pixel, use the least frequent
        # non-zero colour; in the given tasks this is the unique seed.
        r, c, seed_color = min(one_pixels, key=lambda x: (x[2], x[0], x[1]))
    elif counts:
        seed_color = min(counts, key=lambda v: (counts[v], v))
        for r in range(h):
            if seed_color in grid[r]:
                c = grid[r].index(seed_color)
                break
    else:
        return [row[:] for row in grid]

    sr, sc = None, None
    for r in range(h):
        if grid[r][sc if sr is not None else c] == seed_color:
            sr = r
            sc = c
            break
    # More robustly, if the previous search could have been ambiguous:
    if sr is None:
        for r in range(h):
            for c in range(w):
                if grid[r][c] == seed_color:
                    sr, sc = r, c
                    break
            if sr is not None:
                break

    out = [row[:] for row in grid]

    # Distances to the first non-zero cell in each cardinal direction.
    def dist_up():
        for r in range(sr - 1, -1, -1):
            if grid[r][sc] != 0:
                return sr - r
        return sr + 1

    def dist_down():
        for r in range(sr + 1, h):
            if grid[r][sc] != 0:
                return r - sr
        return h - sr

    def dist_left():
        for c in range(sc - 1, -1, -1):
            if grid[sr][c] != 0:
                return sc - c
        return sc + 1

    def dist_right():
        for c in range(sc + 1, w):
            if grid[sr][c] != 0:
                return c - sc
        return w - sc

    du, dd, dl, dr = dist_up(), dist_down(), dist_left(), dist_right()

    # Choose the axis perpendicular to the closest wall(s).
    # Ties prefer vertical, matching the examples.
    min_dist = min(du, dd, dl, dr)
    vertical = (du == min_dist or dd == min_dist)

    if vertical:
        # Fill the whole clear vertical segment containing the seed.
        for r in range(sr - 1, -1, -1):
            if out[r][sc] == 0:
                out[r][sc] = seed_color
            else:
                break
        for r in range(sr + 1, h):
            if out[r][sc] == 0:
                out[r][sc] = seed_color
            else:
                break
    else:
        # Fill the whole clear horizontal segment containing the seed.
        for c in range(sc - 1, -1, -1):
            if out[sr][c] == 0:
                out[sr][c] = seed_color
            else:
                break
        for c in range(sc + 1, w):
            if out[sr][c] == 0:
                out[sr][c] = seed_color
            else:
                break

    return out

