def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows = [tuple(int(x) for x in row) for row in grid]

    # Prefer rows that look like the background template:
    # they contain background 0s and also non-zero vertical-line pixels.
    candidates = [r for r in rows if 0 in r and any(x != 0 for x in r)]
    if not candidates:
        candidates = [r for r in rows if 0 in r]
    if not candidates:
        candidates = rows

    counts = Counter(candidates)

    # The background/template row is the most background-like row.
    # It has the most 0s; ties are broken by frequency.
    base = max(counts, key=lambda r: (r.count(0), counts[r]))

    out = [[int(x) for x in row] for row in grid]

    # Overlay the vertical line pattern from the template row onto every row.
    for c, val in enumerate(base):
        if val != 0:
            for r in range(len(out)):
                out[r][c] = val

    return out

