    for r in range(h):
        for c in (0, w - 1):
            if a[r][c] == 0 and not visited[r][c]:
                visited[r][c] = True
                q.append((r, c))

    for c in range(w):
        for r in (0, h - 1):
            if a[r][c] == 0 and not visited[r][c]:
                visited[r][c] = True
                q.append((r, c))

    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Flood fill outside background.
    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if a[nr][nc] == 0 and not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc))

    # Any remaining 0 components are enclosed holes.
    for r in range(h):
        for c in range(w):
            if a[r][c] == 0 and not visited[r][c]:
                component = []
                neighbor_counts = {}
                dq = deque([(r, c)])
                visited[r][c] = True

                while dq:
                    cr, cc = dq.popleft()
                    component.append((cr, cc))

                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            v = a[nr][nc]
                            if v == 0:
                                if not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    dq.append((nr, nc))
                            else:
                                neighbor_counts[v] = neighbor_counts.get(v, 0) + 1

                if neighbor_counts:
                    fill_color = min(
                        neighbor_counts,
                        key=lambda color: (-neighbor_counts[color], color)
                    )
