from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])
    seen = [[False] * W for _ in range(H)]
    candidates = []

    def add_candidate(r1, r2, c1, c2, color):
        h = r2 - r1 + 1
        w = c2 - c1 + 1
        if h < 3 or w < 3:
            return

        area = h * w
        cnt_color = 0
        cnt_zero = 0
        border_color = 0
        interior_zero = 0
        interior_area = 0

        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                v = grid[r][c]
                if v == color:
                    cnt_color += 1
                if v == 0:
                    cnt_zero += 1

                is_border = (r == r1 or r == r2 or c == c1 or c == c2)
                if is_border:
                    if v == color:
                        border_color += 1
                else:
                    interior_area += 1
                    if v == 0:
                        interior_zero += 1

        solid_score = 2 * cnt_color - area
        hollow_score = 2 * (border_color + interior_zero) - area

        if solid_score >= hollow_score:
            shape = "solid"
            score = solid_score
        else:
            shape = "hollow"
            score = hollow_score

        # Accept reasonably regular candidates.  The threshold is chosen so
        # that small perfect/near-perfect 3x3 blocks are kept, while larger
        # blocks need a correspondingly large number of matching cells.
        min_score = max(7, int(0.6 * area) + (1 if (0.6 * area) % 1 >= 0.5 else 0))
        if score < min_score:
            return

        candidates.append((score, r1, r2, c1, c2, color, shape))

    def trim_component(color, comp_cells):
        r1 = min(r for r, _ in comp_cells)
        r2 = max(r for r, _ in comp_cells)
        c1 = min(c for _, c in comp_cells)
        c2 = max(c for _, c in comp_cells)

        # Iteratively remove boundary rows/columns that are too sparse.
        # This removes isolated noise cells attached to the component.
        while True:
            h = r2 - r1 + 1
            w = c2 - c1 + 1
            if h < 3 or w < 3:
                return

            top_count = sum(1 for c in range(c1, c2 + 1) if grid[r1][c] == color)
            bottom_count = sum(1 for c in range(c1, c2 + 1) if grid[r2][c] == color)
            left_count = sum(1 for r in range(r1, r2 + 1) if grid[r][c1] == color)
            right_count = sum(1 for r in range(r1, r2 + 1) if grid[r][c2] == color)

            cut_top = (top_count * 2) < w
            cut_bottom = (bottom_count * 2) < w
            cut_left = (left_count * 2) < h
            cut_right = (right_count * 2) < h

            if not (cut_top or cut_bottom or cut_left or cut_right):
                break

            if cut_top:
                r1 += 1
            if cut_bottom:
                r2 -= 1
            if cut_left:
                c1 += 1
            if cut_right:
                c2 -= 1

        if r2 - r1 + 1 >= 3 and c2 - c1 + 1 >= 3:
            add_candidate(r1, r2, c1, c2, color)

    # Find connected monochromatic components and turn substantial ones
    # into cleaned rectangular objects.
    for sr in range(H):
        for sc in range(W):
            color = grid[sr][sc]
            if color == 0 or seen[sr][sc]:
                continue

            q = deque([(sr, sc)])
            seen[sr][sc] = True
            cells = []
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        q.append((nr, nc))

            if len(cells) >= 4:
                trim_component(color, cells)

    if not candidates:
        return [[0] * W]

    # Keep the strongest non-overlapping objects.
    candidates.sort(key=lambda x: (-x[0], x[1], x[3], x[2], x[4], x[5]))
    accepted = []
    for score, r1, r2, c1, c2, color, shape in candidates:
        ok = True
        for ar1, ar2, ac1, ac2, _, _ in accepted:
            if r1 <= ar2 and ar1 <= r2 and c1 <= ac2 and ac1 <= c2:
                ok = False
                break
        if ok:
            accepted.append((r1, r2, c1, c2, color, shape))

    # Order horizontally, then vertically, for stable output.
    def sort_key(item):
        r1, r2, c1, c2, _, _ = item
        return (c1 + c2, r1 + r2, r1, c1)

    accepted.sort(key=sort_key)

    blocks = []
    for r1, r2, c1, c2, color, shape in accepted:
        h = r2 - r1 + 1
        w = c2 - c1 + 1
        block = [[0] * w for _ in range(h)]
        for i in range(h):
            for j in range(w):
                if shape == "solid" or i == 0 or i == h - 1 or j == 0 or j == w - 1:
                    block[i][j] = color
        blocks.append(block)

    out_h = max(b[0] for b in blocks)
    out = []
    for i in range(out_h):
        row = []
        for b in blocks:
            if i < len(b):
                row.extend(b[i])
            else:
                row.extend([0] * len(b[0]))
        out.append(row)

    return out

import sys

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    colors = set()
    for row in grid:
        for v in row:
            if v != 0:
                colors.add(v)

    # Prefix sums for each present colour and for non-zero cells.
    def build_prefix(func):
        pref = [[0] * (W + 1) for _ in range(H + 1)]
        for i in range(H):
            row_acc = 0
            prev = pref[i]
            cur = pref[i + 1]
            for j in range(W):
                row_acc += func(i, j)
                cur[j + 1] = prev[j + 1] + row_acc
        return pref

    def rect_sum(pref, r1, c1, r2, c2):
        if r1 > r2 or c1 > c2:
            return 0
        return (
            pref[r2 + 1][c2 + 1]
            - pref[r1][c2 + 1]
            - pref[r2 + 1][c1]
            + pref[r1][c1]
        )

    pref_nz = build_prefix(lambda i, j: 1 if grid[i][j] != 0 else 0)
    pref_color = {}
    for c in colors:
        pref_color[c] = build_prefix(lambda i, j, c=c: 1 if grid[i][j] == c else 0)

    candidates = []  # (type, color, r1, r2, c1, c2, area)
    # type: 0 = solid, 1 = hollow

    # ------------------------------------------------------------
    # Solid rectangles: maximal monochromatic rectangles, size >= 3x3.
    # ------------------------------------------------------------
    for c in colors:
        pc = pref_color[c]

        for r1 in range(H - 2):
            valid = [grid[r1][j] == c for j in range(W)]

            for r2 in range(r1 + 1, H):
                row = grid[r2]
                for j in range(W):
                    valid[j] = valid[j] and (row[j] == c)

                h = r2 - r1 + 1
                if h < 3:
                    continue

                j = 0
                while j < W:
                    if not valid[j]:
                        j += 1
                        continue

                    c1 = j
                    while j < W and valid[j]:
                        j += 1
                    c2 = j - 1
                    w = c2 - c1 + 1

                    if w < 3:
                        continue

                    # Keep only rectangles that cannot be extended by one
                    # full side while remaining solid in the same colour.
                    if r1 > 0 and rect_sum(pc, r1 - 1, c1, r1 - 1, c2) == w:
                        continue
                    if r2 + 1 < H and rect_sum(pc, r2 + 1, c1, r2 + 1, c2) == w:
                        continue
                    if c1 > 0 and rect_sum(pc, r1, c1 - 1, r2, c1 - 1) == h:
                        continue
                    if c2 + 1 < W and rect_sum(pc, r1, c2 + 1, r2, c2 + 1) == h:
                        continue

                    candidates.append((0, c, r1, r2, c1, c2, h * w))

    # ------------------------------------------------------------
    # Hollow rectangles:
    #   border is one non-zero colour, interior is entirely zero.
    # ------------------------------------------------------------
    for c in colors:
        pc = pref_color[c]

        for r1 in range(H - 2):
            top = grid[r1]
            for r2 in range(r1 + 2, H):
                h = r2 - r1 + 1
                bottom = grid[r2]

                for c1 in range(W - 2):
                    # quick prune: left border must start with colour c
                    if top[c1] != c or bottom[c1] != c:
                        continue

                    for c2 in range(c1 + 2, W):
                        if top[c2] != c or bottom[c2] != c:
                            continue

                        w = c2 - c1 + 1
                        perimeter = 2 * w + 2 * (h - 2)

                        # All colour cells must lie exactly on the border.
                        if rect_sum(pc, r1, c1, r2, c2) != perimeter:
                            continue

                        # Interior must be background only.
                        if rect_sum(pref_nz, r1 + 1, c1 + 1, r2 - 1, c2 - 1) != 0:
                            continue

                        candidates.append((1, c, r1, r2, c1, c2, h * w))

    if not candidates:
        return [[0]]

    # Remove duplicates.
    unique = list({(t, c, r1, r2, c1, c2, area) for (t, c, r1, r2, c1, c2, area) in candidates})

    # Greedily remove overlapping candidates, keeping larger ones first.
    def overlaps(a, b):
        return a[2] <= b[3] and b[2] <= a[3] and a[4] <= b[5] and b[4] <= a[5]

    unique.sort(key=lambda x: (-x[6], x[4], x[2], x[5], x[3]))
    selected = []
    for cand in unique:
        ok = True
        for other in selected:
            if overlaps(cand, other):
                ok = False
                break
        if ok:
            selected.append(cand)

    # Final horizontal order: left to right, then top to bottom.
    selected.sort(key=lambda x: (x[4], x[2], x[5], x[3], -x[6]))

    blocks = []
    for t, c, r1, r2, c1, c2, _ in selected:
        h = r2 - r1 + 1
        w = c2 - c1 + 1

        if t == 0:  # solid
            block = [[c] * w for _ in range(h)]
        else:       # hollow
            block = [
                [
                    c if (i == 0 or i == h - 1 or j == 0 or j == w - 1) else 0
                    for j in range(w)
                ]
                for i in range(h)
            ]
        blocks.append(block)

    if not blocks:
        return [[0]]

    out_h = max(len(b) for b in blocks)
    out = []
    for i in range(out_h):
        row = []
        for b in blocks:
            if i < len(b):
                row.extend(b[i])
            else:
                row.extend([0] * len(b[0]))
        out.append(row)

    return out

