def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [[0]]

    H, W = len(grid), len(grid[0])

    def is_zero_row(r):
        return all(grid[r][c] == 0 for c in range(W))

    def is_zero_col(c):
        return all(grid[r][c] == 0 for r in range(H))

    # Find contiguous zero-line separators.
    candidates = []

    r = 0
    while r < H:
        if is_zero_row(r):
            start = r
            while r < H and is_zero_row(r):
                r += 1
            end = r - 1
            if 0 < start and end < H - 1:
                candidates.append(('H', start, end))
        else:
            r += 1

    c = 0
    while c < W:
        if is_zero_col(c):
            start = c
            while c < W and is_zero_col(c):
                c += 1
            end = c - 1
            if 0 < start and end < W - 1:
                candidates.append(('V', start, end))
        else:
            c += 1

    if not candidates:
        return [[0]]

    def split(kind, a, b):
        if kind == 'H':
            return grid[:a], grid[b + 1:]
        else:
            return [row[:a] for row in grid], [row[b + 1:] for row in grid]

    def panel_quality(p):
        if not p or not p[0]:
            return 0
        colors = {v for row in p for v in row}
        if len(colors) >= 2:
            return 2
        if colors and next(iter(colors)) != 0:
            return 1
        return 0

    # Choose the separator that leaves two meaningful panels.
    best = max(candidates,
               key=lambda kv: (panel_quality(*split(kv[0], kv[1], kv[2])),
                               kv[2] - kv[1],
                               kv[0]))
    p1, p2 = split(*best)

    if not p1 or not p2 or not p1[0] or not p2[0]:
        return [[0]]

    def background_color(panel):
        h, w = len(panel), len(panel[0])
        border_counts = {}

        def add(v):
            border_counts[v] = border_counts.get(v, 0) + 1

        for c in range(w):
            add(panel[0][c])
            add(panel[-1][c])
        for r in range(1, h - 1):
            add(panel[r][0])
            add(panel[r][-1])

        overall_counts = {}
        for row in panel:
            for v in row:
                overall_counts[v] = overall_counts.get(v, 0) + 1

        if border_counts:
            border_bg = max(border_counts, key=lambda x: border_counts[x])
            # Prefer the border mode when it dominates the border.
            if border_counts[border_bg] * 2 > sum(border_counts.values()):
                return border_bg

        return max(overall_counts, key=lambda x: overall_counts[x])

    def crop(mask):
        rows = [i for i, row in enumerate(mask) if any(row)]
        if not rows:
            return None
        cols = [j for j in range(len(mask[0])) if any(mask[i][j] for i in range(len(mask)))]
        r0, r1 = rows[0], rows[-1]
        c0, c1 = cols[0], cols[-1]
        return [[mask[i][j] for j in range(c0, c1 + 1)] for i in range(r0, r1 + 1)]

    def has_hole(mask):
        h, w = len(mask), len(mask[0])
        visited = [[False] * w for _ in range(h)]
        q = deque()

        for i in range(h):
            for j in range(w):
                if mask[i][j] == 0 and (i == 0 or i == h - 1 or j == 0 or j == w - 1):
                    visited[i][j] = True
                    q.append((i, j))

        while q:
            i, j = q.popleft()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < h and 0 <= nj < w and not visited[ni][nj] and mask[ni][nj] == 0:
                    visited[ni][nj] = True
                    q.append((ni, nj))

        for i in range(h):
            for j in range(w):
                if mask[i][j] == 0 and not visited[i][j]:
                    return True
        return False

    def color_masks(panel, color):
        h, w = len(panel), len(panel[0])
        return [[1 if panel[i][j] == color else 0 for j in range(w)] for i in range(h)]

    bg1 = background_color(p1)
    bg2 = background_color(p2)

    colors1 = {v for row in p1 for v in row} - {bg1}
    colors2 = {v for row in p2 for v in row} - {bg2}

    # Try any non-background color that appears in both panels.
    for color in colors1 & colors2:
        m1 = crop(color_masks(p1, color))
        m2 = crop(color_masks(p2, color))

        if not m1 or not m2:
            continue
        if len(m1) != len(m2) or len(m1[0]) != len(m2[0]):
            continue

        if all(m1[i][j] == m2[i][j] for i in range(len(m1)) for j in range(len(m1[0]))):
            if has_hole(m1):
                return [[1 if v else 0 for v in row] for row in m1]

    return [[0]]

