def transform(grid: list[list[int]]) -> list[list[int]]:
    grid = [list(row) for row in grid]
    H = len(grid)
    if H == 0:
        return [[0]]
    W = len(grid[0])
    if W == 0:
        return [[0]]

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # Find connected components that are thin rectangular frames.
    visited = [[False] * W for _ in range(H)]
    frame_cells = []
    frame_colors = set()
    color_counts = {}

    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                color_counts[v] = color_counts.get(v, 0) + 1

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                stack = [(r, c)]
                visited[r][c] = True
                comp = []

                while stack:
                    rr, cc = stack.pop()
                    comp.append((rr, cc))
                    for dr, dc in dirs:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                if len(comp) >= 8:
                    min_r = min(r_ for r_, c_ in comp)
                    max_r = max(r_ for r_, c_ in comp)
                    min_c = min(c_ for r_, c_ in comp)
                    max_c = max(c_ for r_, c_ in comp)
                    h = max_r - min_r + 1
                    w = max_c - min_c + 1

                    if h >= 3 and w >= 3:
                        perimeter = 2 * h + 2 * w - 4
                        if len(comp) == perimeter:
                            comp_set = set(comp)
                            ok = True

                            for cc in range(min_c, max_c + 1):
                                if (min_r, cc) not in comp_set or (max_r, cc) not in comp_set:
                                    ok = False
                                    break

                            if ok:
                                for rr in range(min_r, max_r + 1):
                                    if (rr, min_c) not in comp_set or (rr, max_c) not in comp_set:
                                        ok = False
                                        break

                            if ok:
                                frame_colors.add(color)
                                frame_cells.extend(comp)

    # Mark frame cells as barriers.
    frame_mask = [[False] * W for _ in range(H)]
    if frame_cells:
        for rr, cc in frame_cells:
            frame_mask[rr][cc] = True
    elif color_counts:
        # Fallback: treat the most frequent non-zero color as the frame.
        fc = max(color_counts, key=lambda x: color_counts[x])
        frame_colors.add(fc)
        for r in range(H):
            for c in range(W):
                if grid[r][c] == fc:
                    frame_mask[r][c] = True

    # Flood-fill the exterior through all non-frame cells.
    seen = [[False] * W for _ in range(H)]
    q = deque()

    def add(r, c):
        if 0 <= r < H and 0 <= c < W and not frame_mask[r][c] and not seen[r][c]:
            seen[r][c] = True
            q.append((r, c))

    for r in range(H):
        add(r, 0)
        add(r, W - 1)
    for c in range(W):
        add(0, c)
        add(H - 1, c)

    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and not frame_mask[nr][nc] and not seen[nr][nc]:
                seen[nr][nc] = True
                q.append((nr, nc))

    # Prefer the color(s) that appear inside the frame(s).
    dot_colors = set()
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0 and v not in frame_colors and not frame_mask[r][c] and not seen[r][c]:
                dot_colors.add(v)

    if not dot_colors:
        # Fallback: count every non-frame colored pixel outside.
        for r in range(H):
            for c in range(W):
                v = grid[r][c]
                if v != 0 and v not in frame_colors and not frame_mask[r][c]:
                    dot_colors.add(v)

    # Count the selected dot-color pixels that are outside.
    count = 0
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v in dot_colors and not frame_mask[r][c] and seen[r][c]:
                count += 1

    if count == 0:
        return [[0]]
    return [[0] for _ in range(count)]

