def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    H = len(grid)
    W = len(grid[0]) if H else 0

    # Normalize to a Python 2D list of ints.
    g = [[int(grid[r][c]) for c in range(W)] for r in range(H)]
    if H == 0 or W == 0:
        return g

    # Find 4-connected monochromatic components.
    visited = [[False] * W for _ in range(H)]
    comps = []

    for r in range(H):
        for c in range(W):
            if g[r][c] != 0 and not visited[r][c]:
                color = g[r][c]
                stack = [(r, c)]
                visited[r][c] = True

                cells = []
                min_r = max_r = r
                min_c = max_c = c

                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))

                    if cr < min_r:
                        min_r = cr
                    if cr > max_r:
                        max_r = cr
                    if cc < min_c:
                        min_c = cc
                    if cc > max_c:
                        max_c = cc

                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if (
                            0 <= nr < H
                            and 0 <= nc < W
                            and not visited[nr][nc]
                            and g[nr][nc] == color
                        ):
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                comps.append(
                    {
                        "cells": cells,
                        "min_r": min_r,
                        "max_r": max_r,
                        "min_c": min_c,
                        "color": color,
                    }
                )

    if not comps:
        return g

    # Select the topmost object.  If several objects share the same top row,
    # prefer the leftmost one; if it can move, that is the one moved.
    comps.sort(key=lambda comp: (comp["min_r"], comp["min_c"]))
    top_r = comps[0]["min_r"]

    def drop_distance(comp):
        """How far this component can be shifted down without overlap."""
        cells = comp["cells"]
        comp_set = set(cells)
        best = 0
        hits_object = False

        # Maximum possible shift without leaving the grid.
        for d in range(1, H - comp["max_r"]):
            ok = True
            for r, c in cells:
                nr = r + d
                if nr >= H:
                    ok = False
                    break
                # A destination cell is invalid only if it was occupied by
                # a different component in the original grid.
                if g[nr][c] != 0 and (nr, c) not in comp_set:
                    ok = False
                    hits_object = True
                    break

            if ok:
                best = d
            else:
                break

        return best, hits_object

    selected = None
    delta = 0

    # Prefer a top-row object that stops because it would touch another object.
    for comp in comps:
        if comp["min_r"] != top_r:
            break
        d, hit = drop_distance(comp)
        if d > 0 and hit:
            selected = comp
            delta = d
            break

    # Fallback: if no such top-row object exists, move the first top-row
    # object that can move at all (e.g. all the way to the bottom).
    if selected is None:
        for comp in comps:
            if comp["min_r"] != top_r:
                break
            d, _ = drop_distance(comp)
            if d > 0:
                selected = comp
                delta = d
                break

    if selected is None or delta == 0:
        return g

    # Apply the vertical shift.
    result = [row[:] for row in g]

    for r, c in selected["cells"]:
        result[r][c] = 0

    for r, c in selected["cells"]:
        result[r + delta][c] = selected["color"]

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])

    out = [[int(grid[r][c]) for c in range(w)] for r in range(h)]
    seeds = [(r, c) for r in range(h) for c in range(w) if int(grid[r][c]) == 7]

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for r, c in seeds:
        for dr, dc in directions:
            step = 1
            while True:
                rr = r + dr * step
                cc = c + dc * step

                if not (0 <= rr < h and 0 <= cc < w):
                    break

                val = int(grid[rr][cc])

                if val == 4:
                    for k in range(1, step):
                        out[r + dr * k][c + dc * k] = 7
                    break

                if val != 0 and val != 7:
                    break

                step += 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    grid = [[int(grid[r][c]) for c in range(W)] for r in range(H)]
    out = [row[:] for row in grid]

    top = bottom = left = right = None
    seeds = []
    has_four = False

    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v == 4:
                has_four = True
                if top is None:
                    top = bottom = r
                    left = right = c
                else:
                    if r < top:
                        top = r
                    if r > bottom:
                        bottom = r
                    if c < left:
                        left = c
                    if c > right:
                        right = c
            elif v == 7:
                seeds.append((r, c))

    if not has_four or not seeds:
        return out

    for r, c in seeds:
        candidates = []

        if r < top:
            candidates.append((top - r, 0, "down"))
        elif r > bottom:
            candidates.append((r - bottom, 0, "up"))

        if c < left:
            candidates.append((left - c, 1, "right"))
        elif c > right:
            candidates.append((c - right, 1, "left"))

        if candidates:
            candidates.sort(key=lambda x: (x[0], x[1]))
            direction = candidates[0][2]
        else:
            # Fallback for a 7 on or inside the 4 bounding box:
            # shoot away from the nearest side.
            d_top = r - top
            d_bottom = bottom - r
            d_left = c - left
            d_right = right - c
            m = min(d_top, d_bottom, d_left, d_right)

            if d_top == m:
                direction = "down"
            elif d_bottom == m:
                direction = "up"
            elif d_left == m:
                direction = "right"
            else:
                direction = "left"

        if direction == "right":
            end = right - 1
            if end < c:
                end = c
            for cc in range(c, end + 1):
                out[r][cc] = 7

        elif direction == "left":
            end = left + 1
            if end > c:
                end = c
            for cc in range(c, end - 1, -1):
                out[r][cc] = 7

        elif direction == "down":
            end = bottom - 1
            if end < r:
                end = r
            for rr in range(r, end + 1):
                out[rr][c] = 7

        else:  # up
            end = top + 1
            if end > r:
                end = r
            for rr in range(r, end - 1, -1):
                out[rr][c] = 7

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    H = len(grid)
    W = max(len(row) for row in grid)

    # Normalise input to a plain 2D list of ints.
    g = [[0] * W for _ in range(H)]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if c < W:
                g[r][c] = int(v)

    # Group all non-zero cells by colour.
    cells_by_color = {}
    for r in range(H):
        for c in range(W):
            v = g[r][c]
            if v != 0:
                cells_by_color.setdefault(v, []).append((r, c))

    if not cells_by_color:
        return [[0] * W for _ in range(H)]

    # Build object descriptors.
    objects = []
    for color, cells in cells_by_color.items():
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)

        objects.append({
            "color": color,
            "cells": cells,
            "top": min_r,
            "left": min_c,
            "height": max_r - min_r + 1,
            "count": len(cells),
        })

    # Keep the original top margin.
    start_row = min(obj["top"] for obj in objects)

    # Sort by size (number of cells), with stable top-to-bottom tie-breaking.
    objects.sort(key=lambda obj: (obj["count"], obj["top"], obj["left"]))

    # Reconstruct the grid by stacking sorted objects.
    out = [[0] * W for _ in range(H)]
    cursor = start_row

    for obj in objects:
        color = obj["color"]
        top = obj["top"]

        for r, c in obj["cells"]:
            nr = cursor + (r - top)
            # Preserve original horizontal position.
            if 0 <= nr < H and 0 <= c < W:
                out[nr][c] = color

        cursor += obj["height"]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [[]]

    h = len(grid)
    w = len(grid[0])

    # First appearance of each non-zero color, used only as a tie-breaker.
    first_seen = {}
    for r in range(h):
        for c in range(w):
            v = int(grid[r][c])
            if v != 0 and v not in first_seen:
                first_seen[v] = (r, c)

    if not first_seen:
        return [[]]

    # Add a virtual zero border and compute shortest distance from the outside.
    # Moving through non-zero cells is allowed; this gives each color's
    # distance from the exterior.
    H = h + 2
    W = w + 2
    dist = [[-1] * W for _ in range(H)]
    q = []
    in_q = [[False] * W for _ in range(H)]

    for i in range(H):
        for j in (0, W - 1):
            if not in_q[i][j]:
                dist[i][j] = 0
                in_q[i][j] = True
                q.append((i, j))
    for j in range(W):
        for i in (0, H - 1):
            if not in_q[i][j]:
                dist[i][j] = 0
                in_q[i][j] = True
                q.append((i, j))

    head = 0
    while head < len(q):
        i, j = q[head]
        head += 1
        nd = dist[i][j] + 1
        for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= ni < H and 0 <= nj < W and not in_q[ni][nj]:
                dist[ni][nj] = nd
                in_q[ni][nj] = True
                q.append((ni, nj))

    min_dist = {}
    for r in range(h):
        for c in range(w):
            v = int(grid[r][c])
            if v != 0:
                d = dist[r + 1][c + 1]
                if v not in min_dist or d < min_dist[v]:
                    min_dist[v] = d

    colors = sorted(min_dist, key=lambda v: (min_dist[v], first_seen[v]))
    return [colors]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    grid = [list(map(int, row)) for row in grid]
    h = len(grid)
    w = len(grid[0])

    def line_row_info(row):
        vals = [v for v in row if v != 0]
        if not vals:
            return None
        if len(set(vals)) != 1:
            return None

        color = vals[0]
        pos = [i for i, v in enumerate(row) if v != 0]

        # Solid horizontal line: one non-zero colour across the whole row.
        if len(pos) == w:
            return color, pos

        # Dashed horizontal line: same colour at every other column.
        if len(pos) >= 2 and pos[0] in (0, 1):
            if all(pos[i + 1] - pos[i] == 2 for i in range(len(pos) - 1)):
                if len(pos) == len(range(pos[0], w, 2)):
                    return color, pos

        return None

    candidates = []
    for r, row in enumerate(grid):
        info = line_row_info(row)
        if info is None:
            continue

        color, pos = info

        # Prefer a line that is not part of a thicker same-coloured block.
        adjacency = 0
        if r > 0:
            adjacency += sum(1 for p in pos if grid[r - 1][p] == color)
        if r + 1 < h:
            adjacency += sum(1 for p in pos if grid[r + 1][p] == color)

        total = sum(row.count(color) for row in grid)
        candidates.append((adjacency, total, r))

    if candidates:
        candidates.sort()
        separator = candidates[0][2]
    else:
        separator = None

    out = [row[:] for row in grid]
    if separator is not None:
        for r in range(separator + 1, h):
            out[r] = [0] * w

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0]) if h else 0
    if w == 0:
        return [row[:] for row in grid]

    # Find connected components of non-background pixels.
    # Components are 4-connected and uniform in colour.
    visited = [[False] * w for _ in range(h)]
    components = []  # each entry: [list_of_cells, colour]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                colour = int(grid[r][c])
                stack = [(r, c)]
                visited[r][c] = True
                cells = []

                while stack:
                    rr, cc = stack.pop()
                    cells.append((rr, cc))

                    for dr, dc in dirs:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if not visited[nr][nc] and int(grid[nr][nc]) == colour:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                components.append([cells, colour])

    if not components:
        return [row[:] for row in grid]

    # Apply downward gravity: all components fall as rigid bodies,
    # stopping when they would leave the grid or overlap another component.
    while True:
        occupied = set()
        for cells, _ in components:
            for r, c in cells:
                occupied.add((r, c))

        moving = []
        for i, (cells, _) in enumerate(components):
            can_move = True
            for r, c in cells:
                nr = r + 1
                if nr >= h or (nr, c) in occupied:
                    can_move = False
                    break
            if can_move:
                moving.append(i)

        if not moving:
            break

        for i in moving:
            cells, colour = components[i]
            components[i][0] = [(r + 1, c) for r, c in cells]

    out = [[0] * w for _ in range(h)]
    for cells, colour in components:
        for r, c in cells:
            out[r][c] = colour

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])

    result = [[0] * w for _ in range(h)]

    for c in range(w):
        falling = []
        for r in range(h):
            v = int(grid[r][c])
            if v != 0:
                falling.append(v)

        start = h - len(falling)
        for i, v in enumerate(falling):
            result[start + i][c] = v

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        return lower[:-1] + upper[:-1]

    def strictly_inside_hull(p, points):
        hull = convex_hull(points)
        n = len(hull)
        if n < 3:
            return False

        area2 = 0
        for i in range(n):
            x1, y1 = hull[i]
            x2, y2 = hull[(i + 1) % n]
            area2 += x1 * y2 - y1 * x2

        if area2 == 0:
            return False

        sign = 1 if area2 > 0 else -1

        for i in range(n):
            x1, y1 = hull[i]
            x2, y2 = hull[(i + 1) % n]
            c = (x2 - x1) * (p[1] - y1) - (y2 - y1) * (p[0] - x1)
            if sign * c <= 0:
                return False
        return True

    out = [list(row) for row in grid]
    h = len(out)
    if h == 0:
        return out
    w = len(out[0])

    twos = []
    fours = []

    for r in range(h):
        for c in range(w):
            if out[r][c] == 2:
                twos.append((c, r))
            elif out[r][c] == 4:
                fours.append((c, r))

    if not fours:
        return out

    # If there is no closed 2-region, the 4 is not enclosed.
    if not twos:
        for r in range(h):
            for c in range(w):
                if out[r][c] == 4:
                    out[r][c] = 0
        return out

    enclosed = any(strictly_inside_hull(p, twos) for p in fours)

    if enclosed:
