        for r in range(h):
            for c in range(w):
                if out[r][c] == 2:
                    out[r][c] = 0
    else:
        # The 4 is outside: remove the 4.
        for r in range(h):
            for c in range(w):
                if out[r][c] == 4:
                    out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
