        return [row[:] for row in grid]

    # Count non-background colours.
    counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if not counts:
        return grid

    # Tie-breaker: prefer the colour that forms longer vertical runs.
    def max_vertical_run(color: int) -> int:
        best = 0
        for c in range(cols):
            run = 0
            for r in range(rows):
                if grid[r][c] == color:
                    run += 1
                    if run > best:
                        best = run
                else:
                    run = 0
        return best

    vertical_runs = {color: max_vertical_run(color) for color in counts}
    main_color = max(counts, key=lambda color: (counts[color], vertical_runs[color]))

    out = [row[:] for row in grid]

    # For each vertical segment of the main colour, if the cell immediately
    # below it is another non-background colour, recolour that segment.
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r][c] == main_color:
                start = r
                while r < rows and grid[r][c] == main_color:
                    r += 1

                if r < rows:
                    below = grid[r][c]
                    if below != 0 and below != main_color:
                        for rr in range(start, r):
                            out[rr][c] = below
            else:
                r += 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        hull = lower[:-1] + upper[:-1]

        area2 = sum(
            hull[i][0] * hull[(i + 1) % len(hull)][1]
            - hull[(i + 1) % len(hull)][0] * hull[i][1]
            for i in range(len(hull))
        )
        if area2 < 0:
            hull.reverse()
        return hull

    def point_in_convex_hull(hull, p):
        if len(hull) < 3:
            return False
        for i in range(len(hull)):
            if cross(hull[i], hull[(i + 1) % len(hull)], p) < 0:
                return False
        return True

    if not grid or not grid[0]:
        return grid

    twos = []
    fours = []

    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 2:
                twos.append((c, r))
            elif v == 4:
                fours.append((c, r))

    if not twos:
        keep_four = True
    elif not fours:
        keep_four = False
    else:
        hull = convex_hull(twos)
        keep_four = all(point_in_convex_hull(hull, p) for p in fours)

    h = len(grid)
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if keep_four and v == 4:
                out[r][c] = v
            elif not keep_four and v == 2:
                out[r][c] = v

    return out

def _cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def _convex_hull(points):
    """
    Monotone-chain convex hull.
    Points are (x, y) tuples.  Collinear boundary points are omitted,
    so only extreme vertices are returned.
    """
    pts = sorted(set(points))
    if len(pts) <= 2:
        return pts

    lower = []
    for p in pts:
        while len(lower) >= 2 and _cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and _cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]


