    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if len(counts) < 2:
        return out

    # The rare non-background color is the marker/special color.
    # The most common non-background color is the base color.
    marker = min(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
    base = max((c for c in counts if c != marker), key=lambda c: counts[c])

    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue

            # If there is a base cell directly above, paint the contiguous
            # vertical base segment above the marker.
            if r > 0 and grid[r - 1][c] == base:
                top = r - 1
                while top > 0 and grid[top - 1][c] == base:
                    top -= 1
                for i in range(top, r):
                    if grid[i][c] == base:
                        out[i][c] = marker

            # Otherwise, if there is a base cell immediately to the left,
            # paint the contiguous vertical base segment starting there
            # and extending upward.
            elif c > 0 and grid[r][c - 1] == base:
                col = c - 1
                top = r
                while top > 0 and grid[top - 1][col] == base:
                    top -= 1
                for i in range(top, r + 1):
                    if grid[i][col] == base:
                        out[i][col] = marker

    return out

