    w = max(len(row) for row in grid)
    if w == 0:
        return [[] for _ in range(h)]

    # Normalise input to a rectangular Python list of ints.
    g = [[0] * w for _ in range(h)]
    global_counts = {}
    for r in range(h):
        row = grid[r]
        for c, val in enumerate(row):
            v = int(val)
            g[r][c] = v
            if v != 0:
                global_counts[v] = global_counts.get(v, 0) + 1

    out = [row[:] for row in g]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Mark background zeros reachable from the border.
    seen = [[False] * w for _ in range(h)]
    q = deque()

    def add_outside(r, c):
        if 0 <= r < h and 0 <= c < w and g[r][c] == 0 and not seen[r][c]:
            seen[r][c] = True
            q.append((r, c))

    for r in range(h):
        add_outside(r, 0)
        add_outside(r, w - 1)

    for c in range(w):
        add_outside(0, c)
        add_outside(h - 1, c)

    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            add_outside(r + dr, c + dc)

    # Find enclosed zero components and fill them.
    hole_seen = [[False] * w for _ in range(h)]

    for i in range(h):
        for j in range(w):
            if g[i][j] != 0 or seen[i][j] or hole_seen[i][j]:
                continue

            stack = [(i, j)]
            hole_seen[i][j] = True
            component = []
            adjacent_colors = {}

            while stack:
                r, c = stack.pop()
                component.append((r, c))

                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < h and 0 <= nc < w):
