                        adjacent_colors[v] = adjacent_colors.get(v, 0) + 1

            if component and adjacent_colors:
                fill_color = max(
                    adjacent_colors.items(),
                    key=lambda kv: (kv[1], global_counts.get(kv[0], 0), -kv[0])
                )[0]

                for r, c in component:
                    out[r][c] = int(fill_color)

    return out

