    from collections import Counter

    if not grid:
        return []

    # Normalise to a list of lists of Python ints.
    out = [[int(v) for v in row] for row in grid]

    h = len(out)
    w = len(out[0]) if h else 0
    if h == 0 or w == 0:
        return out

    # Count non-background colours.
    cnt = Counter()
    row_sum = {}
    for r in range(h):
        for c in range(w):
            v = out[r][c]
            if v != 0:
                cnt[v] += 1
                row_sum[v] = row_sum.get(v, 0) + r

    if len(cnt) < 2:
        return out

    # The marker is the rarer non-zero colour.
    # If tied, prefer the colour occurring lower in the grid.
    marker = min(cnt, key=lambda v: (cnt[v], -row_sum[v], v))

    # The line colour is the more common non-zero colour.
    common = max(
        (v for v in cnt if v != marker),
        key=lambda v: (cnt[v], -row_sum[v], -v)
    )

    if common == marker:
        return out

    active = {common, marker}

    # Work column by column.
    # In each contiguous vertical run of active cells, if it contains a marker,
    # paint all common cells from the top of the run down to the lowest marker.
    for c in range(w):
        r = 0
        while r < h:
            if out[r][c] in active:
                start = r
                lowest_marker = -1

                while r < h and out[r][c] in active:
                    if out[r][c] == marker:
                        lowest_marker = r
                    r += 1

                if lowest_marker != -1:
                    for rr in range(start, lowest_marker + 1):
                        if out[rr][c] == common:
                            out[rr][c] = marker
            else:
                r += 1

    return out

