    if not grid:
        return []

    h = len(grid)
    w = len(grid[0]) if h else 0
    result = [[int(v) for v in row] for row in grid]

    if h == 0 or w == 0:
        return result

    # Flood-fill background (0) cells that touch the border.
    outside = [[False] * w for _ in range(h)]
    q = deque()

    def add_outside(r, c):
        if 0 <= r < h and 0 <= c < w and result[r][c] == 0 and not outside[r][c]:
            outside[r][c] = True
            q.append((r, c))

    for r in range(h):
        add_outside(r, 0)
        add_outside(r, w - 1)
    for c in range(w):
        add_outside(0, c)
        add_outside(h - 1, c)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while q:
        r, c = q.popleft()
        for dr, dc in directions:
            add_outside(r + dr, c + dc)

    # Default fill colour: the most common non-background colour.
    global_counts = Counter()
    for row in grid:
        for v in row:
            if v != 0:
                global_counts[v] += 1
    default_fill = global_counts.most_common(1)[0][0] if global_counts else 4

    # Any remaining 0-cell components are enclosed holes.
    visited = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if result[r][c] == 0 and not outside[r][c] and not visited[r][c]:
                q2 = deque([(r, c)])
                visited[r][c] = True
                cells = []
                adjacent = Counter()

                while q2:
                    cr, cc = q2.popleft()
                    cells.append((cr, cc))

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            val = result[nr][nc]
                            if val == 0:
                                if not outside[nr][nc] and not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    q2.append((nr, nc))
                            else:
                                adjacent[val] += 1

                if adjacent:
                    fill = max(
                        adjacent.items(),
                        key=lambda kv: (kv[1], kv[0] == default_fill, -kv[0])
