            "c0": c0,
            "c1": c1,
            "r0": r0,
            "r1": r1,
            "base": base,
            "sort_key": sort_key,
        })

    if not blocks:
        return [row[:] for row in grid]

    # Sort blocks by marker row from bottom to top.
    ordered = sorted(blocks, key=lambda b: (-b["sort_key"], b["c0"]))
