def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0]) if h else 0

    def is_separator_row(row: list[int]) -> bool:
        non_zero = [v for v in row if v != 0]
        if not non_zero:
            return False

        c = non_zero[0]
        if any(v != c for v in non_zero):
            return False

        # Solid line.
        if all(v == c for v in row):
            return True

        # Alternating line, e.g. 5050... or 0505...
        if 0 in row and all(row[i] != row[i + 1] for i in range(w - 1)):
            return True

        return False

    sep = -1
    for r in range(h):
        if is_separator_row(grid[r]):
            sep = r
            break

    # Fallback (should not be needed for the given tests):
    # pick the most "line-like" full row with a single non-zero colour.
    if sep == -1:
        best = -1
        best_score = -1
        for r in range(h):
            row = grid[r]
            non_zero = [v for v in row if v != 0]
            if not non_zero:
                continue
            c = non_zero[0]
            if any(v != c for v in non_zero):
                continue
            score = len(non_zero)
            if score > best_score:
                best_score = score
                best = r
        sep = best

    out = [[int(v) for v in row] for row in grid]

    if sep != -1:
        above = 0
        below = 0

        for r in range(sep):
            above += sum(1 for v in out[r] if v != 0)

        for r in range(sep + 1, h):
            below += sum(1 for v in out[r] if v != 0)

        # Keep the lighter side; if tied, keep the upper side.
        if below > above:
            for r in range(sep + 1, h):
                for c in range(w):
                    out[r][c] = 0
        else:
            for r in range(sep):
                for c in range(w):
                    out[r][c] = 0

    return out

