        c = 0
        while c < W:
            v = grid[r][c]
            if v == 0:
                c += 1
                continue
            start = c
            while c < W and grid[r][c] == v:
                c += 1
            end = c - 1
            length = end - start + 1
            cnt = color_count.get(v, 0)

            if length >= best_len:
                sides = has_both_sides("H", r, start, end, v)
                if length > best_len:
                    best = ("H", r, start, end, v)
                    best_len = length
                    best_count = cnt
                    best_sides = sides
                else:
                    if (sides and not best_sides) or (
                        sides == best_sides and cnt > best_count
                    ):
                        best = ("H", r, start, end, v)
                        best_len = length
                        best_count = cnt
                        best_sides = sides

    # Vertical runs.
    for c in range(W):
        r = 0
        while r < H:
            v = grid[r][c]
            if v == 0:
                r += 1
                continue
            start = r
            while r < H and grid[r][c] == v:
                r += 1
            end = r - 1
            length = end - start + 1
            cnt = color_count.get(v, 0)

            if length >= best_len:
                sides = has_both_sides("V", c, start, end, v)
                if length > best_len:
                    best = ("V", c, start, end, v)
                    best_len = length
                    best_count = cnt
                    best_sides = sides
                else:
                    if (sides and not best_sides) or (
                        sides == best_sides and cnt > best_count
                    ):
                        best = ("V", c, start, end, v)
                        best_len = length
                        best_count = cnt
                        best_sides = sides

    if best is None:
        return [[int(v) for v in row] for row in out]

    orient, _, line_start, line_end, line_color = best
    line_len = line_end - line_start + 1

    # Collect every non-background cell that is not part of the main line.
    markers = []
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0 and v != line_color:
                markers.append((r, c, v))
                out[r][c] = 0

    if not markers:
        return [[int(v) for v in row] for row in out]

    if orient == "H":
        # Coordinate along the line is column.
        min_t = min(c for _, c, _ in markers)
        max_t = max(c for _, c, _ in markers)
        obj_width = max_t - min_t + 1

        new_min = line_start + (line_len - obj_width) // 2
        shift = new_min - min_t

        for r, c, v in markers:
            nc = c + shift
            if 0 <= nc < W:
                out[r][nc] = v
    else:
        # Coordinate along the line is row.
        min_t = min(r for r, _, _ in markers)
        max_t = max(r for r, _, _ in markers)
        obj_width = max_t - min_t + 1

        new_min = line_start + (line_len - obj_width) // 2
        shift = new_min - min_t

        for r, c, v in markers:
            nr = r + shift
            if 0 <= nr < H:
                out[nr][c] = v

    return [[int(v) for v in row] for row in out]

from __future__ import annotations


def transform(grid: list[list[int]]) -> list[list[int]]:
    # Normalize input to a plain 2D list of ints.
    g = []
    for row in grid:
        if isinstance(row, str):
            g.append([int(ch) for ch in row])
        else:
            try:
                g.append([int(x) for x in row])
            except TypeError:
                g.append([int(row)])

    H = len(g)
    if H == 0:
        return []
    W = len(g[0])
    if W == 0:
        return [list(row) for row in g]

    out = [row[:] for row in g]

    # Count non-background colours.
    color_counts = {}
    for r in range(H):
        for c in range(W):
            v = g[r][c]
            if v != 0:
                color_counts[v] = color_counts.get(v, 0) + 1

    if not color_counts:
        return out

    # Find all straight non-zero runs.
    candidates = []

    for r in range(H):
        c = 0
        while c < W:
            v = g[r][c]
            if v == 0:
                c += 1
                continue
            start = c
            while c < W and g[r][c] == v:
                c += 1
            end = c - 1
            candidates.append(("H", r, start, end, end - start + 1, v))

    for c in range(W):
        r = 0
        while r < H:
            v = g[r][c]
            if v == 0:
                r += 1
                continue
            start = r
            while r < H and g[r][c] == v:
                r += 1
            end = r - 1
            candidates.append(("V", c, start, end, end - start + 1, v))

    if not candidates:
        return out

    def has_other_sides(orient: str, axis: int, start: int, end: int, color: int) -> bool:
        """True if non-background, non-line colours exist on both perpendicular sides."""
        if orient == "H":
            above = False
            for rr in range(axis):
                if not above:
                    for cc in range(W):
                        v = g[rr][cc]
                        if v != 0 and v != color:
                            above = True
                            break

            below = False
            for rr in range(axis + 1, H):
                if not below:
                    for cc in range(W):
                        v = g[rr][cc]
                        if v != 0 and v != color:
                            below = True
                            break

            return above and below
        else:
            left = False
            for cc in range(axis):
                if not left:
                    for rr in range(H):
                        v = g[rr][cc]
                        if v != 0 and v != color:
                            left = True
                            break

            right = False
            for cc in range(axis + 1, W):
                if not right:
                    for rr in range(H):
                        v = g[rr][cc]
                        if v != 0 and v != color:
                            right = True
                            break

            return left and right

    # The line is the longest straight run.  Ties are broken by preferring
    # a run with object pixels on both perpendicular sides, then by colour count.
    max_len = max(cand[4] for cand in candidates)
    best = None
    best_score = None

    for cand in candidates:
        if cand[4] != max_len:
            continue
        orient, axis, start, end, length, color = cand
        score = (
            int(has_other_sides(orient, axis, start, end, color)),
            color_counts.get(color, 0),
        )
        if best_score is None or score > best_score:
            best_score = score
            best = cand

    if best is None:
        best = candidates[0]

    orient, axis, line_start, line_end, line_len, line_color = best

    # The object is every non-background cell that is not the line colour.
    object_cells = []
    for r in range(H):
        for c in range(W):
            v = g[r][c]
            if v != 0 and v != line_color:
                object_cells.append((r, c, v))

    if not object_cells:
        return out

    # Remove the object from its original location.
    for r, c, _ in object_cells:
        out[r][c] = 0

    if orient == "H":
        min_t = min(c for _, c, _ in object_cells)
        max_t = max(c for _, c, _ in object_cells)
        width = max_t - min_t + 1

        # Center the object's horizontal extent on the line.
        # For ambiguous even-length cases, use the rightmost central position.
        target_start = line_start + (line_len - width + 1) // 2
        target_start = max(0, min(target_start, max(0, W - width)))
        shift = target_start - min_t

        for r, c, v in object_cells:
            nc = c + shift
            if 0 <= nc < W:
                out[r][nc] = v
    else:
        min_t = min(r for r, _, _ in object_cells)
        max_t = max(r for r, _, _ in object_cells)
        width = max_t - min_t + 1

        # Center the object's vertical extent on the line.
        # For ambiguous even-length cases, use the bottommost central position.
        target_start = line_start + (line_len - width + 1) // 2
        target_start = max(0, min(target_start, max(0, H - width)))
        shift = target_start - min_t

        for r, c, v in object_cells:
            nr = r + shift
            if 0 <= nr < H:
                out[nr][c] = v

    return [[int(out[r][c]) for c in range(W)] for r in range(H)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    n_rows = len(grid)
    n_cols = len(grid[0])

    # Determine the dominant orientation:
    # longest horizontal run of non-zero cells vs longest vertical run.
    max_h = 0
    for row in grid:
        run = 0
        for v in row:
            if v != 0:
                run += 1
                max_h = max(max_h, run)
            else:
                run = 0

    max_v = 0
    for c in range(n_cols):
        run = 0
        for r in range(n_rows):
            if grid[r][c] != 0:
                run += 1
                max_v = max(max_v, run)
            else:
                run = 0

    # If the dominant lines are horizontal, pack every row to the right.
    # Otherwise, pack every column to the bottom.
    if max_h > max_v:
        out = [[0] * n_cols for _ in range(n_rows)]
        for r in range(n_rows):
            vals = [v for v in grid[r] if v != 0]
            start = n_cols - len(vals)
            for i, v in enumerate(vals):
                out[r][start + i] = v
        return out
    else:
        out = [[0] * n_cols for _ in range(n_rows)]
        for c in range(n_cols):
            vals = [grid[r][c] for r in range(n_rows) if grid[r][c] != 0]
            start = n_rows - len(vals)
            for i, v in enumerate(vals):
                out[start + i][c] = v
        return out

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    # Prefix sums for each color, to count cells of a color in any rectangle O(1).
    pref = [[[0] * (W + 1) for _ in range(H + 1)] for _ in range(10)]
    for r in range(H):
        for c in range(W):
            v = int(grid[r][c])
            for color in range(10):
                pref[color][r + 1][c + 1] = (
                    pref[color][r][c + 1]
                  + pref[color][r + 1][c]
                  - pref[color][r][c]
                )
            pref[v][r + 1][c + 1] += 1

    def rect_sum(color, r1, c1, r2, c2):
        if r1 > r2 or c1 > c2:
            return 0
        p = pref[color]
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]

    # Find components of each color using 8-connectivity.
    comps = [[None] * W for _ in range(H)]
    comp_info = []
    for r0 in range(H):
        for c0 in range(W):
            if comps[r0][c0] is not None:
                continue
            color = grid[r0][c0]
            cid = len(comp_info)
            q = deque([(r0, c0)])
            comps[r0][c0] = cid
            min_r = max_r = r0
            min_c = max_c = c0
            size = 0
            while q:
                r, c = q.popleft()
                size += 1
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if comps[nr][nc] is None and grid[nr][nc] == color:
                                comps[nr][nc] = cid
                                q.append((nr, nc))
            comp_info.append((color, min_r, max_r, min_c, max_c, size))

    candidates = []

    for color in range(10):
        # Skip a color with very few pixels; frames are reasonably large.
        total_color = rect_sum(color, 0, 0, H - 1, W - 1)
        if total_color < 6:
            continue

        for r1 in range(H):
            for r2 in range(r1 + 2, H):
                h = r2 - r1 + 1
                for c1 in range(W):
                    for c2 in range(c1 + 2, W):
                        w = c2 - c1 + 1
                        perim = 2 * (h + w) - 4

                        top = rect_sum(color, r1, c1, r1, c2)
                        bottom = rect_sum(color, r2, c1, r2, c2)
                        left_mid = rect_sum(color, r1 + 1, c1, r2 - 1, c1)
                        right_mid = rect_sum(color, r1 + 1, c2, r2 - 1, c2)

                        left_top = 1 if grid[r1][c1] == color else 0
                        left_bottom = 1 if grid[r2][c1] == color else 0
                        right_top = 1 if grid[r1][c2] == color else 0
                        right_bottom = 1 if grid[r2][c2] == color else 0

                        left_count = left_top + left_mid + left_bottom
                        right_count = right_top + right_mid + right_bottom
                        border_count = top + bottom + left_mid + right_mid
                        corners = left_top + left_bottom + right_top + right_bottom

                        if border_count * 10 < 75 * perim:
                            continue
                        if corners < 3:
                            continue
                        if left_count * 2 < h or right_count * 2 < h:
                            continue
                        if top * 2 < w or bottom * 2 < w:
                            continue

                        # Need at least one horizontal and one vertical consecutive pair.
                        horiz = False
                        if top >= 2 or bottom >= 2:
                            for cc in range(c1, c2):
                                if grid[r1][cc] == color and grid[r1][cc + 1] == color:
                                    horiz = True
                                    break
                                if grid[r2][cc] == color and grid[r2][cc + 1] == color:
                                    horiz = True
                                    break
                        if not horiz:
                            continue

                        vert = False
                        if left_count >= 2 or right_count >= 2:
                            for rr in range(r1, r2):
                                if grid[rr][c1] == color and grid[rr + 1][c1] == color:
                                    vert = True
                                    break
                                if grid[rr][c2] == color and grid[rr + 1][c2] == color:
                                    vert = True
                                    break
                        if not vert:
                            continue

                        # The frame should be hollow: no same-color pixels strictly inside.
                        interior = rect_sum(color, r1 + 1, c1 + 1, r2 - 1, c2 - 1)
                        if interior > 0:
                            continue

                        # The supporting connected component(s) should span exactly this bbox.
                        # This avoids selecting sub-rectangles of a larger frame.
                        seen = set()
                        min_r = max_r = None
                        min_c = max_c = None

                        def absorb(rr, cc):
                            nonlocal min_r, max_r, min_c, max_c
                            cid = comps[rr][cc]
                            if cid is None or cid in seen:
                                return
                            seen.add(cid)
                            _, cr1, cr2, cc1, cc2, _ = comp_info[cid]
                            if min_r is None:
                                min_r, max_r = cr1, cr2
                                min_c, max_c = cc1, cc2
                            else:
                                min_r = min(min_r, cr1)
                                max_r = max(max_r, cr2)
                                min_c = min(min_c, cc1)
                                max_c = max(max_c, cc2)

                        # Absorb components touching the candidate perimeter.
                        for cc in range(c1, c2 + 1):
                            if grid[r1][cc] == color:
                                absorb(r1, cc)
                            if grid[r2][cc] == color:
                                absorb(r2, cc)
                        for rr in range(r1 + 1, r2):
                            if grid[rr][c1] == color:
                                absorb(rr, c1)
                            if grid[rr][c2] == color:
                                absorb(rr, c2)

                        if min_r is None or (min_r, max_r, min_c, max_c) != (r1, r2, c1, c2):
                            continue

                        score = border_count / perim
                        candidates.append((score, border_count, r1, c1, r2, c2, color))

    # Choose a stable set of frames, preferring higher completeness and larger extent.
    candidates.sort(key=lambda x: (x[0], x[1], (x[2] * 1000 + x[3]), x[5], x[4]), reverse=True)
    chosen = []

    for score, border_count, r1, c1, r2, c2, color in candidates:
        bad = False
        for _, _, er1, ec1, er2, ec2, ecolor in chosen:
            if ecolor != color:
                continue
            # Skip if it is contained in an already chosen frame of the same color.
            if er1 <= r1 and ec1 <= c1 and r2 <= er2 and c2 <= ec2:
                if (r1, c1, r2, c2) != (er1, ec1, er2, ec2):
                    bad = True
                    break
            # Skip if it would contain an already chosen frame of the same color
            # and is not strictly better by a large margin.
            if r1 <= er1 and c1 <= ec1 and er2 <= r2 and ec2 <= c2:
                if (r1, c1, r2, c2) != (er1, ec1, er2, ec2):
                    bad = True
                    break
        if not bad:
            chosen.append((score, border_count, r1, c1, r2, c2, color))

    # Background: most frequent color not used as a frame.
    frame_colors = set(ch[6] for ch in chosen)
    counts = [0] * 10
    for row in grid:
        for v in row:
            counts[int(v)] += 1

    background = 0
    best = -1
    for c in range(10):
        if c in frame_colors:
            continue
        if counts[c] > best:
            best = counts[c]
            background = c

    out = [[background] * W for _ in range(H)]

    # Draw chosen frames.  Larger / more complete frames first; final overlaps are
    # unlikely in the ARC instances, but this gives a deterministic result.
    chosen.sort(key=lambda x: (x[0], x[1], x[4] - x[2] + 1, x[5] - x[3] + 1), reverse=True)
    for _, _, r1, c1, r2, c2, color in chosen:
        for c in range(c1, c2 + 1):
            out[r1][c] = color
            out[r2][c] = color
        for r in range(r1, r2 + 1):
            out[r][c1] = color
            out[r][c2] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Count colours and choose the background as the most frequent colour.
    counts = [0] * 10
    for row in grid:
        for v in row:
            counts[int(v)] += 1

    background = max(range(10), key=lambda c: (counts[c], c == 0))

    # Prefix sums for each colour, for O(1) rectangle sums.
    pref = [[None] * 10 for _ in range(H + 1)]
    for c in range(10):
        if counts[c] == 0:
            continue
        p = [[0] * (W + 1) for _ in range(H + 1)]
        for i in range(H):
            pi = p[i]
            pni = p[i + 1]
            row = grid[i]
            for j in range(W):
                pni[j + 1] = pi[j + 1] + pni[j] + (1 if row[j] == c else 0)
        pref = p
    for c in range(10):
        if counts[c] == 0:
            pref[c] = [[0] * (W + 1) for _ in range(H + 1)]

    def rect_sum(c, r1, c1, r2, c2):
        if r1 > r2 or c1 > c2:
            return 0
        p = pref[c]
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]

    candidates = []

    # Find all plausible hollow rectangular frames.
    for color in range(10):
        if color == background or counts[color] < 6:
            continue

        for r1 in range(H - 2):
            for r2 in range(r1 + 2, H):
                height = r2 - r1 + 1

                for c1 in range(W - 2):
                    for c2 in range(c1 + 2, W):
                        width = c2 - c1 + 1
                        perim = 2 * (height + width) - 4

                        # A very small frame needs a reasonably solid outline.
                        if width == 3 and height == 3:
                            need = 8
                        else:
                            need = (3 * perim + 3) // 4  # ceil(0.75 * perim)

                        top = rect_sum(color, r1, c1, r1, c2)
                        if top * 2 < width:
                            continue
                        bottom = rect_sum(color, r2, c1, r2, c2)
                        if bottom * 2 < width:
                            continue

                        left = rect_sum(color, r1, c1, r2, c1)
                        if left * 2 < height:
                            continue
                        right = rect_sum(color, r1, c2, r2, c2)
                        if right * 2 < height:
                            continue

                        tl = grid[r1][c1] == color
                        tr = grid[r1][c2] == color
                        bl = grid[r2][c1] == color
                        br = grid[r2][c2] == color
                        corners = tl + tr + bl + br
                        if corners < 3:
                            continue

                        mid_left = left - int(tl) - int(bl)
                        mid_right = right - int(tr) - int(br)
                        border = top + bottom + mid_left + mid_right
                        if border < need:
                            continue

                        # Interior should not contain the frame colour.
                        interior = rect_sum(color, r1 + 1, c1 + 1, r2 - 1, c2 - 1)
                        if interior > 0:
                            continue

                        candidates.append((
                            border / perim,
                            border,
                            height * width,
                            r1, c1, r2, c2, color
                        ))

    # Keep only maximal candidates for each colour.
    by_color = {}
    for cand in candidates:
        by_color.setdefault(cand[6], []).append(cand)

    kept = []
    for cands in by_color.values():
        # Larger rectangles first, so containing rectangles dominate contained ones.
        cands.sort(key=lambda x: (x[2], x[0], x[1]), reverse=True)
        local_kept = []
        for cand in cands:
            r1, c1, r2, c2 = cand[3], cand[4], cand[5], cand[6]
            contained = False
            for other in local_kept:
                or1, oc1, or2, oc2 = other[3], other[4], other[5], other[6]
                if or1 <= r1 and oc1 <= c1 and r2 <= or2 and c2 <= oc2:
                    contained = True
                    break
            if not contained:
                local_kept.append(cand)
        kept.extend(local_kept)

    # Select non-overlapping frames globally.
    kept.sort(key=lambda x: (x[0], x[2], x[1]), reverse=True)
    frames = []
    for cand in kept:
        r1, c1, r2, c2, color = cand[3], cand[4], cand[5], cand[6], cand[7]
        ok = True
        for fr in frames:
            fr1, fc1, fr2, fc2 = fr[3], fr[4], fr[5], fr[6]
            if not (r2 < fr1 or fr2 < r1 or c2 < fc1 or fc2 < c1):
                ok = False
                break
        if ok:
            frames.append(cand)

    # Final background: most frequent colour not used by a chosen frame.
    frame_colors = set(fr[7] for fr in frames)
    final_background = 0
    best = -1
    for c in range(10):
        if c in frame_colors:
            continue
        if counts[c] > best:
            best = counts[c]
            final_background = c

    out = [[final_background] * W for _ in range(H)]

    for _, _, _, r1, c1, r2, c2, color in frames:
        for c in range(c1, c2 + 1):
            out[r1][c] = color
            out[r2][c] = color
        for r in range(r1, r2 + 1):
            out[r][c1] = color
            out[r][c2] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    n = len(grid)

    # Collect all non-background cells.  The examples use 1 for the object.
    pts = [(r, c) for r in range(n) for c in range(n) if grid[r][c] != 0]
    if not pts:
        return out

    rmin = min(r for r, _ in pts)
    rmax = max(r for r, _ in pts)
    cmin = min(c for _, c in pts)
    cmax = max(c for _, c in pts)

    height = rmax - rmin + 1
    width = cmax - cmin + 1

    # The object is considered to have a horizontal or vertical main axis.
    # For a horizontal main axis, choose top/bottom; for vertical, left/right.
    # The side is chosen by the side with fewer object cells in that half.
    if width >= height:
        top_count = sum(1 for r, _ in pts if r < rmax / 2 + 0.5)
        bottom_count = len(pts) - top_count
        if top_count <= bottom_count:
            row = 0
            for c in range(n):
                out[row][c] = 3
        else:
            row = n - 1
            for c in range(n):
                out[row][c] = 3
    else:
        left_count = sum(1 for _, c in pts if c < cmax / 2 + 0.5)
        right_count = len(pts) - left_count
        if left_count <= right_count:
            col = 0
            for r in range(n):
                out[r][col] = 3
        else:
            col = n - 1
            for r in range(n):
                out[r][col] = 3

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return grid

    n_rows = len(grid)
    n_cols = len(grid[0])

    out = [row[:] for row in grid]

    row_counts = [0] * n_rows
    col_counts = [0] * n_cols

    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0:
                row_counts[r] += 1
                col_counts[c] += 1

    max_row_count = max(row_counts)
    max_col_count = max(col_counts)

    # Candidate rows/columns with maximal density.
    # For rows: choose the one closest to vertical center; tie -> top.
    best_row = None
    for r in range(n_rows):
        if row_counts[r] == max_row_count:
            if best_row is None:
                best_row = r
            else:
                d1 = abs(r - (n_rows - 1) / 2.0)
                d2 = abs(best_row - (n_rows - 1) / 2.0)
                if d1 < d2:
                    best_row = r
                # if equal, keep earlier (higher) row

    best_col = None
    for c in range(n_cols):
        if col_counts[c] == max_col_count:
            if best_col is None:
                best_col = c
            else:
                d1 = abs(c - (n_cols - 1) / 2.0)
                d2 = abs(best_col - (n_cols - 1) / 2.0)
                if d1 < d2:
                    best_col = c
                # if equal, keep earlier (left) column; final tie handled below

    # If column density is strictly greater, use vertical side.
    # Otherwise use horizontal side.
    if max_col_count > max_row_count:
        # If closest-to-center tie included both left and right, prefer right.
        if best_col is not None:
            d_best = abs(best_col - (n_cols - 1) / 2.0)
            if any(
                col_counts[c] == max_col_count and
                abs(c - (n_cols - 1) / 2.0) == d_best and
                c > (n_cols - 1) / 2.0
                for c in range(n_cols)
            ):
                side = "right"
            elif best_col < (n_cols - 1) / 2.0:
                side = "left"
            else:
                side = "right"
        else:
            side = "right"

        if side == "left":
            for r in range(n_rows):
                out[r][0] = 3
        else:
            for r in range(n_rows):
                out[r][n_cols - 1] = 3
    else:
        # If closest-to-center tie included both top and bottom, prefer top.
        if best_row is not None:
            d_best = abs(best_row - (n_rows - 1) / 2.0)
            if any(
                row_counts[r] == max_row_count and
                abs(r - (n_rows - 1) / 2.0) == d_best and
                r < (n_rows - 1) / 2.0
                for r in range(n_rows)
            ):
                side = "top"
            elif best_row < (n_rows - 1) / 2.0:
                side = "top"
            else:
                side = "bottom"
        else:
            side = "top"

        if side == "top":
            for c in range(n_cols):
                out[0][c] = 3
        else:
            for c in range(n_cols):
                out[n_rows - 1][c] = 3

    return out

from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0])
    g = [list(map(int, row)) for row in grid]

    if h == 0 or w == 0:
        return g

    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Flood-fill the outside: any non-3 cell reachable from the border is outside.
    outside = [[False] * w for _ in range(h)]
    q = deque()

    def add_outside(r, c):
        if 0 <= r < h and 0 <= c < w and not outside[r][c] and g[r][c] != 3:
            outside[r][c] = True
            q.append((r, c))

    for c in range(w):
        add_outside(0, c)
        add_outside(h - 1, c)
    for r in range(h):
        add_outside(r, 0)
        add_outside(r, w - 1)

    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                add_outside(nr, nc)

    # Each enclosed non-3 component is a separate interior region.
    comp_id = [[-1] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if comp_id[r][c] != -1:
                continue
            if g[r][c] == 3 or outside[r][c]:
                continue

            idx = len(components)
            cells = []
            counts = [0, 0]
            first = (r, c)
            first4 = None

            dq = deque([(r, c)])
            comp_id[r][c] = idx

            while dq:
                cr, cc = dq.popleft()
                cells.append((cr, cc))

                if g[cr][cc] == 4:
                    p = (cr + cc) & 1
                    counts[p] += 1
                    if first4 is None:
                        first4 = (cr, cc)

                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if (
                        0 <= nr < h and 0 <= nc < w
                        and comp_id[nr][nc] == -1
                        and g[nr][nc] != 3
                        and not outside[nr][nc]
                    ):
                        comp_id[nr][nc] = idx
                        dq.append((nr, nc))

            components.append((cells, counts, first, first4))

    # Global majority parity, used only for empty regions if needed.
    global_counts = [0, 0]
    for _, counts, _, _ in components:
        global_counts[0] += counts[0]
        global_counts[1] += counts[1]

    global_phase = None
    if global_counts[0] + global_counts[1] > 0:
        if global_counts[0] > global_counts[1]:
            global_phase = 0
        elif global_counts[1] > global_counts[0]:
            global_phase = 1
        else:
            for _, _, _, first4 in components:
                if first4 is not None:
                    global_phase = (first4[0] + first4[1]) & 1
                    break

    # Fill missing 4s in the chessboard pattern.
    for cells, counts, first, first4 in components:
        if counts[0] > counts[1]:
            phase = 0
        elif counts[1] > counts[0]:
            phase = 1
        elif first4 is not None:
            phase = (first4[0] + first4[1]) & 1
        elif global_phase is not None:
            phase = global_phase
        else:
            phase = (first[0] + first[1]) & 1

        for r, c in cells:
            if g[r][c] == 0 and ((r + c) & 1) == phase:
                g[r][c] = 4

    return g

import numpy as np
from collections import defaultdict, deque
import heapq

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Allow the compact string representation as well, just in case.
    if grid and isinstance(grid[0], str):
        grid = [[int(ch) for ch in row] for row in grid]
    if not grid:
        return []

    H, W = len(grid), len(grid[0])
    arr = np.array(grid, dtype=int)

    # Connected components over all non-zero pixels (4-neighbor).
    labels = np.full((H, W), -1, dtype=int)
    comps = []

    for r0 in range(H):
        for c0 in range(W):
            if arr[r0, c0] == 0 or labels[r0, c0] != -1:
                continue

            cid = len(comps)
            q = deque([(r0, c0)])
            labels[r0, c0] = cid

            coords = []
            coord_color = {}
            color_coords = defaultdict(list)

            while q:
                r, c = q.popleft()
                col = int(arr[r, c])
                coords.append((r, c))
                coord_color[(r, c)] = col
                color_coords[col].append((r, c))

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if arr[nr, nc] != 0 and labels[nr, nc] == -1:
                            labels[nr, nc] = cid
                            q.append((nr, nc))

            comps.append({
                "coords": coords,
                "set": set(coords),
                "color_coords": dict(color_coords),
                "coord_color": coord_color,
                "size": len(coords),
            })

    if len(comps) < 2:
        return [list(row) for row in grid]

    PAIR_LIMIT = 300_000
    TOP_K = 500

    def generate_candidates(S, T):
        """Generate plausible translation vectors from S to T."""
        counts = defaultdict(int)

        # Prefer matching the same colour, because in all examples the shared
        # part of the two objects uses the same colours.
        for color, t_list in T["color_coords"].items():
            s_list = S["color_coords"].get(color)
            if not s_list or not t_list:
                continue

            prod = len(t_list) * len(s_list)
            if prod <= PAIR_LIMIT:
                sample_t = t_list
            else:
                step = max(1, (prod - 1) // PAIR_LIMIT + 1)
                sample_t = t_list[::step]

            for tr, tc in sample_t:
                for sr, sc in s_list:
                    counts[(tr - sr, tc - sc)] += 1

        if counts:
            return counts

        # Fallback: ignore colour while aligning shapes.
        t_list = T["coords"]
        s_list = S["coords"]
        prod = len(t_list) * len(s_list)
        if prod <= PAIR_LIMIT:
            sample_t = t_list
        else:
            step = max(1, (prod - 1) // PAIR_LIMIT + 1)
            sample_t = t_list[::step]

        for tr, tc in sample_t:
            for sr, sc in s_list:
                counts[(tr - sr, tc - sc)] += 1

        return counts

    def evaluate(S, T, v):
        dr, dc = v
        covered = 0
        S_color = S["coord_color"]
        T_color = T["coord_color"]
        S_set = S["set"]

        for tr, tc in T["coords"]:
            sr, sc = tr - dr, tc - dc
            col = T_color[(tr, tc)]
            if (sr, sc) in S_set and S_color[(sr, sc)] == col:
                covered += 1

        additions = 0
        overlap = 0
        for sr, sc in S["coords"]:
            tr, tc = sr + dr, sc + dc
            if 0 <= tr < H and 0 <= tc < W:
                if (tr, tc) in S_set:
                    overlap += 1
                if arr[tr, tc] == 0:
                    additions += 1

        return covered, additions, overlap

    best_score = None
    best_v = None
    best_source = None
    best_additions = 0

    for i, S in enumerate(comps):
        for j, T in enumerate(comps):
            if i == j:
                continue

            cand_counts = generate_candidates(S, T)
            if not cand_counts:
                continue

            # Keep only the most frequently supported candidates.
            top = heapq.nlargest(TOP_K, cand_counts.items(), key=lambda kv: kv[1])

            for v, cnt in top:
                covered, additions, overlap = evaluate(S, T, v)

                # Need a meaningful alignment, not just one accidental cell.
                if covered < max(1, len(T) // 4):
                    continue

                full = 1 if covered == len(T) else 0
                size_ok = 1 if S["size"] >= T["size"] else 0

                score = (
                    size_ok,
                    full,
                    covered,
                    1 if overlap == 0 else 0,
                    cnt,
                    additions,
                )

                if best_score is None or score > best_score:
                    best_score = score
                    best_v = v
                    best_source = S
                    best_additions = additions

    out = arr.copy()

    if best_v is not None and best_additions > 0:
        dr, dc = best_v
        for r, c in best_source["coords"]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and out[nr, nc] == 0:
                out[nr, nc] = best_source["coord_color"][(r, c)]

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Accept compact string rows too.
    if grid and isinstance(grid[0], str):
        grid = [[int(ch) for ch in row] for row in grid]
    if not grid:
        return []

    arr = np.array(grid, dtype=int)
    H, W = arr.shape

    # --- Identify connected components of non-zero pixels (4-neighbor) ---
    labels = -np.ones((H, W), dtype=int)
    comps = []  # list of (row_min, row_max, col_min, col_max)

    for r0 in range(H):
        for c0 in range(W):
            if arr[r0, c0] == 0 or labels[r0, c0] != -1:
                continue
            cid = len(comps)
            q = deque([(r0, c0)])
            labels[r0, c0] = cid
            rmin = rmax = r0
            cmin = cmax = c0
            while q:
                r, c = q.popleft()
                rmin = min(rmin, r); rmax = max(rmax, r)
                cmin = min(cmin, c); cmax = max(cmax, c)
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W and arr[nr, nc] != 0 and labels[nr, nc] == -1:
                        labels[nr, nc] = cid
                        q.append((nr, nc))
            comps.append((rmin, rmax, cmin, cmax))

    out = arr.copy()

    # Each candidate: one source component (the "left" object) and one target
    # component (the "right" object). period = target.cmin - source.cmin.
    for A in comps:
        rA0, rA1, cA0, cA1 = A
        for B in comps:
            rB0, rB1, cB0, cB1 = B
            if A is B:
                continue
            period = cB0 - cA0
            if period <= 0:
                continue
            if cA1 + period >= W:        # shifted source would run off grid
                continue
            if cB1 + 1 < cA0 + period:    # right object entirely left of target zone
                continue

            # Copy source pixels to the right (shifted by `period`), zeros only.
            for r in range(rA0, rA1 + 1):
                row_changed = False
                for c in range(cA0, cA1 + 1):
                    v = int(arr[r, c])
                    if v != 0:
                        nc = c + period
                        if out[r, nc] == 0:
                            out[r, nc] = v
                            row_changed = True

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    a = [[int(x) for x in row] for row in grid]

    colors = [c for c in range(1, 10) if any(c == v for row in a for v in row)]
    if not colors:
        return a

    def comp_count(mask):
        seen = [[False] * W for _ in range(H)]
        cnt = 0
        for i in range(H):
            for j in range(W):
                if mask[i][j] and not seen[i][j]:
                    cnt += 1
                    stack = [(i, j)]
                    seen[i][j] = True
                    while stack:
                        r, c = stack.pop()
                        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                            if 0 <= nr < H and 0 <= nc < W and mask[nr][nc] and not seen[nr][nc]:
                                seen[nr][nc] = True
                                stack.append((nr, nc))
        return cnt

    def cells_of(col):
        return [(i, j) for i in range(H) for j in range(W) if a[i][j] == col]

    def area(col):
        pts = cells_of(col)
        if not pts:
            return 0
        rs = [p[0] for p in pts]
        cs = [p[1] for p in pts]
        return (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)

    def perimeter_len(pts):
        used = [[False] * W for _ in range(H)]
        for i, j in pts:
            used[i][j] = True
        total = 0
        for i, j in pts:
            for nr, nc in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if not (0 <= nr < H and 0 <= nc < W) or not used[nr][nc]:
                    total += 1
        return total

    def score_frame(col):
        pts = cells_of(col)
        if not pts:
            return -1
        comp = comp_count([[a[i][j] == col for j in range(W)] for i in range(H)])
        ar = area(col)
        cnt = len(pts)
        dens = cnt / ar if ar else 0
        per = perimeter_len(pts)
        return (comp == 1, ar, per, dens)

    def score_line(col):
        pts = cells_of(col)
        if not pts:
            return -1
        comp = comp_count([[a[i][j] == col for j in range(W)] for i in range(H)])
        ar = area(col)
        cnt = len(pts)
        dens = cnt / ar if ar else 0
        return (comp <= 4, ar, dens)

    frame = max(colors, key=score_frame)
    others = [c for c in colors if c != frame]
    if not others:
        return a
    line = max(others, key=score_line)

    # Determine intended frame cells: frame cells plus missing frame cells
    # that are directly adjacent to the line crossing the frame boundary.
    frame_mask = [[a[i][j] == frame for j in range(W)] for i in range(H)]
    line_mask = [[a[i][j] == line for j in range(W)] for i in range(H)]

    def adjacent_to_any(mask, i, j):
        for nr, nc in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= nr < H and 0 <= nc < W and mask[nr][nc]:
                return True
        return False

    restored = [row[:] for row in frame_mask]
    for i in range(H):
        for j in range(W):
            if line_mask[i][j] and adjacent_to_any(frame_mask, i, j):
                restored[i][j] = True

    # If the frame is not closed after simple repair, close small local gaps
    # by filling missing frame cells that separate line pixels from the frame.
    for i in range(H):
        for j in range(W):
            if not restored[i][j] and a[i][j] == 0:
                horiz = (
                    j > 0 and j + 1 < W and
                    restored[i][j - 1] and restored[i][j + 1]
                )
                vert = (
                    i > 0 and i + 1 < H and
                    restored[i - 1][j] and restored[i + 1][j]
                )
                if horiz or vert:
                    if any(
                        line_mask[nr][nc]
                        for nr, nc in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1))
                    ):
                        restored[i][j] = True

    # Flood-fill outside from border cells not occupied by restored frame.
    outside = [[False] * W for _ in range(H)]
    stack = []
    for j in range(W):
        if not restored[0][j]:
            outside[0][j] = True
            stack.append((0, j))
        if not restored[H - 1][j]:
            outside[H - 1][j] = True
            stack.append((H - 1, j))
    for i in range(H):
        if not restored[i][0]:
            outside[i][0] = True
            stack.append((i, 0))
        if not restored[i][W - 1]:
            outside[i][W - 1] = True
            stack.append((i, W - 1))

    while stack:
        r, c = stack.pop()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < H and 0 <= nc < W and not restored[nr][nc] and not outside[nr][nc]:
                outside[nr][nc] = True
                stack.append((nr, nc))

    out = [[0] * W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if restored[i][j]:
                out[i][j] = frame
            elif line_mask[i][j] and not outside[i][j]:
                out[i][j] = line

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])
    g = [[int(v) for v in row] for row in grid]

    def four_neighbors(r, c):
        if r + 1 < H:
            yield r + 1, c
        if r - 1 >= 0:
            yield r - 1, c
        if c + 1 < W:
            yield r, c + 1
        if c - 1 >= 0:
            yield r, c - 1

    def comps(mask):
        seen = [[False] * W for _ in range(H)]
        out = []
        for i in range(H):
            for j in range(W):
                if mask[i][j] and not seen[i][j]:
                    cells = []
                    stack = [(i, j)]
                    seen[i][j] = True
                    while stack:
                        r, c = stack.pop()
                        cells.append((r, c))
                        for nr, nc in four_neighbors(r, c):
                            if mask[nr][nc] and not seen[nr][nc]:
                                seen[nr][nc] = True
                                stack.append((nr, nc))
                    out.append(cells)
        return out

    def fill_region(start, blocked):
        if not (0 <= start[0] < H and 0 <= start[1] < W) or blocked[start[0]][start[1]]:
            return [[False] * W for _ in range(H)]
        seen = [[False] * W for _ in range(H)]
        stack = [start]
        seen[start[0]][start[1]] = True
        while stack:
            r, c = stack.pop()
            for nr, nc in four_neighbors(r, c):
                if not blocked[nr][nc] and not seen[nr][nc]:
                    seen[nr][nc] = True
                    stack.append((nr, nc))
        return seen

    nonzeros = [c for c in range(1, 10) if any(g[i][j] == c for i in range(H) for j in range(W))]
    if len(nonzeros) < 2:
        return g

    best = None

    for frame_color in nonzeros:
        frame_mask = [[g[i][j] == frame_color for j in range(W)] for i in range(H)]
        frame_comps = comps(frame_mask)
        if not frame_comps:
            continue

        for other in comps(frame_mask):
            cells = set(other)
            if len(cells) < 4:
                continue

            # Candidate frame cells: original frame pixels plus line pixels that
            # sit in gaps of a single frame component.
            frame_candidate = [[False] * W for _ in range(H)]
            for i, j in cells:
                frame_candidate[i][j] = True

            # Only accept small local gap-fillings (usually 1-2 pixels) whose
            # addition keeps the frame component closed enough to enclose area.
            for other_color in nonzeros:
                if other_color == frame_color:
                    continue
                line_mask = [[g[i][j] == other_color for j in range(W)] for i in range(H)]
                candidates = []
                for i, j in cells:
                    pass
                gap_cells = []
                for i in range(H):
                    for j in range(W):
                        if line_mask[i][j]:
                            # A line pixel can complete the frame if it is adjacent
                            # to at least two frame pixels of this component.
                            cnt = 0
                            for nr, nc in four_neighbors(i, j):
                                if (nr, nc) in cells:
                                    cnt += 1
                            if cnt >= 2:
                                gap_cells.append((i, j))

                for take in [False] + [True]:
                    candidate = [row[:] for row in frame_candidate]
                    if take:
                        for i, j in gap_cells:
                            candidate[i][j] = True
                    blocked = [[candidate[i][j] for j in range(W)] for i in range(H)]

                    # Try to find an enclosed region not touching the border.
                    interior = None
                    for i in range(H):
                        for j in range(W):
                            if not blocked[i][j] and not any(
                                blocked[x][y] for x, y in ((0, j), (H - 1, j), (i, 0), (i, W - 1))
                            ) and not blocked[i][j]:
                                pass
                    # More directly: flood from all border non-blocked cells.
                    outside_blocked = [row[:] for row in blocked]
                    outside_seen = [[False] * W for _ in range(H)]
                    stack = []
                    for j in range(W):
                        if not blocked[0][j]:
                            outside_seen[0][j] = True
                            stack.append((0, j))
                        if not blocked[H - 1][j]:
                            outside_seen[H - 1][j] = True
                            stack.append((H - 1, j))
                    for i in range(H):
                        if not blocked[i][0]:
                            outside_seen[i][0] = True
                            stack.append((i, 0))
                        if not blocked[i][W - 1]:
                            outside_seen[i][W - 1] = True
                            stack.append((i, W - 1))
                    while stack:
                        r, c = stack.pop()
                        for nr, nc in four_neighbors(r, c):
                            if not blocked[nr][nc] and not outside_seen[nr][nc]:
                                outside_seen[nr][nc] = True
                                stack.append((nr, nc))

                    inside_line = []
                    for i, j in line_mask and [[g[i][j] == other_color for j in range(W)] for i in range(H)]:
                        if g[i][j] == other_color and not outside_seen[i][j]:
                            inside_line.append((i, j))

                    if not inside_line:
                        continue

                    # Score this interpretation.
                    # Prefer a frame component that is large, closed, and whose
                    # filled frame is not too many added pixels.
                    added = len(gap_cells) if take else 0
                    score = (
                        len(inside_line),
                        len(cells),
                        -added,
                        frame_color == min(nonzeros),
                    )
                    cand_out = [[0] * W for _ in range(H)]
                    for i, j in range(H) if False else [(i, j) for i in range(H) for j in range(W)]:
                        if candidate[i][j]:
                            cand_out[i][j] = frame_color
                    for i, j in inside_line:
                        cand_out[i][j] = other_color

                    # Keep pixels already matching a frame component that were not
                    # part of the chosen component only if they do not overlap.
                    for i in range(H):
                        for j in range(W):
                            if not candidate[i][j] and frame_mask[i][j]:
                                cand_out[i][j] = frame_color

                    if best is None or score > best[0]:
                        best = (score, cand_out, frame_color, other_color, candidate, inside_line)

    if best is None:
        # Fallback: simple crop to the largest non-zero component's bounding box.
        return g

    _, out, frame_color, other_color, frame_mask, inside_line = best

    # Clean up: ensure output only contains frame and kept line colors,
    # and does not accidentally keep line pixels outside the closed frame.
    final = [[0] * W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if frame_mask[i][j]:
                final[i][j] = frame_color
    for i, j in inside_line:
        final[i][j] = other_color

    # If this interpretation left too many line pixels outside, use a safer
    # interior flood with the same completed frame.
    blocked = [row[:] for row in frame_mask]
    outside_seen = [[False] * W for _ in range(H)]
    stack = []
    for j in range(W):
        if not blocked[0][j]:
            outside_seen[0][j] = True
            stack.append((0, j))
        if not blocked[H - 1][j]:
            outside_seen[H - 1][j] = True
            stack.append((H - 1, j))
    for i in range(H):
        if not blocked[i][0]:
            outside_seen[i][0] = True
            stack.append((i, 0))
        if not blocked[i][W - 1]:
            outside_seen[i][W - 1] = True
            stack.append((i, W - 1))
    while stack:
        r, c = stack.pop()
        for nr, nc in four_neighbors(r, c):
            if not blocked[nr][nc] and not outside_seen[nr][nc]:
                outside_seen[nr][nc] = True
                stack.append((nr, nc))

    for i in range(H):
        for j in range(W):
            if g[i][j] == other_color and not outside_seen[i][j]:
                final[i][j] = other_color
            elif g[i][j] == frame_color:
                final[i][j] = frame_color

    return final

import sys
from collections import deque

def _inside_closed_8(grid, frame, h, w):
    """Return True for cells strictly inside an 8-connected closed frame."""
    outside = [[False]*w for _ in range(h)]
    q = deque()

    def add(r, c):
        if 0 <= r < h and 0 <= c < w and not outside[r][c] and grid[r][c] != frame:
            outside[r][c] = True
            q.append((r, c))

    for r in range(h):
        add(r, 0)
        add(r, w-1)
    for c in range(w):
        add(0, c)
        add(h-1, c)

    while q:
        r, c = q.popleft()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                add(r+dr, c+dc)

    inside = [[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            inside[r][c] = (not outside[r][c]) and grid[r][c] != frame
    return inside

def _fill_frame_gaps(out, frame, line, h, w):
    """Fill frame gaps that lie on straight runs between two frame cells."""
    candidates = []
    for r in range(h):
        for c in range(w):
            if out[r][c] != line:
                continue
            # horizontal gap
            if 0 <= c-1 < w and 0 <= c+1 < w:
                if out[r][c-1] == frame and out[r][c+1] == frame:
                    candidates.append((r, c))
            # vertical gap
            if 0 <= r-1 < h and 0 <= r+1 < h:
                if out[r-1][c] == frame and out[r+1][c] == frame:
                    candidates.append((r, c))

    for r, c in candidates:
        out[r][c] = frame

def _fill_diagonal_gap(out, frame, line, h, w):
    """
    Fill a line-colored cell if it completes a diagonal 8-connected frame path.
    This is used for rotated-frame shapes where a gap is surrounded diagonally.
    """
    candidates = []
    for r in range(h):
        for c in range(w):
            if out[r][c] != line:
                continue
            # Look for two frame cells diagonally touching this cell in opposite
            # diagonal directions, which indicates a missing point on an 8-path.
            # Example: (r-1,c-1) and (r+1,c+1), or (r-1,c+1) and (r+1,c-1).
            if (r-1 >= 0 and c-1 >= 0 and r+1 < h and c+1 < w and
                out[r-1][c-1] == frame and out[r+1][c+1] == frame):
                candidates.append((r, c))
            if (r-1 >= 0 and c+1 < w and r+1 < h and c-1 >= 0 and
                out[r-1][c+1] == frame and out[r+1][c-1] == frame):
                candidates.append((r, c))

    # Prefer the smallest set of such cells whose filling yields an 8-connected
    # closed loop with an interior.  In these puzzles at most a couple exist.
    if not candidates:
        return out

    # Try filling all, then if that overfills and leaves no interior, try each individually.
    test = [row[:] for row in out]
    for r, c in candidates:
        test[r][c] = frame
    if _has_interior(test, frame, h, w):
        out = test
        return out

    best = None
    best_score = -1
    # try each single candidate
    for idx, (r, c) in enumerate(candidates):
        test = [row[:] for row in out]
        test[r][c] = frame
        if _has_interior(test, frame, h, w):
            score = 1
            if score > best_score:
                best_score = score
                best = test
    if best is not None:
        out = best
    return out

def _has_interior(grid, frame, h, w):
    inside = _inside_closed_8(grid, frame, h, w)
    cnt = sum(1 for r in range(h) for c in range(w) if inside[r][c])
    return cnt > 0

def _components(cells):
    cells = set(cells)
    seen = set()
    comps = []
    for s in cells:
        if s in seen:
            continue
        q = deque([s])
        seen.add(s)
        comp = []
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nb = (r+dr, c+dc)
                    if nb in cells and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
        comps.append(comp)
    return comps

def _frame_score(grid, color, h, w):
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not cells:
        return -10**9
    comps = _components(cells)
    # We want one large 8-connected component with many cells.
    if not comps:
        return -10**9
    largest = max(len(x) for x in comps)
    score = largest
    # Bonus if it spans a sizable bounding box and has a plausible closed shape.
    for comp in comps:
        if len(comp) != largest:
            continue
        rs = [r for r, _ in comp]
        cs = [c for _, c in comp]
        hh = max(rs) - min(rs) + 1
        ww = max(cs) - min(cs) + 1
        if hh >= 3 and ww >= 3:
            score += 5
        break
    return score

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})
    if len(colors) != 2:
        return [row[:] for row in grid]

    a, b = colors
    # Choose frame as the color with the better large connected-component score.
    if _frame_score(grid, a, h, w) >= _frame_score(grid, b, h, w):
        frame, line = a, b
    else:
        frame, line = b, a

    out = [row[:] for row in grid]

    # Iteratively fill obvious orthogonal and diagonal gaps.
    for _ in range(6):
        before = [row[:] for row in out]
        _fill_frame_gaps(out, frame, line, h, w)
        _fill_diagonal_gap(out, frame, line, h, w)
        if out == before:
            break

    # If still no interior, try forcing a few line cells that are diagonal
    # bridge candidates even if not explicitly filled above.
    if not _has_interior(out, frame, h, w):
        candidates = []
        for r in range(h):
            for c in range(w):
                if out[r][c] != line:
                    continue
                diag_pairs = []
                if r-1 >= 0 and c-1 >= 0 and r+1 < h and c+1 < w:
                    diag_pairs.append(((r-1,c-1),(r+1,c+1)))
                if r-1 >= 0 and c+1 < w and r+1 < h and c-1 >= 0:
                    diag_pairs.append(((r-1,c+1),(r+1,c-1)))
                for p1, p2 in diag_pairs:
                    if out[p1[0]][p1[1]] == frame and out[p2[0]][p2[1]] == frame:
                        candidates.append((r, c))
                        break
        for r, c in candidates:
            out[r][c] = frame
            if _has_interior(out, frame, h, w):
                break

    # Clip line color to the interior of the completed frame.
    inside = _inside_closed_8(out, frame, h, w)
    for r in range(h):
        for c in range(w):
            if out[r][c] == line and not inside[r][c]:
                out[r][c] = 0

    return out

from collections import deque

def _clone(grid):
    return [row[:] for row in grid]

def _inside_closed_4(grid, frame, h, w):
    """
    Mark non-frame cells inside an 8-connected frame by 4-connectivity.
    Outside cells are 4-connected non-frame cells reachable from the border.
    """
    outside = [[False] * w for _ in range(h)]
    q = deque()

    def try_push(r, c):
        if 0 <= r < h and 0 <= c < w and not outside[r][c] and grid[r][c] != frame:
            outside[r][c] = True
            q.append((r, c))

    for c in range(w):
        try_push(0, c)
        try_push(h - 1, c)
    for r in range(h):
        try_push(r, 0)
        try_push(r, w - 1)

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not outside[nr][nc] and grid[nr][nc] != frame:
                outside[nr][nc] = True
                q.append((nr, nc))

    inside = [[(not outside[r][c]) and grid[r][c] != frame for c in range(w)] for r in range(h)]
    return inside

def _components_8(cells):
    cells = set(cells)
    seen = set()
    comps = []
    for s in cells:
        if s in seen:
            continue
        q = deque([s])
        seen.add(s)
        comp = []
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nb = (r + dr, c + dc)
                    if nb in cells and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
        comps.append(comp)
    return comps

def _frame_score(grid, color, h, w):
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not cells:
        return -10**9
    comps = _components_8(cells)
    if not comps:
        return -10**9
    best = -10**9
    for comp in comps:
        size = len(comp)
        rs = [r for r, _ in comp]
        cs = [c for _, c in comp]
        hh = max(rs) - min(rs) + 1
        ww = max(cs) - min(cs) + 1
        score = size
        if hh >= 3 and ww >= 3:
            score += 6
        # Prefer a closed-ish loop: many cells along bounding-box perimeter.
        perimeter = 2 * (hh + ww)
        if perimeter > 0:
            score += min(10, int(10 * size / perimeter))
        if score > best:
            best = score
    return best

def _fill_obvious_frame_gaps(out, frame, line, h, w):
    """
    Fill line-colored cells that are clearly on the completed frame:
    - between two frame cells orthogonally,
    - at a diagonal bridge between two frame cells in opposite diagonal directions,
    - at convex corners suggested by two adjacent frame cells.
    """
    changed = True
    for _ in range(8):
        if not changed:
            break
        changed = False

        # Orthogonal one-cell gaps.
        for r in range(h):
            for c in range(w):
                if out[r][c] != line:
                    continue
                if c > 0 and c + 1 < w and out[r][c - 1] == frame and out[r][c + 1] == frame:
                    out[r][c] = frame
                    changed = True
        for r in range(h):
            for c in range(w):
                if out[r][c] != line:
                    continue
                if r > 0 and r + 1 < h and out[r - 1][c] == frame and out[r + 1][c] == frame:
                    out[r][c] = frame
                    changed = True

        # Diagonal bridges: (r-1,c-1) and (r+1,c+1), or (r-1,c+1) and (r+1,c-1).
        for r in range(h):
            for c in range(w):
                if out[r][c] != line:
                    continue
                if (r > 0 and c > 0 and r + 1 < h and c + 1 < w and
                    out[r - 1][c - 1] == frame and out[r + 1][c + 1] == frame):
                    out[r][c] = frame
                    changed = True
                if (r > 0 and c + 1 < w and r + 1 < h and c > 0 and
                    out[r - 1][c + 1] == frame and out[r + 1][c - 1] == frame):
                    out[r][c] = frame
                    changed = True

        # Convex corners: two frame cells diagonally adjacent around the missing cell.
        # Patterns like:
        # X .      . .      . .      . .
        # . X      X .      . X      X .
        for r in range(h):
            for c in range(w):
                if out[r][c] != line:
                    continue
                # top-left corner: frame at (r-1,c) and (r,c-1)
                if r > 0 and c > 0 and out[r - 1][c] == frame and out[r][c - 1] == frame:
                    out[r][c] = frame
                    changed = True
                # top-right corner
                if r > 0 and c + 1 < w and out[r - 1][c] == frame and out[r][c + 1] == frame:
                    out[r][c] = frame
                    changed = True
                # bottom-left corner
                if r + 1 < h and c > 0 and out[r + 1][c] == frame and out[r][c - 1] == frame:
                    out[r][c] = frame
                    changed = True
                # bottom-right corner
                if r + 1 < h and c + 1 < w and out[r + 1][c] == frame and out[r][c + 1] == frame:
                    out[r][c] = frame
                    changed = True

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})
    if len(colors) != 2:
        return _clone(grid)

    a, b = colors
    if _frame_score(grid, a, h, w) >= _frame_score(grid, b, h, w):
        frame, line = a, b
    else:
        frame, line = b, a

    out = _clone(grid)
    _fill_obvious_frame_gaps(out, frame, line, h, w)

    inside = _inside_closed_4(out, frame, h, w)

    for r in range(h):
        for c in range(w):
            if out[r][c] == line and not inside[r][c]:
                out[r][c] = 0

    # Special topological refinement for single-pixel diagonal frames:
    # If a line cell lies exactly in the narrow “neck” created by two opposite
    # diagonal frame cells and it is not needed to connect an inside line segment
    # to the frame, suppress the farthest such isolated interior pixel.
    # This avoids keeping a stray pixel in the one-cell gap of a diamond vertex.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if out[r][c] != line:
                continue
            if not inside[r][c]:
                continue

            # Is this cell between two diagonal frame corners in the horizontal direction?
            # Pattern: frame at (r-1,c+1) and (r+1,c+1), with line at (r,c), and the
            # cell to its right is line or frame.
            if out[r - 1][c + 1] == frame and out[r + 1][c + 1] == frame:
                # If the cell to the left is not line, this is a one-cell inward protrusion
                # that can be removed while preserving the visible inner segment.
                if c - 1 < 0 or out[r][c - 1] != line:
                    out[r][c] = 0

            # Same pattern mirrored vertically.
            if out[c?]:
                pass

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    if h == 0 or w == 0:
        return grid

    # Find 8-connected components of non-zero cells
    visited = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                color = grid[r][c]
                cells = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in [-1, 0, 1]:
                        for dx in [-1, 0, 1]:
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not visited[ny][nx] and grid[ny][nx] == color:
                                    visited[ny][nx] = True
                                    stack.append((ny, nx))
                components.append({'cells': cells, 'color': color})

    if not components:
        return [[0] * w for _ in range(h)]

    # Largest component is the fixed anchor
    anchor = max(components, key=lambda comp: len(comp['cells']))

    out = [[0] * w for _ in range(h)]
    placed = set()

    for r, c in anchor['cells']:
        out[r][c] = anchor['color']
        placed.add((r, c))

    # Process other components bottom-to-top
    others = [comp for comp in components if comp is not anchor]
    others.sort(key=lambda comp: min(r for r, c in comp['cells']), reverse=True)

    for comp in others:
        cells = list(comp['cells'])
        color = comp['color']

        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        # Only fall if there's a placed cell below with horizontal overlap
        has_below = any(
            pr > max_r and min_c <= pc <= max_c
            for (pr, pc) in placed
        )

        if not has_below:
            for r, c in cells:
                out[r][c] = color
                placed.add((r, c))
            continue

        # Fall until blocked
        while True:
            new_cells = [(r + 1, c) for r, c in cells]
            can_fall = all(
                nr < h and (nr, nc) not in placed
                for (nr, nc) in new_cells
            )
            if not can_fall:
                break
            cells = new_cells

        for r, c in cells:
            out[r][c] = color
            placed.add((r, c))

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    fg = g > 0
    if not fg.any():
        return [[0] * W for _ in range(H)]

    # Work on the largest connected foreground component (4-neighbor).
    comp = np.zeros((H, W), dtype=int)
    best_id, best_size = 0, 0
    for i in range(H):
        for j in range(W):
            if fg[i, j] and comp[i, j] == 0:
                stack = [(i, j)]
                comp[i, j] = 1
                size = 0
                while stack:
                    y, x = stack.pop()
                    size += 1
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and fg[ny, nx] and comp[ny, nx] == 0:
                            comp[ny, nx] = 1
                            stack.append((ny, nx))
                if size > best_size:
                    best_size = size
                    main = comp.copy()
                    main[main != 1] = 0
                else:
                    comp[comp == 1] = 0

    # Fill enclosed background holes of that component (4-neighbor background).
    fill = main.copy()
    if best_size:
        from collections import deque
        q = deque()
        for i in range(H):
            for j in (0, W - 1):
                if not main[i, j]:
                    q.append((i, j))
                    fill[i, j] = -1
        for j in range(W):
            for i in (0, H - 1):
                if not main[i, j] and fill[i, j] == 0:
                    q.append((i, j))
                    fill[i, j] = -1

        while q:
            y, x = q.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W and not main[ny, nx] and fill[ny, nx] == 0:
                    fill[ny, nx] = -1
                    q.append((ny, nx))

        # Holes are 0 cells not reached from the border.
        holes = (main == 0) & (fill == 0)
        out = main | holes
    else:
        out = np.zeros((H, W), dtype=bool)

    # Remove thin one-cell spurs from the filled outline.
    # A spur is a 3-cell straight line ending in a single terminal pixel.
    removed = np.zeros((H, W), dtype=bool)
    for y in range(H):
        for x in range(W):
            if not out[y, x]:
                continue
            # Vertical spur
            if y > 0 and y + 1 < H and x > 0 and x < W - 1:
                if out[y, x - 1] and out[y - 1, x] and out[y + 1, x] and not out[y + 1, x - 1] and not out[y + 1, x + 1] and not out[y + 1, y - 1] if False else True:
                    pass

    # Simpler and safer spur removal:
    changed = True
    while changed:
        changed = False
        for y in range(H):
            for x in range(W):
                if not out[y, x]:
                    continue

                # Terminal vertical pixel: its only foreground neighbors in the
                # 3x3 neighborhood are directly above and below.
                if y > 0 and y + 1 < H:
                    if out[y - 1, x] and out[y + 1, x]:
                        ok = True
                        for dy in (-1, 0, 1):
                            for dx in (-1, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < H and 0 <= nx < W and out[ny, nx]:
                                    if not (dy == -1 and dx == 0) and not (dy == 1 and dx == 0):
                                        ok = False
                        if ok and not out[y, x - 1] and not out[y, x + 1]:
                            out[y, x] = False
                            changed = True
                            break

                # Terminal horizontal pixel: its only foreground neighbors in the
                # 3x3 neighborhood are directly left and right.
                if x > 0 and x + 1 < W:
                    if out[y, x - 1] and out[y, x + 1]:
                        ok = True
                        for dy in (-1, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < H and 0 <= nx < W and out[ny, nx]:
                                    if not (dy == 0 and dx == -1) and not (dy == 0 and dx == 1):
                                        ok = False
                        if ok and not out[y - 1, x] and not out[y + 1, x]:
                            out[y, x] = False
                            changed = True
                            break
            if changed:
                break

    out = out.astype(int)
    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.asarray(grid, dtype=int)
    h, w = g.shape

    if not (g > 0).any():
        return [row[:] for row in grid]

    color = int(g[(g > 0).nonzero()][0][0])

    fg = (g == color)

    # Flood-fill all background regions that touch the border.
    outside = np.zeros((h, w), dtype=bool)
    q = deque()

    def add_bg(y, x):
        if 0 <= y < h and 0 <= x < w and not fg[y, x] and not outside[y, x]:
            outside[y, x] = True
            q.append((y, x))

    for y in range(h):
        add_bg(y, 0)
        add_bg(y, w - 1)
    for x in range(w):
        add_bg(0, x)
        add_bg(h - 1, x)

    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < h and 0 <= nx < w and not fg[ny, nx] and not outside[ny, nx]:
                outside[ny, nx] = True
                q.append((ny, nx))

    # Everything not foreground and not outside is an enclosed hole.
    holes = (~fg) & (~outside)

    # Fill enclosed holes.
    filled = fg | holes

    # Remove one-cell dead-end protrusions (iterated skeleton pruning).
    removed = np.zeros((h, w), dtype=bool)
    changed = True
    while changed:
        changed = False
        for y in range(h):
            for x in range(w):
                if not filled[y, x] or removed[y, x]:
                    continue

                # Count valid foreground neighbours after previously removed cells.
                neigh = []
                deg = 0
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and filled[ny, nx] and not removed[ny, nx]:
                        neigh.append((ny, nx))
                        deg += 1

                if deg == 1:
                    removed[y, x] = True
                    changed = True

    ans = filled & (~removed)
    ans = ans.astype(int) * color

    return ans.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0

    out = [[0] * w for _ in range(h)]
    colors = set()
    for row in grid:
        for v in row:
            if v != 0:
                colors.add(v)

    def in_grid(r: int, c: int) -> bool:
        return 0 <= r < h and 0 <= c < w

    def get(r: int, c: int) -> int:
        return grid[r][c] if in_grid(r, c) else 0

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue

        # Find all maximal diagonal runs (slope -1 and slope +1).
        runs = []

        used = set()

        # slope -1: (r, c) -> (r+1, c-1), constant r + c
        for r, c in cells:
            if (r, c) in used:
                continue
            # move to the start of this diagonal run
            nr, nc = r, c
            while in_grid(nr - 1, nc + 1) and grid[nr - 1][nc + 1] == color:
                nr -= 1
                nc += 1
            run = []
            rr, cc = nr, nc
            while in_grid(rr, cc) and grid[rr][cc] == color:
                run.append((rr, cc))
                used.add((rr, cc))
                rr += 1
                cc -= 1
            if len(run) >= 2:
                runs.append(run)

        # slope +1: (r, c) -> (r+1, c+1), constant r - c
        used = set()
        for r, c in cells:
            if (r, c) in used:
                continue
            # move to the start of this diagonal run
            nr, nc = r, c
            while in_grid(nr - 1, nc - 1) and grid[nr - 1][nc - 1] == color:
                nr -= 1
                nc -= 1
            run = []
            rr, cc = nr, nc
            while in_grid(rr, cc) and grid[rr][cc] == color:
                run.append((rr, cc))
                used.add((rr, cc))
                rr += 1
                cc += 1
            if len(run) >= 2:
                runs.append(run)

        # Keep only runs that are on the exterior boundary:
        # at least one cell in the run has an orthogonal background neighbour.
        for run in runs:
            boundary = False
            for r, c in run:
                if not in_grid(r - 1, c) or grid[r - 1][c] == 0:
                    boundary = True
                    break
                if not in_grid(r + 1, c) or grid[r + 1][c] == 0:
                    boundary = True
                    break
                if not in_grid(r, c - 1) or grid[r][c - 1] == 0:
                    boundary = True
                    break
                if not in_grid(r, c + 1) or grid[r][c + 1] == 0:
                    boundary = True
                    break
            if boundary:
                for r, c in run:
                    out[r][c] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0]) if grid[0] else 0

    out = [[0] * w for _ in range(h)]
    stats = {}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            u = r + c
            v = r - c
            if color not in stats:
                stats[color] = [u, u, v, v]
            else:
                s = stats[color]
                if u < s[0]:
                    s[0] = u
                if u > s[1]:
                    s[1] = u
                if v < s[2]:
                    s[2] = v
                if v > s[3]:
                    s[3] = v

    def draw_u_side(u, vmin, vmax, color):
        r_start = max(0, u - w + 1)
        r_end = min(h - 1, u)
        for r in range(r_start, r_end + 1):
            c = u - r
            if vmin <= r - c <= vmax:
                out[r][c] = color

    def draw_v_side(v, umin, umax, color):
        r_start = max(0, v)
        r_end = min(h - 1, umax + v)
        for r in range(r_start, r_end + 1):
            c = r - v
            if umin <= r + c <= umax:
                out[r][c] = color

    for color in sorted(stats):
        u_min, u_max, v_min, v_max = stats[color]
        u_len = u_max - u_min
        v_len = v_max - v_min

        if v_len > u_len:
            draw_u_side(u_min, v_min, v_max, color)
            draw_u_side(u_max, v_min, v_max, color)
        elif u_len > v_len:
            draw_v_side(v_min, u_min, u_max, color)
            draw_v_side(v_max, u_min, u_max, color)
        else:
            draw_u_side(u_min, v_min, v_max, color)
            draw_u_side(u_max, v_min, v_max, color)

    return out
